/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20161012-4","meetingId":"h28-c-settlement","date":"2016年10月12日","dateIso":"2016-10-12","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を153件整理しています。","topics":[{"id":"topic-01","title":"◯こんの委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２７年度品川区一般会計歳入歳出決算","agenda":"◯こんの委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２７年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"１４３ページの予防接種費、それから１４６ページの乳児健康診査、それから１５０ページの資源回収事業についてお伺いいたします。１０月から定期接種になったＢ型肝炎ワクチンについてお伺いいたします。","respondent":"舟木保健予防課長","answer":"では、１０月から定期接種化されたＢ型肝炎ワクチンについてご説明いたします。Ｂ型肝炎につきましては、国のほうで広く接種が望ましいワクチンということで定められておりまして、検討が進められていました。","id":"exchange-001"},{"speaker":"沢田委員","kind":"確認","question":"これは医療機関も区民もとてもわかりにくいと思いますし、間違えないように、具体的には区としてどのような対策をとられているのでしょうか。６カ月以降の赤ちゃんに関しては接種にお金がかかる人とかからない人が出てくるので、改めて確認したいと求めました。","respondent":"舟木保健予防課長","answer":"対象、全額、費用を区のほうで補助するという形で実施することになっております。お問い合わせがあれば、こちらのほうでもきちんと対応しているところです。","id":"exchange-002"},{"speaker":"沢田委員","kind":"意見","question":"厚生労働省から業務改善命令を受けていて、日本脳炎のワクチンもここがつくっているのですけれども、供給がとまってしまっているという状況です。品川区としてはどう捉えているのか、対応をお考えなのか、説明を求めました。","respondent":"舟木保健予防課長","answer":"化血研のワクチンの件については、こちらも厚生労働省から、こういう形で報道が出たということで把握はしております。それを集めて、東京都あるいは国のほうに上げて、意見を言っているところです。","id":"exchange-003"},{"speaker":"沢田委員","kind":"確認","question":"続きまして、１４６ページの乳児健康診査について、新生児聴覚検査についてお伺いしたいと思います。現在、品川区では、区民の出産に関して出産場所や施設についてのデータなどをお持ちでしょうか、確認したいと求めました。","respondent":"太田品川保健センター所長","answer":"出産場所については、４カ月健診および、すくすく赤ちゃん訪問で確認しております。６月から７月にかけて４カ月健診を受診した方に対して、区内での出産が三、四割ということがわかっております。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"区内で３割から４割ということですけれども、新生児聴覚検査は品川区だけで対応できる問題ではないということだと思います。品川区から都のほうに強く働きかけを行っていただきたいと思うのですけれども、こういったことのお考えを説明するよう求めました。","respondent":"川島健康課長","answer":"保健衛生部長会においての検討が今始まったところですので、その推移を見守って、都内全域でできるような仕組みの構築に向けて注視していきたいと考えております。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"現在、母子手帳の記載だと、８割以上の健診受診者は聴覚検査を受けているとなっているそうです。新生児聴覚検査が行われなかった子どもに対して、現在、品川区ではどのように対応されているのか教えてほしいと求めました。","respondent":"太田品川保健センター所長","answer":"もし入院中に検査を希望しなかったという方につきましては、生後２カ月までであれば、東芝病院のほうで、ＯＡＥの検査ですが、行ってくださるということを確認しております。","id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"今、品川区の１歳未満の聴覚障害児の数と、その療育支援についてどのようなことを行っているのかをお聞かせください。この間の親に寄り添って精神的負担を和らげて、品川区は現在どのような体制で聴覚障害児の支援を行っているのか、その概要を説明するよう求めました。","respondent":"中山障害者福祉課長","answer":"聴覚障害の方への支援ということですけれども、新生児につきましては、特にこちらでご相談があって初めてということになります。つけた後の可否というのもわからないので、生まれたばかりのお子さんに対しての支援というところでは、現在できていないところです。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問","question":"それと、ちょっともう時間がなくなってしまうので、１歳児未満の数だけ後で教えてほしいと求めました。やはり地域ごとに大分やり方に違いが出てきているのかと思うのですけれど、その状況について一言説明を求めました。","respondent":"太田品川保健センター所長、小林品川区清掃事務所長","answer":"新生児聴覚スクリーニングで、精密検査が必要となる方は０.４％ということですので、品川区では年間３人から７人いらっしゃるということになると思います。廃棄物の集積所であったところを、可燃・不燃が各戸収集になった結果、残った資源について資源ステーションで回収しています。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問・要望","question":"資源ステーション、そしてまた各戸回収でやるという、どちらにしろしっかりとした体制でやってほしいと求めました。ちょっと時間がないので、また今度聞こうと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"つる委員","kind":"提案","question":"こうした状況を受けて、財務省の財政制度等審議会で医療費の抑制策も提案されるという全国的な事態というところであります。そこで、「私の散歩道」の改訂、またウォーキングマップアプリが、どの程度、区民の皆さんの健康づくりに貢献しているか説明を求めました。","respondent":"川島健康課長","answer":"あわせましてウォーキングマップのアプリも公開しておりますが、こちらも大変好評でして、７,８３３件のダウンロードをしていただいております。皆様、健康づくりに関心のある方、それからウォーキングに関心のある方がこちらを有効活用していただいていると分析しています。","id":"exchange-010"},{"speaker":"つる委員","kind":"提案","question":"さらに推進をお願いしたいと思いますが、それからヘルスケアポイントということで提案させていただいて、昨年の４定では。そこで、今現在の区のヘルスケアポイントの導入についての検討状況を説明するよう求めました。","respondent":"川島健康課長","answer":"健康ポイントプロジェクトを実施している、私は６月にお聞きしまして、内容について確認したところです。健康づくりに対して有効な施策であると認識しておりますので、調査、情報収集を続けていきたいと考えています。","id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"筑波大学だったり久野教授の名前だったり、私もかつて繰り返し一般質問等で、視察させていただいたところを引用して提案させていただいたところです。こういう傾向が見られるということでありますが、品川区としてのこうした数字がわかるものでしょうか、説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"品川区では、これまで平成２４年度からこうした中小企業に向けての取組みを開始しております。中小企業支援の特性としまして、大手の企業でありましたら、いろいろ育児関係の法的なもので義務化で対応しているような状況があります。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"これは報道で私も知りましたが、今、九州・山口のワーク・ライフ・バランス推進キャンペーンということで、「知事が妊婦に」が話題になっています。既にもう再生が１２万回を超えたということで、同性がどう頑張っても経験できない部分を疑似体験できるという体験は、いかがか説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"先ほどの繰り返しになりますけれど、小規模事業者であるがゆえに、なかなか休暇なりお休みがとりづらいというようなこともあります。経営者の方々とやりとりをしながら、強力に意識啓発に努めている、あるいは努めてまいりたいと考えているものです。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"さまざまな議論も一方ではあるのかと思いながらも、ひとつ、ぜひ参考にしてほしいと求めました。地域経済分析システム、いわゆるＲＥＳＡＳを、産業経済振興としてどのように活用されているか説明を求めました。","respondent":"柏原企画調整課長","answer":"庁内でも観光、それから商業の部門に、データのアクセスの権利というものを案内して、政策をつくる上で使ってもらっているという状況があります。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"商店街の近辺で、何時ぐらいに人が多くなっているかということもわかってくるということで、活用をぜひ積極的に促してほしいと求めました。最後に１点確認で、皆さんの声をしっかりと注視していただきたいと、最後は要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"中塚委員","kind":"提案","question":"１５５ページの商店街活性化事業費と、１５４ページの若者・女性就業支援事業について、就業支援のＰＲについてそれぞれ伺いたいと思います。個人の店舗に対してリニューアル工事への助成制度をぜひ実施してほしいと求めましたけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"２割が、約３００件弱ですけれども、個人事業主の方々も利用していただいている制度です。そうした制度の活用とともに、そうした最適な補助制度であり融資の利用というようなことをもって対応してまいりたいと考えているものです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"対象工事などを決めて、例えばこれは２０１５年の調査なのですけれども、空き店舗等活用事業補助金などを活用して実施している自治体が増えています。こうした、実施している自治体について、品川区でも調査・把握していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"あるいは中小企業も含めた産業支援のメニューにつきましては、あるいは見直ししたりということで努めてまいりたいとは基本的には考えております。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"区の長期基本計画でも第４次実施計画でも、生活のインフラと位置づけているわけですから、方向性は一致しているのではないのかと思うのです。この声は届いているのか確認したいのと、次回の告知などを認めていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"地域の身近なインフラであり、活力を醸成するもとになるものという認識のもと、しっかりとした支援メニューを考えてまいりたいです。区としましては、東京都に要請をしつつ、柔軟な対応も必要かと考えているところです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"それが１つと、東京都に対して改善してほしいと要望しているのか、そこを確認させてほしいと求めました。こうしたことはできないのか、伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"東京都のほうが４月の段階で計画が決まりまして、より東京都に先んじて、商店街の実態を見きわめたふうに改善をしてまいっているつもりです。今後もそうした視点で、東京都とのやりとりと、区の制度の見直しは、継続的に続けてまいりたいと考えているところです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区としても要望しているということなので、ぜひ強く要望していただきたいのと、その点を改めて求めたいと思うのですけれども。ご両親向けの事業説明会や相談会などを企画してみるというのもよいアイデアではないかと思うのですけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長、立木産業活性化担当課長","answer":"先ほどの問題は、平成２７年度の年度中に東京都の方針がということで示されました。区としては、ちょっと検討課題にして、いろいろ東京都とやりとりをしてまいりたいとは考えているところです。関係する機関等にもチラシを置いていただいておりまして、そういったところからが大体６割ぐらいということで、認知経路になっております。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"私はぜひ、例えば正規雇用につながった体験例を紹介するパンフレットや、ご両親向けの事業説明会や相談会、何か希望が感じられるような工夫がとても大事ではないかと思いますので、ぜひご検討いただけたらと思いますけれど、いかがか尋ねました。","respondent":"立木産業活性化担当課長","answer":"例えばホームページで紹介するとか、そういったことも含めていろいろ検討してまいりたいと思います。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"私からは、１５２ページの動物死体処理費について、続きまして１５０ページのボトルキャップ回収運動について伺います。一律で２,６００円、料金等かかってくると把握しておりますが、道路などで発見された場合の引き取り料はどこが補填しているのか伺いたいと思います。","respondent":"小林品川区清掃事務所長","answer":"その取扱いなのですけれども、道路等の場合、道路管理者の負担となりますが、国道については国道管理事務所でみずから収集して対応しています。その他の区道等ですが、これについては区の負担です。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問・要望","question":"道路上や公園などで発見した場合に、ちょっと詳しく教えていただきたいのですが、どのように対応されているのか伺いたいと思います。例えば首輪などをしている猫や犬に関してはどのように対応されているのか、捜査などはされているのか伺いたいと思います。","respondent":"小林品川区清掃事務所長","answer":"首輪等の識別するものがあれば、それも含めて全て記録して対応し、問い合わせがあれば見ていただいているという形になります。環境課とも相談しながら、基本的に事件性がある関係がありますので、同時に警察通報ということでマニュアルを定めているところです。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問・要望","question":"続きまして、１５０ページのボトルキャップ回収運動について伺いたいと思います。率先して環境活動に取り組むため」という、いろいろ文章があるのですけれども、このボトルキャップは何に使われていくのか伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"福栄会に取りにきていただいていますけれども、福栄会では知的障害者の方が、このボトルキャップをそれぞれ色分けしてくださっています。そちらに関してはリサイクル業者が、例えば、プラスチック溶剤の製品に利用しております。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"いろんな学校や会社、団体というのが、そういったボトルキャップの回収を中止しているということでありました。品川区の平成２８年度の予算では見当たらなかったのですが、そのことについて今後どのように行われていくのか伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"平成２８年度予算が計上されていないと申しますのは、今現在、必要なボックスについては全部賄えております。事務用経費となっていますので、ボトルキャップ回収運動としては、名目上ございません。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"次に、１４５ページの公衆便所費について伺いたいと思います。この公衆トイレの清掃管理について、どのような方が清掃して、またどのぐらいのペースでトイレを掃除されているのか伺いたいと思います。","respondent":"溝口公園課長","answer":"区内には３６カ所トイレがありまして、最低でも１回の清掃、また大井町駅など駅周辺につきましては１日２回の清掃を行っているものです。業者につきましては、トイレ清掃等を行っている専門の業者に委託して清掃業務を行っているものです。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問・要望","question":"毎日清掃されているとお聞きしましたけれども、２回やるとか、そういうのがわかりましたら教えてほしいと求めました。そこで、少し費用はかかると思いますが、消臭剤や、またトイレボールの活用をお願いしたいと思うのですが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"さらににおいがひどい、年１回につきましては高圧洗浄機を使って、全ての床、また便器等を清掃しているものです。は利用者のマナーの向上に努めていくといったことをやることによって、誰もが利用しやすいトイレ環境をつくっていくというふうに考えているものです。","id":"exchange-027"},{"speaker":"松永委員","kind":"質問・要望","question":"最後ですが、１４９ページの環境調査測定費の航空機騒音調査について伺いたいと思います。５８万２,１２０円の内訳について伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"航空機騒音調査につきましては、平成２７年度には、どのあたりが一番、測定地点としていいのかどうか、業者委託して測定地点の調査を行いました。","id":"exchange-028"},{"speaker":"松永委員","kind":"確認","question":"場所を確認しただけということでよろしいのですか。今後、本年度予算でも６６０万円とついているので、もしかしたら、もうそういった場所は決められたのか、あわせて伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"今回、調査いたしましたのは、どのあたりの場所がいいのか、また箇所数が何カ所がいいのかなどを広く調査したものです。一応考えてはおりますけれども、そのようなことを考えておりますので、一応調査はしております。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"１５７ページ、１５６ページで、バンコクビジネスサポートセンター運営補助についてお伺いいたします。再びあのような、品川区全域のおみこしを集結した一大パレードを企画するべきかと思われますが、区のご見解はいかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"機運醸成に向けて非常に効果があるのではないかという考えがありまして、区としてもただいま具体的なプログラムの検討に入ったところです。区民の皆さん、また関係者、品川区全体で盛り上がるイベントを実施していきたいと考えているところです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"例えば１５年前は旧東海道でパレードを行いましたけれども、３年後に開通予定の２６号線、事業を前向きに進めていただきたいと考えております。この２点、お伺いいたします。","respondent":"立木産業活性化担当課長","answer":"各創業支援施設に入居している方の区民率なのですけれども、例えば武蔵小山創業支援センターを退去した方が、５７％ほどの定着率ということになってあります。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"この５施設は品川区民の税金で一部賄われている、ぜひとも統計を今後はしっかりととっていただきたいと考えております。区内産業との連携、そうしたことをやっていただくような仕組みづくりが必要だと考えておりますけれども、この点を品川区はどうお考えか尋ねました。","respondent":"立木産業活性化担当課長","answer":"入居中・入居後の支援のほうが大切になってくるのですけれども、その後の支援を継続、また例えば創業支援センターも幾つか段階がございまして。固定ということではなく、いろいろ柔軟に検討は、これからもデータをとりながら進めてまいりたいと考えております。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"審査でしっかりと実態をチェックしていただいて、そういったことはないように、ぜひともしていただきたいと考えております。今の時代に合った、産業構造に合わせた施設に改修していくのかどうか、そうした予定があるのかどうかということをお伺いいたします。","respondent":"立木産業活性化担当課長","answer":"今の施設の業態のところですが、確かに品川区はこれまで製造業のまちというところで、多く製造業の部分の支援をしてまいりました。そういったところをしっかり見きわめながら、今後の施設運営の検討をしてまいりたいと思います。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひともそれぞれの時代に合わせた、施設づくり、産業・ものづくりを進めていっていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"最初に、１４３ページの予防費の予防接種費から伺います。予防接種法の改正にのっとった副反応を防ぐための予診は実際にどのように行われているのか、把握していらっしゃるのでしょうか、説明を求めました。","respondent":"舟木保健予防課長","answer":"２カ月の方が受けることということで説明ということで、そういうところをきちんと読んでくださいというふうに書かせていただいております。情報提供に関しましては、そこで確認して、かかりつけの先生のところできちんと説明を受けた上で受けていただくという形となっております。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"そこまでの情報も、今おっしゃったアプリなどを見るとわかるのでしょうか。何かもう少し丁寧な予診というのがあってもいいのかなと思ったのですが、その辺はいかがか尋ねました。","respondent":"舟木保健予防課長","answer":"そこの副反応について、より詳しく載っているところや、あと予防接種の情報が載っているところのリンクを張って周知するようにしております。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"ＨＰＶの問診票に、２カ月のお子さん向けではないのでいただかなかったのですけれど、例えばパン酵母アレルギーについて書かれているのでしょうか。探すのが難しかったのは、私が検索が下手だからと言われたらそれまでなのですけれども、その辺の情報提供はどうなのか尋ねました。","respondent":"舟木保健予防課長","answer":"そのことについての記載、私のほうもちょっと確認してみたところ、厚生労働省のホームページのＱ＆Ａには書かれておりました。そのような形であれば、「医師とよく相談した上で」とか、そのような形で記載されております。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"２０１５年１２月にアレルギー疾患対策基本法が施行されて、それに先立つ１２月２日には厚生労働省健康局長から通知が来ています。一層のアレルギーについての認識を持つべきと思うのですけれども、何か強化したところとか、そういうことがあれば説明を求めました。","respondent":"舟木保健予防課長","answer":"予防接種を実施するにあたっては、そこのところの適切な説明をきちんと行うようにということは、こちらも現場で実施しているところです。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"年１０カ所というのはどういう趣旨なのでしょうか。例えば２０１５年度の予算立ては１,２００万円弱あったわけですから、広げるという方向であれば、その辺はいかがでしょう。","respondent":"和田河川下水道課長、舟木保健予防課長","answer":"これまでの取組みを十分振り返りながらＰＲをしていきたいと、今後もＰＲを重点的にやっていきたいと考えています。設置できる区有施設は全て終わるというようなことでございまして… 予防接種に関する情報提供について区の見解ということで答えします。受けられる方、みずからの意思で接種することについて十分認識・理解できるよう、あと医師会等とも連携しながら情報提供してまいりたいと思います。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問","question":"その後のご検討をいただけたでしょうか。子どもを預けたい人だけ予約制にして、そのときだけ人の手当てをするということは考えられないか尋ねました。","respondent":"立木産業活性化担当課長","answer":"そこの部分に対しての手当てという部分に関しては、検討は進めておりますが、今のところはできておりません。引き続き、あそこの相談だけでなく、いろいろな部分で検討してまいりたいと考えています。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから、託児室なのですけれども、ホームページの施設案内に出ていないのですけれども、ぜひその辺の広報もお願いしたいと思います。要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私からは、成果報告書１４９ページ、水質調査についてお伺いいたします。１１カ所と記載してありますけれども、さまざまな調査をしていると思うのですけれども、どういう調査をしているのか示すよう求めました。","respondent":"三ツ橋環境課長","answer":"一方、立会川の５地点ですけれども、浜川橋、新浜川橋北、運河中央、鮫洲橋、勝島橋となっています。こちら、どういう調査という内容ですが、ＢＯＤ、ＣＯＤ、全窒素、全リン、ＤＯなどをはかっております。","id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"意見","question":"今後、４年後に向けて、東京オリンピック・パラリンピックがあります。東京湾、これは都との連携も今後あると思うのですけれども、その辺の水質の改善といったことも今後調査として取り組んでいくのかお知らせくださいとの意見を述べました。","respondent":"和田河川下水道課長","answer":"今、立会川の河口部でやっています高濃度酸素水の注入事業、それから定期的な浚渫事業にとどまっております。毎年、合流改善の推進について強く要望しておりますので、これについては今後も強く合流改善の事業の推進を東京都に求め続けてまいります。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"本当に区長にこれからも要望していただきまして、４年後に向けて、そういった整備を含めてご検討をよろしくお願いしたいと思います。続いて、同じく１４９ページのアスベスト対策についてお伺いいたします。","respondent":"三ツ橋環境課長","answer":"こちらは吹きつけアスベストに関してのみです。一方、除去助成につきましては、解体に伴う除去の助成をしております。","id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"意見","question":"助成の件数が先着順となっておりますけれども、調査５件、除去が３件。本年の４月１日から来年度の１月１０日までが申込期間になっておりますけれども、今現在どの程度申し込みがあるのかお知らせくださいとの意見を述べました。","respondent":"三ツ橋環境課長","answer":"今現在のアスベスト調査助成、また除去助成の申請件数ですけれども、除去助成につきましては１件ございまして、調査助成につきましてはまだ来ておりません。","id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"意見","question":"ここの環境指導相談費の中の環境相談の中で、アスベスト相談が９５件あります。これは建築業者が主だと思うのですが、そういった９５件の中に業者も含まれているのかお知らせくださいとの意見を述べました。","respondent":"三ツ橋環境課長","answer":"例えば区民の方から、また隣で解体しているけれども、あのお宅にもやもやしているものはアスベストではないかというご相談が主です。例えば業者が、実際に自分たちが調査に当たる場合はどのような業者がいいのか、ご相談もあります。","id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"意見","question":"結構、アレルギーを持っておられる方はひどく腫れてしまったり、今現在もそういうのがあります。そういった相談というのはありませんかとの意見を述べました。","respondent":"三ツ橋環境課長、川島健康課長","answer":"アスベストに関しましては、数十年後に中皮腫や肺がんになる可能性がありますので、そちらのご相談につきましては、実際に東京都であったり、また公害補償関係であったりになってあります。 平成２５年度が４件、平成２６年度が３件、平成２７年度は０件でした。それから申請も、年に１件、２件あるかないかというような少ない状態になってあります。","id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして１４５ページ、そ族昆虫防除対策費についてお伺いいたします。本年のジカ熱などの感染症の対策に向けた蚊の防除について、この取組みをお知らせほしいと求めました。","respondent":"井浦生活衛生課長","answer":"平成２７年度から実施してございまして、品川区としまして、蚊が発生しないような対策を講じているものです。区内全域の公道あるいは区立公園等々、３万４,０００カ所に雨水ますがございまして、蚊の発生を抑制する薬剤を散布しているという事業です。","id":"exchange-048"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今、巡回予定数が年間、当然、冬の期間は、冬の期間もあるのかな、４巡回。実施状況が５月から１０月ということなので、まだ１０月の半ば前なので、まだ実施しているということでよろしいのか尋ねました。","respondent":"井浦生活衛生課長","answer":"５月から１０月にかけまして、区内の３万４,０００カ所を４回回るという計画です。現在、最終回で巡視しています。","id":"exchange-049"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうしますと、これは区内全域の公道ということで解釈してよろしいのか尋ねました。","respondent":"井浦生活衛生課長","answer":"区内全域の公道でございまして、区道、都道、国道について行っているところです。","id":"exchange-050"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"来年度もこの取組みはやっていくのでしょうか。その辺の今後の予定についてお知らせほしいと求めました。","respondent":"井浦生活衛生課長","answer":"さらにホームページにもトレンドな内容でアップしてございまして、引き続きＰＲ、広報に努めてまいりたいと考えています。２点目の、来年度につきましても、一層の充実ということで推進を図っていきたいと考えています。","id":"exchange-051"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは散布ではないですか。やっていただいている方は、区の職員の方と解釈してよろしいのか尋ねました。","respondent":"井浦生活衛生課長","answer":"事業受託で実施してございまして、委託の経費が年間８４６万７,０００円余です。","id":"exchange-052"},{"speaker":"新妻委員","kind":"質問","question":"１５６ページ、プレミアム付区内共通商品券発行助成についてお伺いいたします。この６月の一般質問でも取り上げましたが、「肺がん予防の取組みとして、作成状況およびどういう仕様なのかということをお伺いしたいと思います。","respondent":"川島健康課長","answer":"もうそろそろ印刷に入れるということで、１１月ぐらいにはお配りできるだろうということで、まず２,０００部の配布の予定です。その他、ホームページにもアップする予定です。","id":"exchange-053"},{"speaker":"新妻委員","kind":"質問","question":"６２カ所あるということです。禁煙外来に行ったとか、また禁煙に成功したとか、この結果というのはどのように把握されるのか尋ねました。","respondent":"川島健康課長","answer":"何か区でできる支援があるかないかというところも含めて検討するということ、保健指導で禁煙指導にこちらを使用するというような話も聞いておりますので、有効活用されることを期待しております。","id":"exchange-054"},{"speaker":"新妻委員","kind":"質問・要望","question":"一般質問でも要望したのは、しっかりとこれは検証する対策をとってほしいと求めましたので、よろしくお願いいたします。そこをちょっと確認したいのですけれども、今後の品川区の公衆便所のあり方についてのお考え、方向性をお伺いしたいと思います。","respondent":"溝口公園課長","answer":"やはり観光として品川区に来られた方の利用、また公衆トイレということで、誰もが利用できるということの視点が大事だと考えています。","id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"さまざま手を入れていただきたいと思うのですが、品川区はこのネーミングライツ事業の取組みについての考えはいかがでしょうか。お伺いしたいと思います。","respondent":"溝口公園課長","answer":"先ほどお話しした観光またはオリンピックといった観点で整備していく中で、洋式化についてもしっかり取り組んでいきたいと考えているものです。","id":"exchange-056"},{"speaker":"新妻委員","kind":"質問・要望","question":"そして商品券についてお伺いいたします。もしかしたらこれは今回だけなのか、また戻ることもあるのか、ちょっと含みがあると思ったので確認させてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"「今回は」と申しますのは、事前申込制を強調するために選びました。基本的にはこの申込制を維持したいと、今、現時点では思っております。","id":"exchange-057"},{"speaker":"新妻委員","kind":"質問・要望","question":"公平性も保たれてきているかと思います。今回、いろんな取組みが考えられるかと思いますので、今後そのようなこともぜひご検討いただきたいということを要望して終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"「４０歳からの健診で適正だ」、「４０歳からで口腔内の健康は守れる」、どのような認識の変化があったのか伺いたいと思います。「具体的に検討」とは、中身は何か、どんな検討がされているのか伺います。","respondent":"川島健康課長","answer":"まず１つは２０歳からの健診を導入したということ、今回、「検討に入った」というような答弁をさせていただいたところであります。予算編成の作業とかかわってくるので、年齢を引き下げるというのをどうしていくのかという、その辺の制度設計を検討し始めているです。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"提案","question":"ぜひそこで提案させていただきたいのですけれども、二十歳からの健康診査は、健康診断の機会のない人が対象です。そして、改めて、２０歳の健康診査と一緒に成人歯科健診も２０歳からということを求めますけれども、いかがか尋ねました。","respondent":"川島健康課長","answer":"具体的な検討の中身につきましては、これからというところですが、年齢を引き下げる検討に入ったという段階になります。ですので、細かな、どの年齢を対象にするのかなどという話になってきますと、これからの検討になるです。","id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"年齢を拡大していく、開始年齢を引き下げていくということですけれども、今までのように５歳刻みなどではなく、毎年診断が受けられるようにしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"川島健康課長","answer":"毎年ということになりますと、その上の年代、今の４０歳以上の方の年代の健診ともかかわってくるので、なかなか難しいのではないかです。","id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その根拠を伺うと、区は５歳刻みで、ぜひ毎年やっていただきたい。どの年代でも早期発見・早期治療ができるように、毎年の歯科健診をしてほしいと求めましたけれども、改めてお願いします。","respondent":"川島健康課長","answer":"区が５歳刻みに持ち出ししてやっているというところで、よくできた制度設計だと考えていますので、大変なことになるというのが現状の認識です。","id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこからまた５歳刻みというのは、ぜひ２０歳から、そして毎年お願いしたいと強く求めたいと思います。ですけれど、平成２８年から平成３０年は、平成３０年以降はどうなるのか伺います。","respondent":"川島健康課長","answer":"それで、平成３０年度までは激変緩和策ということで、２０歳からとするような予定でおります。１,２３９人中５１人が受診されております。","id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、そういった切れ目のない健診を進めていくためにも、１６歳からの健診に全てしていってはどうかと思うのです。ですので、さらに拡大していくということを求めますけれども、いかがか尋ねました。","respondent":"川島健康課長","answer":"名前が変わってしまうような変更にもなりますし、この形で事業は継続していきたいと考えておりますので、１０代の方の健診も終了するような予定で進めていきたいと考えております。","id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"提案","question":"それと、また先日の一般質問のところで、２０歳からの健康診査に麻しん・風しんの抗体検査を加えてはどうかといったことが提案されていました。検査コストの面からも難しい」と答弁されているのですけれども、具体的にどういうことなのかを伺いたいと思いますとの意見を述べました。","respondent":"川島健康課長","answer":"一般質問でご答弁申し上げたとおり、これは２０歳からの健康診査の単価が上がってしまうです。２０歳からの健康診査のお知らせの中に、「先天性風しん症候群対策として、ご相談ください」という文言を入れしています。","id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういう紹介を入れているのでしたら、一緒に検査ができるというようなことでいいのではないかと思うのです。２０歳からの健康診査に入れるということは、単価が上がるということですけれども、どれぐらい上がってしまうのか伺いたいと思います。","respondent":"川島健康課長","answer":"すみません。今回一緒に受けられます」というご案内をするということで、同時にやるというのは今でも可能ですので、そういったご案内をつけ加えて周知するです。","id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"意見","question":"ぜひ、２０歳からの健康診査に来た方が、全ての医療機関で、２０歳の健康診査ができる機関で一緒にできるようにしていくことが、さらなる予防につながっていくと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"あべ委員","kind":"質問・要望","question":"１４４ページ、１５１ページ、それから１５６ページのバンコクビジネスサポートセンターについてお伺いしたいと思います。こういったことを品川区でも、これまでも要望が出ていたと思うのですけれども、現在の検討状況について説明を求めました。","respondent":"川島健康課長、小林品川区清掃事務所長、立木産業活性化担当課長","answer":"２３区内でも、今、１１区ほどが何らかの形で眼科検診を導入していると聞いてあります。視力というのが大変重要な感覚になると私どもも認識しておりますの… 品川区におきましても軽微なものも含めまして、平成２７年度におきましては４件の火災事故が発生しています。… 設置から６年ほどたちまして、タイへの進出ということでは、品川区内の企業のご利用というのが少なくなっております。","id":"exchange-068"},{"speaker":"あべ委員","kind":"質問・要望","question":"区民の方が「かわいそうではないか」というような声が出ないような職場環境にしてほしいと求めましたので、お考えをお伺いしたいと思います。このまま区が公金を出すやり方としては、私はちょっとイレギュラーな時期が続いているのではないかと思いますが、いかがか尋ねました。","respondent":"立木産業活性化担当課長、小林品川区清掃事務所長","answer":"撤退も含めて、今、検討しているというようなところです。 広報による、あるいはホームページによる啓発等、努めてまいります。なお、労働環境につきましては、安全衛生委員会で現場の声を取り入れながら進めてまいります。","id":"exchange-069"},{"speaker":"あべ委員","kind":"意見","question":"もっときめ細かく、安全あるいは危険性というものを、場合によっては火災の動画などを何かに使っていくということもあってもいいと思います。もっと強く、これはアピールしてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"渡部委員","kind":"質問","question":"１５７ページはビジネス・カタリストについて伺うのですけれど、平成２７年度予算書で、信用保証料の補助が２億６,７００万円。これは毎年のことなのですけれど、このようになってくるのだというところなのか、その辺の見方を説明するよう求めました。","respondent":"山崎商業・ものづくり課長","answer":"性格上、経済状況をつかむということが必要になってくるわけなのですけれども、とりわけそれをしっかりつかんでいくのが非常に困難な部分もあります。","id":"exchange-071"},{"speaker":"渡部委員","kind":"質問","question":"やはり毎年、紹介数に対して実行されるのが、おおむね８割程度なのです。なかなか実行できないのか、紹介数と実行数の約２割の乖離というのは、どういうふうに見たらいいのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"そうした中で、ちょっと残念ながら融資制度を活用できないという数字もありますが、ここの乖離の一番大きな部分は、品川区であっ旋を銀行に出します。国の制度を使うとか、そういったことが主でございまして、はじかれてしまうという意味では非常に少ないかとは捉えております。","id":"exchange-072"},{"speaker":"渡部委員","kind":"質問","question":"前にちょっとご質問させていただいた借換え等の需要に関しましても、これ１冊あれば、本当に便利だなと。ほかに参考された資料等があったのか、どうなのかと、あわせてお願いします。","respondent":"山崎商業・ものづくり課長","answer":"低金利の時代になりまして、４月からオール０.１％、引き下げを行いました。敏感にいろんな情報をキャッチして、企業の皆様に使っていただく制度であり続けるためにしっかり努力してまいりたいと考えております。","id":"exchange-073"},{"speaker":"渡部委員","kind":"質問","question":"ビジネス・カタリストについて伺っていくのですけれど、これも事務事業概要等を見ますと、９８名の登録があります。どのような方々が、この９８名にいらっしゃるのか、ちょっとご紹介いただくよう求めました。","respondent":"立木産業活性化担当課長","answer":"研究者の方ですとか、あと士業の方、そういった方々が登録されております。登録に際しましては、区の職員とカタリストマネージャーが面接の上、適しているかどうかということで登録いただいております。","id":"exchange-074"},{"speaker":"渡部委員","kind":"質問","question":"４６件、１６５回というところ、派遣実績ですからそうですよね。どのようなかかわり方といいましょうか、知り方というのでしょうか、しているのか尋ねました。","respondent":"立木産業活性化担当課長","answer":"こちらの件数ですけれども、前年度に比べまして増えておりまして、回数的には予算のほうも増額させていただいたという経緯があります。それから、ここはこうしたほうがいいのではないかというような、例えば自身の売り込みといったような形で派遣されるというような形もあります。","id":"exchange-075"},{"speaker":"渡部委員","kind":"質問","question":"このカタリストが入ることによって、その企業が相当活性化された、また新商品等も開発されたというような事例も伺っています。活用もされたらいいのかななどという思いがあって質問させていただきましたので、もう答弁する必要はないのでご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"あくつ委員","kind":"確認","question":"１５３ページ、時間があれば１５４ページ、観光アクションプラン推進事業についてお伺いいたします。幾つか今までの確認をします。","respondent":"舟木保健予防課長","answer":"軽度外傷性脳損傷というのが最近認識された疾患概念だということで、いろいろな症状を呈するということで、なかなか診断が難しいような疾患です。当初から教育機関と連携して、平成２７年度予算で２万５,０００部作成しまして、学校でも配布していただいています。","id":"exchange-077"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区は、患者会の要望で、２３区で初めて教育機関への周知ということも文言に入って、皆さんの見識の高さに敬意を表するものであります。この後の展開について、何か教育機関でお考えのことがあれば説明を求めました。","respondent":"有馬学務課長","answer":"ＭＴＢＩのリーフレットの作成の趣旨を説明いたしまして、このリーフレットを保護者にも周知していくということの説明会ということで行いました。ＭＴＢＩを理解していただくということが必要になってくるのだろうということで、今、考えているところです。","id":"exchange-078"},{"speaker":"あくつ委員","kind":"質問・要望","question":"教育機関への周知ということを患者会の方が求められていましたし、私もお話を伺いましたけれども、ぜひ進めていってほしいと求めました。この執行率の低さの原因は何なのか伺います。","respondent":"山崎商業・ものづくり課長","answer":"いろいろ災害への備えは大事だという認識は、この事業については力強くご理解を賜るというようなつもりでやってきたのですが、結果としてこれです。反省しまして、いろいろＰＲなり何なりも含めてしっかり取り組んでまいりたいと思っている次第です。","id":"exchange-079"},{"speaker":"あくつ委員","kind":"質問","question":"中堅企業では、２９.９％が策定済みで、これに策定中を加えると４割強となっているということになっております。先ほど、反省はされているというお言葉がありましたが、周知はどのように行われてきたのか、この２点をお伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"やはり１０％前後というようなことで数字は把握しております。今、策定中の企業が３事業者おりまして、そうしたところも含めてしっかりサポートしてまいりたいと考えているものです。","id":"exchange-080"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最近は刀剣女子というのですか、その方のところにお伺いを立てに来るぐらい、非常に著名な方なのです。ここはぜひ、坂本龍馬が大好きと聞いている文化観光課長にお伺いしたいと思うのですが、いかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"来年が大政奉還１５０周年、明治元年から１５０周年ということで、明治にかかる関係資料等を使って事業を展開したいと考えているところです。なので、ご提案のことも含めまして、何か品川をＰＲできるいいイベントができないかということで検討したいと考えております。","id":"exchange-081"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ぜひ各市区町村と連携しながら、この資源を活かしていただく。検討していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"西本委員","kind":"質問","question":"この拡大の理由と、それから２０歳から３９歳ということなのですが、２０歳前の状況はどういうふうな形になっているのでしょうかということ。そういうものが理解できるような仕組みも必要ではないかと思いますが、いかがか尋ねました。","respondent":"川島健康課長、山崎商業・ものづくり課長、稲田都市開発課長","answer":"５歳刻みでなく、切れ目のない年齢設計にするということでさせていただいた制度の変更ということで、年齢対象を拡大させていただいたものです。それから… 商店街の国際化の対応です。ハラル食品の対応あるいはそうしたことに準じた取組みをしていらっしゃるとか、そうした品川区なりの… １０月３１日には成田便も開通します。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"もっと長くやっていただきたい思いはあるのですけれども、何か１つの柱ができないかと思っているのですが、そのお考えはいかがでしょうか。そういうものにまで考えられ、視野が広がるようなものにしてほしいと求めましたので、もう少しお考えをお聞きしたいと思います。","respondent":"川島健康課長、鈴木文化観光課長、河内協働・国際担当課長","answer":"障害者の方の歯科につきましては、治療する歯医者にとっても大変難しいという話をお聞きします。それから、例えば障害者福祉課… 大崎駅西口バスターミナルの活用ですが、区としても重要な開発の資源、また観光の資源と考えております。設置いたしました観光振興協議会のショートトリッ… 「中国語少し通じます商店街」あるいは「英語少し通じます商店街」が面的・線的な事業になるかと思います。","id":"exchange-084"},{"speaker":"飯沼委員","kind":"質問","question":"１４２ページの医師会助成費についてお伺いします。国と自治体の連携が重要と思いますが、現状においての品川区の実態と対策を幾つか示すよう求めました。","respondent":"舟木保健予防課長","answer":"相談事業の充実、あと自殺というのは非常に原因がさまざまでして、そういうネットワークづくりというところで対策を進めているところです。","id":"exchange-085"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区の実態というのはどうなっているのですか。年１回の講演会だけではなくて、もっと力を入れてやってほしいと求めましたが、いかがか尋ねました。","respondent":"舟木保健予防課長","answer":"保健所で実施しているのですが、あと映画上映会のときにも、いろいろな場面でそういう機会を捉えて自殺についてお話ししているところです。そのような形で、こちらのほうも少しずつ啓発は進めていますが、さらにまた進められるよう取り組んでまいりたいと思います。","id":"exchange-086"},{"speaker":"飯沼委員","kind":"質問・要望","question":"こういった危険性をはらんでいらっしゃる方に、ぜひもっと働きかけができる体制の充実を求めていきたいと思いますが、いかがでしょうか。悩みを抱えた人が集える常設の居場所を求めますが、いかがか尋ねました。","respondent":"舟木保健予防課長","answer":"未遂者に対する支援につきましては、現在まだ取り組んでいないところですが、しなければいけないということで、少しずつ考えているところです。ゲートキーパー研修を取り組んでいるところですが、あるいは状況に応じて、対象を考えながら進めてまいりたいと思っているところです。","id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ご遺族や残された人に対する支援はどうなっているでしょうか。その後のつながりづくりを支援してほしいと求めましたが、いかがか尋ねました。","respondent":"舟木保健予防課長","answer":"事業につきましては、各保健センターと協力しながら実施しているような状況です。自死遺族の支援につきましては、「わかちあいの会」とか、そういうところをご紹介するというような形で現在はしているところです。","id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問・要望","question":"相談の場所があってもハードルが高くてなかなか伺えないというところで、ぜひ工夫してほしいと求めましたが、いかがでしょうか。シルバーウイークについて、ゴールデンウイークと同じようにしてほしいという声が出ていますが、いかがか尋ねました。","respondent":"川島健康課長","answer":"２３区、どこもそういう表示をしていないというところですので、やはり運用でやっていただきたいということ。たしか４年に１回、その前の年に検討させていただきたいという、その都度検討ということでお答えいたします。","id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問・要望","question":"長く維持していただきたい休日診療の制度ですので、医師会の先生たちとよく話し合って、ぜひ充実を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"渡辺委員","kind":"質問","question":"ページ数はあれなのですが、健康センターのことを伺います。いろいろな掲示物や内容・施設の充実を肌で感じたものですから、それとあわせて、かなり地域の声も評判よく聞いています。","respondent":"川島健康課長","answer":"それから平成２６年度が２億円を超えております。それから、平成２７年度も２億１,０００万円という、毎年上昇しているという状況です。","id":"exchange-091"},{"speaker":"渡辺委員","kind":"提案","question":"そういった提案にしたいと思うのですが、その辺の考え方をひとつ伺いたいと思います。地域のエリアバランスに拠点の拡充が必要ではないかという、この辺の３点を伺いたいと思いますとの意見を述べました。","respondent":"川島健康課長","answer":"事実、国保医療年金課では、健診のご案内も置いているという状況にあります。広さが違うのがまず１つなのですけれども、土地がなかなか出てこないというところもありまして、こういった形での運営をしています。","id":"exchange-092"},{"speaker":"渡辺委員","kind":"提案","question":"続きまして１５０ページ、環境啓発のところを伺います。それで、提案者がおもしろいと思って提案できるような募集の仕方をすれば、いい企画も出てくるのではないかとの意見を述べました。","respondent":"三ツ橋環境課長","answer":"そのほかエコライフアイデアコンテストにつきましてですが、こちらは平成２６年度から実施している事業です。昨年度、平成２７年度につきましては、エコライフアイデアコンテストの次年度として、エコトバコンクールというものを実施いたしました。","id":"exchange-093"},{"speaker":"渡辺委員","kind":"質問","question":"行政が観光協会等と連携しながらとか、やったらどうかと思うので、伺いたいと思います。そういった意味で、チャレンジ精神という観光の意識について伺えればと思います。","respondent":"鈴木文化観光課長","answer":"観光に関するチャレンジの考え方ですが、観光、どうしてもチャレンジの気持ちでリスクのことも考えて対応が必要というのは認識しております。しっかりと挑戦しながら、区のＰＲ、また観光のお客様の誘致というところに取り組んでいきたいと考えております。","id":"exchange-094"},{"speaker":"塚本委員","kind":"質問","question":"１４５ページのそ族昆虫防除対策費ですが、ネズミの防除ということも区が行っていこうとしている理由について、まずお伺いします。この２点をまず最初にお伺いします。","respondent":"井浦生活衛生課長","answer":"そのような中で、生活衛生の適正を確保するという趣旨でご相談に応じている。あるいは、ピッタンコという、トリモチのようなネズミとりもサンプルとして提供するという事業を行っているところです。","id":"exchange-095"},{"speaker":"塚本委員","kind":"質問","question":"具体的に、そういった相談の中で、主にあれでしょうか。解体に際してネズミの対策、駆除みたいなことというのは、そ族の防除対策費の中でやる範疇となり得るかどうかもお伺いします。","respondent":"井浦生活衛生課長","answer":"ご相談をお聞きしながら、ネズミの出入り口等々を塞ぐようなことを、まずみずから行っていただくというアドバイスをすることを中心にしています。ネズミの毒餌ですとか、あるいはネズミとりをサンプルとしてご案内するというための経費として見積もっているところです。","id":"exchange-096"},{"speaker":"塚本委員","kind":"質問・要望","question":"今お伺いしたご答弁ですけれども、ぜひ今後の検討課題というか要望というところにもなりますけれども、ご答弁をお願いします。","respondent":"井浦生活衛生課長","answer":"それから３番目に蚊です。家屋解体等で出現するということも認識していますので、実態を見ながら防除の方法については研究していきたいと考えています。","id":"exchange-097"},{"speaker":"塚本委員","kind":"質問","question":"次に、１５６ページの商店街国際化推進事業ということで、免税店のことについてお伺いします。現状どういった形に、それから品川区のほうに、どうしましょうかみたいな相談が具体的にあるのかどうかというところもお伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"それから、それぞれの商店街の中の各個店の中では、既にそれぞれの個店の特性で、そうした免税の対応を行っているところもあります。いろんな、今、現状の情報の提供を行うなりの支援をさせていただいているような状況です。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問","question":"これは行政視察でも見に行っているというようなことも伺っていますけれども、一括してやっていただくというようなことが前提になるかと思うのです。どういうところを課題として思っているのかどうかということをお伺いします。","respondent":"山崎商業・ものづくり課長","answer":"そうした意味では、大型店舗では、既にその店舗の中では免税の対応がされているということで、そうしたカウンターなどは既存であるわけです。いろいろ１００以上ある商店街の中で、それぞれの個々の特性と意向を確認しながら、よい方向で検討を進めたいとは思っております。","id":"exchange-099"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこには積極的にシニアの方々を採用し、３世代がそこでおしゃべりをしたり、コミュニティスペースができると。それについてのお考えと、それから今現在、区の空き店舗の活用支援事業の実績についてお伺いいたします。","respondent":"山崎商業・ものづくり課長","answer":"平成１１年から１８年間、毎年１カ所ずつということで、１８カ所でそういう整備をしてきました。昭和通り商店街で、品川宿おばちゃんちの２号店というようなことで、付加価値を見ながら空き店舗の運営を品川区としても行っているような状況です。","id":"exchange-100"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"何というのですか、少し類似のあれがありましたけれども、このような形で就労支援の側面からぜひ検討してほしいと求めました。そういったところの課題をどのようにして解決してきたか、あるいはこれからしていくのかというところをお伺いいたします。","respondent":"山崎商業・ものづくり課長","answer":"そうした補助が途切れたときに、いわゆる、いろいろ空き店舗で展開している事業の継続性というのが非常に課題だと受けとめております。中小企業の経営支援だとか経営相談、しっかり最近は支援しながら、本事業について取り組んでいるというような状況です。","id":"exchange-101"},{"speaker":"高橋（し）委員","kind":"質問","question":"廃店したところもあるというのですが、所管が異なって、異なったところから支援というか補助が継続していくような方法もあるかと思います。そういった、そういった形で行政がフォローしていくということができるのではないかと思いますが、そういった点についてはいかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"ちょっと例示として繰り返しになりますが、昭和通りのおばちゃんちのほうは、一時預かりの保育のほうの、そうした補助スキームも入っております。","id":"exchange-102"},{"speaker":"高橋（し）委員","kind":"質問","question":"ぜひ、総合窓口的なところ、これは商業・ものづくり課になるのでしょうか。あまり大きく目立たないのですが、大切な事業だと思うのですが、その事業についての実績をお願いします。","respondent":"山崎商業・ものづくり課長","answer":"商店街の活力醸成という意味では、商店街の規模に関係なく、行政として必要な支援を行う必要があるとは考えてあります。人的な支援といいますか、より細かな支援が必要だと考えて、こうした点で支援をこれまでも充実してきているような状況です。","id":"exchange-103"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"調査は場所を確認したということですが、その点、もう一度お答えをほしいと求めました。超音波検査の導入も求める声があると聞きましたが、その点についても現状と今後について教えてほしいと求めました。","respondent":"三ツ橋環境課長、川島健康課長","answer":"今回につきましては、あくまでも候補地の場所を確認しております。国が実際にどのような考え方なのか、そのあたり等を考えながら複合的に考えていきたいと思いますので、その点でまだ決まっていないと申し上げました。 地区医師会と８月に打ち合わせをした際に、持ち帰り検討ということになっておりますが、区としてはやめていきたいという方向で考えております。高濃度乳腺に適している超音波を実施しつつ、今、対応しているという状況です。","id":"exchange-104"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"騒音ですが、そうなると、国と一緒に今年度これを進めていくということでよろしいのでしょうか。第三庁舎の１階にあるリボンですが、私は以前から区役所内に保育所ということを求めているわけでありますが、その点も示すよう求めました。","respondent":"三ツ橋環境課長、小林品川区清掃事務所長、柏原企画調整課長","answer":"航空機の調査地点ですが、こちらにつきましては、国の調査地点など、また区の調査地点など、連携していきながら考えていきたいと考えています。リユース事業を推進する必要があり、この必要性から、その拠点とするためにリサイクルショップを支援してまいったところです。… 考え方としましては、それからニーズといったところを考えたときに、そういったときの１つの選択肢であろうとは思ってあります。","id":"exchange-105"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"清掃用地に関しては検討をぜひしていただき、実現に向けて一歩踏み出してほしいと求めました。これは何に使われているのかお知らせいただきたいのと、１つの製品というか商品をつくって、どのようにお考えになるか示すよう求めました。","respondent":"山崎商業・ものづくり課長、立木産業活性化担当課長","answer":"マイスター店等支援事業の、９００万円余、それの執行のための委託費ということで使わせていただいております。それから従来のマイスター店の広報・周知・ＰＲにも使途させていただいているというような内訳です。 区内企業の製品技術に対して、個々のものに対しての認定、ＰＲということになっております。例えば１つのものをつくり上げてそれをＰＲするというのを、こちらのほうと連携しながら今後研究してまいりたいと思います。","id":"exchange-106"},{"speaker":"石田（し）委員","kind":"質問","question":"「ああ、品川区はこんないいものがあるのだな」という、ある意味ＰＲにもなるのかなと。そういうことを進めていけばいいのではないかと思いますが、その点、どう考えるか説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"ふるさと納税に、品川区なりの特徴的なもの、すてきなものをというようなご意見かと考えています。本件に関しての庁内の検討なども行う中で、委員がご指摘の品物、委員のおっしゃったようなところでいろいろ検討してまいりたいとは思ってあります。","id":"exchange-107"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、この３つの目的に対する、平成２７年度を中心に成果、また課題がございましたら、お聞かせほしいと求めました。多くの方がより買い求めやすいように工夫したという目的があったかと思いますので、今後の継続の考え方についてもお聞かせほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"ご案内の春におきましては、発行総額８億円に２０％のプレミアムをつける特別な交付金を活用したもので行いました。こういった単位を維持する方向で現時点では考えているというようなことです。","id":"exchange-108"},{"speaker":"若林委員","kind":"質問・要望","question":"４月については１０億円近いわけですから、今後、２,０００軒の加盟店の拡大がなかなか進まないというところ。精緻な分析をするというところで、今後、この内容の分析・報告が議会に対してしっかりとなされるのかというところは確認します。","respondent":"山崎商業・ものづくり課長","answer":"区としましては、そうした本来の商店街振興の趣旨にのっとってやってまいりたいとは考えているところです。今回も事前方式を導入して情報も取得できるようなことから、そうしたＰＤＣＡの取組みをさらに強化してまいりたいと考えているものです。","id":"exchange-109"},{"speaker":"若林委員","kind":"質問・要望","question":"公衆便所については既に議論がありますが、さまざまな要素がありますけれども、時間がありませんので１点だけ。文化観光を推進する立場から、どのような公衆便所、公園便所が望ましいのかお聞かせほしいと求めました。","respondent":"溝口公園課長、鈴木文化観光課長","answer":"文化観光、観光という面が強いかとは思いますが、誰もが使えるようなトイレが必要だと考えているものです。 例えば旧東海道の公園のトイレのように、観光の視点、文化の視点でふさわしい形や形状というのもあると思いますので、所管と連携しながら取り組んでいきたいと考えております。","id":"exchange-110"},{"speaker":"本多委員","kind":"質問","question":"１４９ページの、環境費、環境対策費、低公害車買換え支援事業、２点目が１５１ページの清掃費について伺います。今、そのことに対して区の環境課としてどう着眼されるのか、その点を説明するよう求めました。","respondent":"三ツ橋環境課長","answer":"例えばハイブリッド車であったり電気自動車であったり燃料電池車などがありますけれども、地球に優しい車が対応していくものだと考えております。","id":"exchange-111"},{"speaker":"本多委員","kind":"質問・要望","question":"これはどうなのか詳しくお聞かせいただきたいのですが、清掃工場の延命策というのをつくっていますよね。多分、そういった取組みによって延命策をされているのだと思うのですが、５０年と言われる最終処分場の現状についてお知らせほしいと求めました。","respondent":"小林品川区清掃事務所長","answer":"２つ目の、中央防波堤外側の埋立処分場その２ということで、昭和５２年の１０月から使用開始しております。将来のことは断言できませんが、５０年以上の使用継続が可能、見えてくるという状況かと考えております。","id":"exchange-112"},{"speaker":"本多委員","kind":"質問","question":"取組みの成果が出ていると認識しますが、この最終処分場５０年というカウント、算定はどこでされているのか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"もちろんその中で、明確に「５０年しかもたない」という表現はございません。そういった目途、５０年が目途になっていたというのが、当初の処分計画で算定されたものが若干ひとり歩きしていると受けとめております。","id":"exchange-113"},{"speaker":"本多委員","kind":"質問","question":"ちょっと次の質問に移りますが、ちょうど今１０月ということなのですけれども、結構そういった手作業が多いのだなと思いました。２３区と連携した啓発活動、不適正搬入防止について、その辺の連携・連絡について説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"自分の目でその実態を確かめながら、できれば車に入れる段階で、不適正なものについては可能な限り排除していこうという連携をとっているところです。Ｄのランクに分けて、可能な限りオールＡになるように、不適正な搬入がないようにということで努力しています。","id":"exchange-114"},{"speaker":"本多委員","kind":"意見","question":"最後に１点だけお聞かせください。平成２７年度には１６カ所、３０６本、現状を説明するよう求めました。","respondent":"小林品川区清掃事務所長","answer":"保存樹だけに限りませんが、落ち葉等につきましては、所有者の負担と責任で処分するということで、清掃事務所で受けております。もちろん、地域への貢献等を踏まえて、適切に臨時ごみとしての費用負担をいただいて処理しています。","id":"exchange-115"},{"speaker":"南委員","kind":"質問","question":"１４４ページのがん検診とその他の健診について伺います。各種検診を品川区は実施しておりますけれども、検診をしている目的というのは何でしょうか、改めて伺います。","respondent":"川島健康課長","answer":"検診の目的につきましては、区民の方の健康を守るということ、それで安全安心、それでいつまでも元気に暮らしていけるというのが最終目的になろうかと思います。","id":"exchange-116"},{"speaker":"南委員","kind":"質問・要望","question":"それで、しっかり健診を受けてしっかり治すことは重要だと思っているのですけれども、改めて健診の重要性について見解を伺いたいと思います。その中で、改めて受診率について、それぞれのがん検診の受診率を伺いたい、教えてほしいと求めました。","respondent":"川島健康課長","answer":"喉頭がん検診は、喫煙者等が対象になっている関係上、受診率の算定ができません。これまで我々の区としての地道な周知の工夫や啓発の取組みも少しずつ成果があらわれているのではないかという自己分析もしています。","id":"exchange-117"},{"speaker":"南委員","kind":"質問・要望","question":"受診率を上げる工夫、努力をどういうふうに捉えているのか、そこをひとつ伺いたいと思うのです。そういう努力をやはりしていただきたいと思っているのが１つですので、そこを伺いたいのと、料金はたしか数百円かかりますよね。","respondent":"川島健康課長","answer":"私ども、４０歳以上の世帯には毎年、がん検診のお知らせのリーフレットを郵送しております。受診率が少しずつでも向上するということ、もしくは意識が変わって、受けたいと思ったら受けられるといった環境をつくっていると考えています。","id":"exchange-118"},{"speaker":"南委員","kind":"質問・要望","question":"ほかのところでそういう体制をぜひとるべきだということについて、見解をお願いしたいと思います。その点についての見解を伺いたいと思います。","respondent":"川島健康課長","answer":"区の中での生活習慣病健診に位置づけて実施している自治体が増えているということなので、少し私どもも研究していきたいと考えているところです。","id":"exchange-119"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういうことにしっかりシフトしていただいて、健診に入れていただきたいと思っています。その点だけお願いします。","respondent":"川島健康課長","answer":"そういったものもわかるような検診のことを私ども考えているのですけれども、広く検診の導入ということですので、いろいろと検討していきたいと思います。","id":"exchange-120"},{"speaker":"たけうち委員","kind":"質問","question":"ちょっと今とまっているのかと思うのですが、今この民泊についてどのような形で検討されているのか、２点お聞きします。決算では６,６００万円、約６割弱ということなのですが、これについてなぜかということをまず説明を求めました。","respondent":"鈴木文化観光課長、柏原企画調整課長、山崎商業・ものづくり課長","answer":"文化的な情報の発信という機能が中心ではありますが、ある意味、品川区の歴史的な魅力という部分では観光の資源になると考えております。今年… 民泊の検討状況です。我々も民泊の立ち位置といいますか、品川区独自の考え方というのは整理しているところではありますが… 結果としましては、実施されたのがそのうちの５つということで、４つの中止事業が発生したというようなことです。","id":"exchange-121"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それで、歴史館もちょうど昭和６０年に開館して３２年になるのですか。一体的にこういうのをどうしていくのかというのを、また検討しなければいけないのかと思うので、何か所感があれば教えていただきたい。","respondent":"鈴木文化観光課長、山崎商業・ものづくり課長","answer":"ただし、位置づけとしましては、やはり区の重要な歴史を伝える施設として、今後も重要性が増してくると考えています。十分観光のコンテンツになると考えておりますので、運営、それから活用を図っていきたいと考えております。 そこの耐用年数の１０年という縛りがありまして、この間、東京都に強力に要請をしております。解釈が前進しておりますので、こういった事例も含めまして、しっかり東京都とは交渉してまいりたいと考えています。","id":"exchange-122"},{"speaker":"たけうち委員","kind":"質問","question":"歴史館のほうはまたぜひよろしくお願いします。東京都も、もうそれでいいよというふうになったということだと思いますけれど、それは区商連とか関係者の方はご存じということでいいのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"担当者とやりとりをしまして、メールと、しっかり東京都からも通知といいますか、文書も９月１６日付けでいただいた、ほやほやなものです。","id":"exchange-123"},{"speaker":"伊藤委員","kind":"質問","question":"成果報告書１５４ページ、観光アクションプラン推進事業に関連して質問します。区内にあるマスコミが参加していないのはなぜかということと、いかがでしょうか、現時点でのお考えを説明するよう求めました。","respondent":"鈴木文化観光課長","answer":"具体的には、また事業推進にかかわる関係機関や団体との連携・調整に関することというような大きな機能を持っているものです。まちのコミュニティ雑誌であったり、それからケーブルテレビ品川といった、身近なマスメディアの皆さんには参加をいただいているところです。","id":"exchange-124"},{"speaker":"伊藤委員","kind":"質問","question":"品川区内にテレビ東京があるわけですから、さまざまな形のものを外に出していくことを企画してはいかがでしょうかということをお伺いするのと。そして計画を具体化していくことのほうが、私はこの目的に沿っていると思うのですが、いかがでしょうか、ご答弁をお願いいたします。","respondent":"鈴木文化観光課長","answer":"特に重要性に鑑みまして今年度につきましては、情報発信強化部会という専門部会を立ち上げまして検討していますので、その検討結果も踏まえまして。区はそのための支援、ご指摘のような、官民一体で取り組むという体制を組んでいるところです。","id":"exchange-125"},{"speaker":"伊藤委員","kind":"確認","question":"基本計画ではなくてアクションプランを具体化していくことの方向が確認できたと思いますけれども、東急バス等々、いろんなところが入っていますよね。そのホームページを見たらわかるようなことができれば、非常に観光振興に役立つと思うのですが、いかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"観光に携わるいろんな事業者への情報提供、それとホームページ、さまざまな媒体を使っての情報発信を試みるところです。それから３カ月単位ぐらいの詳細のスケジュールというものをまとめたものを、今、次のステップに向けて歩みを進めたいと考えております。","id":"exchange-126"},{"speaker":"伊藤委員","kind":"意見","question":"いろんな団体が集約されて１つのホームページで見られれば、観光振興協議会の方々に対する働きかけなり、それから民間の情報が少ない気がするのです。","respondent":"鈴木文化観光課長","answer":"そして区のＰＲと、さまざまな媒体と主体の持ち味を活かした情報発信を総合的に活用することで、しっかりと品川区の観光についてのＰＲをしていきたいと考えております。","id":"exchange-127"},{"speaker":"伊藤委員","kind":"質問","question":"だから、ゆるキャラの考え方について改めてお伺いしたいのと、それから品川区のキャッチフレーズ、今、「わ！だから、それから品川区のキャッチフレーズを定期的に変えてはいかがでしょうかということをお伺いしたいのですが、いかがか尋ねました。","respondent":"鈴木文化観光課長、中元広報広聴課長","answer":"区のイメージとしてのゆるキャラですが、区内にはこれまでに各商店街等で取り組んでいただいて生まれましたゆるキャラが幾つもあります。ある会社のキャラクターと連携しながら、品川区の観光イコール… キャッチフレーズのことについてでしたので、私のほうからお答えします。いましばらく活用し、前後に言葉をつなげて展開していくということで、特に変えるという考えは現段階ではございません。","id":"exchange-128"},{"speaker":"伊藤委員","kind":"提案","question":"だから、それを品川区で展開してみたらどうですかということを提案するのです。そういうふうにして、何というか、具体的に品川区をＰＲすることも検討してみてはいかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"ご指摘のありました、映像による品川区の観光魅力の発信ですが、実は、来年度予算の編成の中で、同様の施策についての検討をしています。これからの検討ですが、その手法も含めて、より効果的に品川区の観光をＰＲできる映像制作に取り組みたいと考えております。","id":"exchange-129"},{"speaker":"伊藤委員","kind":"質問","question":"バレンタインのときもＬＥＤをやると聞いたので、それは１つの観光名所になる可能性があるわけではないですか。ある意味新しい観光スポットができる可能性もあると思うのですが、いかがでしょうか、ご答弁をお願いいたします。","respondent":"鈴木文化観光課長","answer":"ＮＨＫのほうの了解が得られるかどうか、ちょっとわかりませんので、コンタクトはとってみたいと考えています。若い方たちにアピールできるという仕掛けを考えながら、２人のカップル、多くの方に来ていただけるようなイルミネーションにしたいと考えております。","id":"exchange-130"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひ検討をお願いいたします。ＬＥＤ化していくなり、やはり１つ前に出た具体的な施策を検討してみてはいかがでしょうか、最後に答弁をお願いいたします。","respondent":"鈴木文化観光課長","answer":"大井町駅のイルミネーションにつきましても、昨年度、エリアの関係事業者の方等のお話を踏まえまして、今回ちょっと一部、銀行側にエリアを広げたりという工夫をしておりますので、今後もしっかりと進めていきたいと考えております。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"区の施策に大きくかかわる財政課にお聞きしたいと思います。今の現在、区内の中小企業、産業の経営実態をどのように把握されているのか、お聞きしたいと思います。","respondent":"秋山財政課長","answer":"先行きが大幅に改善する見込みのある業種もあれば、前もお話しさせていただいたように二極化という、業種の中でも二極化がある。それから個店を見ても、その業種の中でもいいお店もあれば悪いお店もあるというところが１つの評価であると考えています。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"こちらの販売、どうですか」。それとも実態はわからないということか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"企画部門と連携しまして、１,４００件の企業に年間を通じて、いろいろ相談を経てそのようなことをしています。「悪い」「やや悪い」と答えたのが１６％で、先ほど財政課が二極化という、まさにそういうことかと。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"私はよく調べてほしいのは、勤労者の４割が非正規雇用ということと、そして上がらない正規雇用者層というのがあるのです。やはりきちんと把握すべきだと思うのですが、そういうのは把握しているのでしょうか、その辺についても説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"まさに消費者の動向と申しますのは、区民の方々の個人消費の動向というようなことかと考えています。なかなか商店街もお悩みですけれども、区としてはそういう中でもいろいろなご支援を工夫していくというようなことで対応しているものです。","id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"でも、想定外の黒字が出たら、実質収支の１割ぐらいは、私は低所得者層にやはり還元すべきではないかと思う。だったら、皆さんが大変なら、私たちもやはり、返せるものは返すという姿勢も大事ではないか尋ねました。","respondent":"秋山財政課長","answer":"想定外の黒字というお話ですけれども、そういうときにこそ、景気が落ちて財政が落ちたときのために基金を積むというのが王道だと考えております。こういうときに使ってしまって、実際に景気が落ちたときに使うものがないという状態を避けるのが財政の仕事だと考えております。","id":"exchange-135"},{"speaker":"大倉委員","kind":"質問","question":"１５５ページ、中小企業ワークライフバランス支援事業に関連して、あと１４８ページ、環境費、ちょっと関連して食品ロスについて伺いたいと思います。“もったいない”推進店について伺いたいと思いますが、全世界の食料援助量の約２倍ということで、現状と目的について説明を求めました。","respondent":"山崎商業・ものづくり課長、三ツ橋環境課長","answer":"こちらは、事業のほうは平成１９年度から開始しています。次世代育成支援対策推進の取組みの一環といたしまして、仕事と家庭のバランスのとれた雇用環境づくりを支援するということを目的に、推進するです。 環境に配慮したものと考えておりまして、日本の共通語の“もったいない”という精神に基づき、食品ロス削減ということが目的となっております。現状ですけれども、９商店街６９店舗、平成２８年９月末です。","id":"exchange-136"},{"speaker":"大倉委員","kind":"質問","question":"民間企業など等と書いてありますが、総勢１０１名でやっておりますが、こうしたイクボス宣言、非常に重要かと思います。このイクボス宣言についてお考えを説明するよう求めました。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味では、１つの事業所として区役所内の所管部で、そうしたことを推進しているというようなことです。中小企業のほうの支援事業も含めまして、経営者の考え方というのですか、そういったもので受けとめさせていただきたいと思ってあります。","id":"exchange-137"},{"speaker":"大倉委員","kind":"質問・要望","question":"お考えを教えていただきたいのと、３０・１０運動というのがされておりまして、新年会・忘年会の開始後３０分は食事だけにする。毎月３０日を冷蔵庫クリーンアップデーとして、毎月１０日を“もったいない”クッキングデーなどと、お考えを説明するよう求めました。","respondent":"米田人事課長、三ツ橋環境課長","answer":"次世代育成支援推進行動計画あるいは女性活躍のための行動計画というようなことで、事業者として推進しているところです。より目標を設定して、またこれに取り組んでいきたいということで… 今後はどのようなものがいいのか、品川区としてどのような考え方がいいのか、さまざまな取組みがあります。今回の委員ご指摘の３０・１０運動なども考えながら、今後、品川区として一番いいものを考えていきたいと考えています。","id":"exchange-138"},{"speaker":"大倉委員","kind":"質問・要望","question":"品川区もぜひ宣言も目指して取組みを前に進めてほしいと求めましたので、これはちょっと、ぜひ考えていただければと思って要望します。ぜひ今後さらに食品ロスを減らせるように取組みを、さまざまな自治体も見ながら行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１４８ページの環境対策費のところから、羽田新ルート計画が品川区の環境に及ぼす影響についてお伺いしたいと思います。この環境省が出している報告書について、区としてどう捉えているかをお聞かせほしいと求めました。","respondent":"三ツ橋環境課長","answer":"八潮局では一般局、また大井中央局、平塚橋など、自動車排出ガスの測定を実施しております。今、委員ご指摘の平成２４年度の船舶・航空機排出大気汚染物質削減に関する検討調査につきましても、今現在のところは測定している状況です。","id":"exchange-140"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、私は東京都と同様、品川区としても国に対してこのことを求めるべきではないかと思いますけれども、いかがでしょうかということです。そして、大気汚染についても、実態や影響を明らかにさせて区民に説明をするべきではないかと思いますが、いかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"実際に、まずは品川区の中で、八潮局であったり、いろいろな部分についても把握していかなければならないと考えています。ＰＭ２.５につきましても、環境基準というものが非常に微小ですので、測定の方法なども踏まえながら考えていきたいと考えています。","id":"exchange-141"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"明らかにしていくということが求められていると思いますので、ぜひ区としても認識を持って報告するようにということで求めてほしいと求めました。今度は１３２回、１時間に４４機が３時間ですから、ちょっと伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"こちらの環境基本法の中の１６条の中では、航空機の騒音や新幹線の騒音というものは、普通の環境基準について除かれるというものになっております。したがいまして、今回の特定建設作業が８５デシベルとなっている場合、今回は違うものと考えております。","id":"exchange-142"},{"speaker":"浅野委員","kind":"質問","question":"そのような場合については、やはり何らかの形で縛りというのでしょうか、知らない間にどこかで使われているということもあるかと思います。このような場合については、区のほうに相談とか、そのようなことは来るのかどうか、説明を求めました。","respondent":"三ツ橋環境課長","answer":"パネル設置に関しましての苦情ですけれども、ずっと助成を続けておりますけれども、特に苦情というものは来ておりません。そのほか、撤去の報告ですけれども、撤去の報告につきましては、今のところ環境課には来ておりません。","id":"exchange-143"},{"speaker":"浅野委員","kind":"質問・要望","question":"温室効果ガスの排出量について質問しますが、今の段階で、２０１３年の結果というものは既に出ているのかどうか。結果が出たら建設委員会にたしか報告されていると思いますけれども、これも結果が出たら早急に報告をお願いしたいと思いますが、いかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"一方、２０１３年度の地域推進計画の結果ですけれども、ほぼ品川区として確定しておりますので、近く建設委員会にご報告したいと考えています。実行計画は特にしながわエコリンクを昨年度から実施いたしておりますので、品川区の庁内全体に環境への配慮、力を入れております。","id":"exchange-144"},{"speaker":"浅野委員","kind":"質問","question":"今回、モロッコのほうでＣＯＰ２２が開催されますけれども、それにも参加できないというような報道もされております。日本の立ち位置がかなり変わってくるのかとも思いますが、この件に関してどう捉えられているのか説明を求めました。","respondent":"三ツ橋環境課長","answer":"１０月１１日に閣議決定、案ですけれども、されたという情報は得ております。非常に重要だと考えていますので、この３計画、今後考えていかなければいけないものを盛り込んでいきたいと考えています。","id":"exchange-145"},{"speaker":"浅野委員","kind":"質問・要望","question":"もう一点ですけれども、東京都においては、東京都環境基本計画を今年の３月に既に作成してあります。２０３０年までに、そしてまた環境３計画の改訂についての基本的な考え方、また策定時期について説明を求めました。","respondent":"三ツ橋環境課長","answer":"このたび東京都が策定いたしました、委員ご指摘の環境基本計画ですけれども、非常に厳しいパーセンテージになっていると考えています。委員ご指摘の３計画につきましては、そちらがＣＯ２削減なのか、そのあたりも考えながら実際につくっていきたいと考えています。","id":"exchange-146"},{"speaker":"浅野委員","kind":"質問","question":"最後になりますが、１５７ページの外国語版ホームページ作成経費助成について簡単に質問します。このホームページをつくって、外国からのアプローチが実際にあったのかどうか、その例があれば説明を求めました。","respondent":"立木産業活性化担当課長","answer":"こちらのホームページ、つくった結果、アクセスがあったということ、それから問い合わせ、メール等、入っているということは聞いてありますが、ちょっと具体的な数字に関しましては、そこまで手元にございませんので、申し訳ございません。","id":"exchange-147"},{"speaker":"鈴木（真）委員","kind":"確認","question":"この辺の実態と、今どういうふうになっているのか、まずそれを１点お願いします。ですから私も、予算特別委員会でもこの件を確認させていただいたのですが、町会での資源回収のやり方についてもう一回確認したいと求めました。","respondent":"三ツ橋環境課長、小林品川区清掃事務所長","answer":"環境指導相談費の土壌汚染に関する相談件数ですけれども、中心となるものは不動産業者であるとかディベロッパーなどが確認している件数となっております。 その行動をもって、副次的には町会、地域力が増すことにも貢献できるものということで考えております。実質的な利益としては、回収しました資源について、キロ６円の活動費として助成しています。","id":"exchange-148"},{"speaker":"鈴木（真）委員","kind":"質問","question":"どういうふうにチェックしていくのかというのが、大きなものも全て区でやっていくのか、その辺を教えてください。今、一般の区の収集と集団回収をどう切り分けていくのか、そこのやり方をもう一回説明を求めました。","respondent":"三ツ橋環境課長、小林品川区清掃事務所長","answer":"３,０００平米以上のものにつきましては、東京都が届け出受理をしておりますので、そちらは東京都に対していろいろな状況を確認しております。実際に環境課が相談役となって、そのあたりのことについては取りまとめをしておりまして… 行政回収としての資源回収と集団回収との関係ですけれど、基礎ベースはあくまでも区の行政回収です。","id":"exchange-149"},{"speaker":"鈴木（真）委員","kind":"質問","question":"よく昔、クリーニング屋が廃業すると、土壌汚染の問題が出てくるというお話を聞かれて相談も受けたことがあります。こういうときの対応というのは、区のほうとしてどういうふうにやっていらっしゃるのか、その点を説明するよう求めました。","respondent":"三ツ橋環境課長","answer":"それは有害物質を取り扱っているためですけれども、そちらが廃止する場合には、区の環境課に届け出が必要です。土壌汚染対策防止法にのっとりまして、また環境確保条例上にのっとりまして、対応してまいります。","id":"exchange-150"},{"speaker":"鈴木（真）委員","kind":"確認","question":"もう一点確認したかったのが、１５１ページの、東京二十三区清掃協議会負担金の件です。清掃協議会の運営は２３区ということは、１,１５０万円の予算を組んでいるということでよろしいのか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"ご指摘のとおりです。","id":"exchange-151"},{"speaker":"鈴木（真）委員","kind":"質問","question":"一緒に聞けばよかったのですけれど、改めて清掃協議会の今の業務内容について説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"２つ目が浄化槽清掃業の許可に関する事務です。３つ目が、雇上車、雇い上げ車両の関係事務を統一的に行ってあります。","id":"exchange-152"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の許可事務ですか、これは平成１２年に清掃が区に移管したとき、あのときにいろいろ検討したと思うのです。協議会の今の事業内容からすると、こういう話題というのは２３区の中で検討にも上がっていないのかどうか、そこら辺を説明するよう求めました。","respondent":"小林品川区清掃事務所長","answer":"目的が２３区共通で、それを集中して共同処理したほうが効率的であるという点に着目したものです。全て権限は区長にありますので、その各区の独自性と区長の権限を協議会のほうが代行しているという関係は基本として確認されているところです。","id":"exchange-153"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/678897?Template=document&Id=1426#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":116601,"voices":359}},{"id":"h28-20161014-4","meetingId":"h28-c-settlement","date":"2016年10月14日","dateIso":"2016-10-14","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を153件整理しています。","topics":[{"id":"topic-01","title":"◯こんの委員長 ただいまより決算特別委員会を開会いたします。 それでは、平成２７年度品川区一般会計歳入歳出決算","agenda":"◯こんの委員長 ただいまより決算特別委員会を開会いたします。 それでは、平成２７年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"成果報告書１５９ページ、駅周辺等放置自転車対策事業の放置防止指導啓発について、お伺いをいたします。そのことについて、私道にかかるところですけれども、今現在、区として鉄道事業者に対してどういった取組みをしているのか、お聞かせ願います。","respondent":"桑波田交通安全担当課長","answer":"花壇等があるのですけれども、そちらに単管バリケード等を設置して止めさせない措置を行うことについても、東急に了解をいただいているところです。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"その辺含めて対応をよろしくお願いしたいということで、これは要望なので、よろしくお願いいたします。そういったところを区としても前向きに検討されているのか、改めてお知らせほしいと求めました。","respondent":"溝口公園課長","answer":"これにつきましては、今年８月、オリンピックの正式種目に決定するなど、今後、スケートボード競技人口の増加が見込まれるところです。そういったところを受けて、区内でもスケートボードができる公園の整備は前向きに検討していきたいと考えているものです。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"意見","question":"場所等、どこをお考えになっているのか、わかる範囲でお知らせくださいとの意見を述べました。","respondent":"溝口公園課長","answer":"そういったところの話を聞くと、近隣への騒音の問題、また、利用者のマナーの問題などに課題があると聞いているところです。できるだけ早くスケートボードができるような公園ができるように、今、検討を進めているところです。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"４年後、また未来ある子供たちのためにも、スケートパークをぜひ検討してほしいと求めました。続きまして、１６８ページ、密集住宅市街地整備促進事業について、お伺いをいたします。","respondent":"古巻防災課長","answer":"感震ブレーカー設置推進事業ですけれども、今年度より設置の助成を開始したところです。感震ブレーカーを設置する木造戸建て住宅所有者の方に対しまして、分電盤タイプの感震ブレーカー設置助成、助成の申込みを受けているところです。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今現在の、既存住宅の取り付け申込み件数と新築住宅の取り付け申込み件数がわかれば、説明を求めました。","respondent":"古巻防災課長","answer":"それから、新築住宅に関しましては１件のお申込みがあります。お申込み１３６件ありますけれども、それから見積もりを出していただいて、申請いただいている件数につきましては本日現在で３６件です。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ハウスメーカー等への告知といいますか、そういった活動はしているのでしょうか、説明を求めました。","respondent":"古巻防災課長","answer":"周知に関しましては、今現在、区として、ハウスメーカーへ直接周知という形では行っておりませんで、個人の方、新築される方も含めて、地域の方に対しての周知をしているという状況です。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今、この設置推進事業の助成制度については、木密地区が限定だと思うのですけれども、今後、区内全区域に対してこういった助成制度をやるのか、やらないのか、説明を求めました。","respondent":"古巻防災課長","answer":"感震ブレーカー設置助成のエリアに関しまして、現在、木密の整備地区を重点ということで、普及促進のためにエリアを定めております。ここに注力したいという考えがありますので、現在のところ、エリアを拡大するという考えはございません。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ぜひこの助成制度をよろしくお願いしたいと思います。そういった中で、区としてどういうお考えをしているのか、説明を求めました。","respondent":"寺嶋木密整備推進課長","answer":"緊急の措置として、先ほど防災課長からご答弁申し上げましたとおり、感震ブレーカー等による対応が現時点では効果的であると考えております。引き続き、地区の皆様と検討、勉強を進めながら、改善に向け、取り組みたいと考えております。","id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問","question":"木密地域の感震ブレーカー設置について、先ほど件数を教えていただきましたけれども、現在、旗の台四丁目地区ではどの程度申込み件数があるのか、わかれば説明を求めました。","respondent":"古巻防災課長","answer":"申し訳ありません。今、手元に地区ごとの件数は持ち合わせておりません。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"自転車スマホの危険性というところで、品川区がどういうふうに対策を進めていただけるかという現状を確認させていただきたいと思っています。あわせて、現在までに品川区の中で歩きスマホ、自転車スマホで起きてしまった事故とかがあるのかどうか、確認をしたいと思います。","respondent":"桑波田交通安全担当課長","answer":"そのチラシの活用のキャペーン実施、そういった場面を想定した事故再現ということで、区民の方には周知させていただいているところです。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問","question":"区内では事故がないということですね。よろしいか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"区内の事故は、統計がとれておりませんので、あるかどうかは判明しておりません。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"区内でどうなのかということは気になるところなのですが、これはまた何か統計をとれる手段があるのであれば、確認をしてほしいと求めました。は、例えば主要駅などでの街頭キャンペーンですとかもぜひ折々にやっていただきたいなと思いますが、いかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"交通につきましては各警察署でキャンペーン等を実施します。それはそれぞれの所管で、関係機関と連携をとりながら、対策を実施しています。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"次に、自転車走行レーンについて、お伺いいたします。平成２７年度、区内調査をされていると思いますので、調査結果と、現状どこまで進んでいるのかということを教えてほしいと求めました。","respondent":"多並道路課長","answer":"今後についてということですけれども、この中から今後の進め方は検討するべきと考えております。よく見られる青色で塗ったレーンが区で実施したものなのですけれども、ピクトグラム、合わせまして８.７kmというのが今までの実績です。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"それともう１点、何度か質問でも取り上げておりますけれども、そういう声が消えないのです。例えば色を塗らないで、走行の指示だけするようなタイプが可能なのかということを教えてほしいと求めました。","respondent":"多並道路課長","answer":"これについて、国や都と連携して、どのように進めていくかということを検討している最中です。これについては、八潮の地域も今後、路線が違うところもありますので、このような形で整備を進めたいと考えているところです。","id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"家具転倒防止器具取付助成ですが、３０万円の予算に対して決算額が８,０００円ということで、ちょっと進んでいないなと感じるところがあります。１件なのか２件なのかという感じだと思いますけれども、平成２７年度、平成２８年度も含めて現状をお知らせほしいと求めました。","respondent":"今井住宅課長","answer":"地域活動課と連携いたしまして地域センター等、障害者に向けての購入および取付助成もありますので、高齢者地域支援課とも連携して周知しています。","id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"地域センターで周知されているということでしたが、支え愛・ほっとステーションでもぜひ強力に周知してほしいと求めましたが、いかがか尋ねました。","respondent":"今井住宅課長","answer":"支え愛・ほっとステーションは特に福祉の分野もありますので、先ほどの所管課と連携しながら対応してまいりたいと考えています。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"繰り返し一方的に転出を求めることはありませんとお話ししますが、お話を伺った方は、私有財産をなぜ奪えるのかと話しておりました。そして改めて、権利者の全員合意が区の基本原則なのか、ここも確認したいと思います。","respondent":"稲田都市開発課長","answer":"３分の２以上の同意を求めながら進めてきているというところと、また適正な評価をしながら、進めてきているものです。それを基本として進めているところです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"ご答弁では、権利者の方に丁寧に対応しているということでしたけれども、私が伺ったのは、なぜ追い出されたとの声が権利者より上がるのか、この理由を伺いたいと思います。","respondent":"稲田都市開発課長","answer":"丁寧に説明をしている、権利変換計画縦覧のときにおきましても、意見を申し立てるところもあります。客観的な審査が審査委員によって行われて進められるというところで進めておりますので、追い出されたというところはないと感じております。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"伺いますけれども、さらには解体工事では１０人もの権利者が同意していないのに、開発計画を進めている。そして、区がたびたび言う一方的ではないというのは、どういう状態のことを指すのか、ここも伺いたいと思います。","respondent":"稲田都市開発課長","answer":"そういった形で進めてきておりますので、一方的ではないと考えております。工事を進めてきているところですが、建物等を取り壊していくということが進められるものでございまして、これに従いながら現在やっているところです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、２割を超える約１６人の地権者が同意していない。結局、全員同意というのは建前なのか、その点も伺いたいと思います。","respondent":"稲田都市開発課長","answer":"都市開発法に従って３分の２以上というところで進めてきているところですが、そういうところで話が折り合わないところもあります。そういう中で事業も進めていくというところで、やっているところです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"つまり、もともと同意していない人がいるのに進めるため、追い出された、私有財産をなぜ奪うのかという声が上がるのではないでしょうか。この点も改めて伺いたいと思います。","respondent":"稲田都市開発課長","answer":"それから丁寧な説明、今までも、大井一丁目南第１地区につきましてお話を続けてきているところです。まだ同意をしていない方がいる中におきましては、影響のない範囲で取り壊し等の工事を進めてきていると聞いております。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"先ほどから丁寧に説明をしていると述べていますが、なぜ住民から追い出されたとの声があるのか。この仕組みが、追い出されたという声が上がる一番の原因だと思いますけれども、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"権利変換計画の案の時点で縦覧公告をするわけですが、その中で意見書を出すことができるというところもあります。それに従って再開発事業を進めているものですので、決して追い出す、追い出されたというようなことにはならないと思います。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"どんなに丁寧に説明と言ったって、結局はこの二者択一を早く選べるように説明をしているだけですから、住民にとっては追い出されたにほかなりません。もう１つ、マンションに入ることも引っ越すこともどちらも最後まで徹底して拒み続けると、最後の最後、最終的にはどうなるのか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"何度も意見を言う場を設け、また、話し合いの場も設けて進めてきておりますので、一方的に転出を求めているところには立っていないです。拒み続けると最終的にどうなるのかですが、最終的には裁判という形になってくるです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"地域コミュニティをつくるといいますが、壊しているだけではないでしょうか。住民コミュニティを壊している自覚があるのか、その点、最後に伺いたいと思います。","respondent":"稲田都市開発課長","answer":"再開発事業というものは、地域のいろいろな課題を解決していって、新たなまちに更新し、地域の発展につなげていくというものです。決してそのようなことではないというところです。","id":"exchange-024"},{"speaker":"木村委員","kind":"質問","question":"２億７,０００万円余からの質問ですけれども、一体性、大井町駅周辺地区バリアフリー計画を平成２７年３月２０日に策定されました。あるとすれば、どういうところか尋ねました。","respondent":"多並道路課長","answer":"この中でも、品川区としては長期基本計画に基づき、計画時に道路工事にあわせて段差解消や歩道の平坦化などを進めてまいりました。連携を図りながら進めるということを今までやってまいりましたので、一緒により良いまちづくりを進めていきたいと考えているものです。","id":"exchange-025"},{"speaker":"木村委員","kind":"意見","question":"ゼロ段差、また２センチ段差と分かれていますけれども、なぜ１つのところにゼロ段差と２センチ段差が共存するのか。全てをゼロ段差にすべきと思いますけれども、分ける理由を説明するよう求めました。","respondent":"多並道路課長","answer":"平成５年から始めていますけれども、フラットな側溝を使ったりして、より使いやすい歩行環境等を今まで進めております。約１ｍちょっとですけれども、それ以外の場所は２センチ段差とするような工夫もしながら、よりお使いいただきやすい構造を進めているものです。","id":"exchange-026"},{"speaker":"木村委員","kind":"質問","question":"ちょっとした段差につまずいてしまうようなこともあろうかと思いますけれども、その周知の仕方はどのようにするのでしょうか。八潮団地の、道幅は変わらないのだけれども、歩道と自転車道をどのようにするのかということをもう一度説明を求めました。","respondent":"多並道路課長","answer":"ソフトの部門等も含めながら、そういう形の周知、広がりということで我々としては考えているところです。自転車の走行空間をあわせてつくりまして、あわせて整備したことで、よりお使いいただきやすいような構造ということで検討したものです。","id":"exchange-027"},{"speaker":"木村委員","kind":"意見","question":"次に、オリンピック・パラリンピック施設周辺無電柱化事業ですが、多くの海外からの来訪者が見込まれています。大事な事業となるでしょうけれども、目標は平成３２年になっていると思いますが、計画を説明するよう求めました。","respondent":"多並道路課長","answer":"来年度としては、引込連系管といいまして、電線共同溝の地下からＮＴＴや東京電力の引き込んでいくほうの工事を予定しております。大田区と接続する道路でもありますので、大田区と品川区で連携しながら今一緒に、そこの工程も含めて工事を進めているところです。","id":"exchange-028"},{"speaker":"木村委員","kind":"提案","question":"区民が抱える生活上の問題とは、どういったことが１番にランクされているのでしょうか。そして、区民の皆さんからの声を、本区としてはどのように受け取り、そして、どのように解決しようと考えているのでしょうか、説明を求めました。","respondent":"中村都市計画課長","answer":"やはり皆様いろいろと心配をされたりするということで、相談に来られたりとか、そういったところがあります。それを地域の皆様とともに考えて、あるいは団体に対して補助金を出したり、あるいは専門家の派遣を行ったりということをしています。","id":"exchange-029"},{"speaker":"木村委員","kind":"質問・要望","question":"これは要望で、お願いをしたいと思います。ペーパーケースには鍵がついていることを私も確認をしたのですけれども、頻繁になくなるということでありました。","respondent":"溝口公園課長","answer":"清掃につきましては、毎日１回、必ず行っております。トイレも含めまして、皆さんに安全に公園をご利用いただけるように心がけて、維持管理を日々行っているものです。","id":"exchange-030"},{"speaker":"木村委員","kind":"意見","question":"２６６カ所もトイレがあるわけでありますから、それ以外の公衆トイレとか、また児童遊園などでも持ち去りが起きているのかどうか。それに対して将来的には処罰の適用は考えられるか、または考えているかということを説明するよう求めました。","respondent":"溝口公園課長","answer":"そのうち、公園・児童遊園合わせまして１２６カ所の公園トイレがあります。しっかり警察に被害届等を出しながら、これまでも対応していますし、今後も同じような対応をしていきたいと考えているものです。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"お伺いします。東京都への要望とか調整はどういう形で品川区としてはやっていくのかということと、それと、その辺のレガシーのことについてもお答えいただけますか。","respondent":"今井住宅課長、和田河川下水道課長、多並道路課長、小川オリンピック・パラリンピック準備課長","answer":"いわゆる民間の借上型区民住宅についての方針ですけれども、オーナーと十分協議を進めながら、そちらを廃止していくという方針に変わりありません。そのときは道路の埋設物が障害となっているため、その対応に時間がかかっており、当初よりも１年間工事が遅れるとご報告させていただいたところです… オリンピックに向けて大会組織委員会が、こういう部分も国とか都と連携しながら、その中でそういう整備を今検討しているところです。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"５０ミリの降水量でお水があふれてしまうわけですから。まだ２０２０年、そろそろ確実に具体的にもっと考えていただかないといけないと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"和田河川下水道課長、今井住宅課長、小川オリンピック・パラリンピック準備課長","answer":"本件につきましては、平成２３年から工事概要を説明し、今に至っているという状況です。半年なのか１年なのか、また都に帰ってからもこの工事には注視して… 住宅改善工事助成などの既存ストックへの支援ですとか、今年は１７億円を超える形で、住宅政策全体としては充実しています。多目的な競技に使えるようなスポーツの振興拠点としていきたいということで都には申し入れしています。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"同じく１６４ページの河川総務費の中の雨水流出抑制推進事業、それから１６８ページの都市開発費の中から観光まちづくり整備事業について伺います。数字の目標などが読み取れませんでしたので、どのように進めていくのか、計画などを教えていただけたらと思います。","respondent":"多並道路課長","answer":"年間２０カ所ということで、これは実施計画に基づき現在進めているところです。その後の実施の段階で、最終的には実績でこういう数字と少しずれていくような形になりますけれども、そういう進め方で進めております。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"要望がそれぞれ出て、それに対応できるという点についてはいいと思うのですけれども、もう少し計画性があってもいいのかなと。もう少し具体的に、ご要望があったときにお答えできるだけの情報をいただけるといいのですが、お願いします。","respondent":"多並道路課長","answer":"区として取組んでいる考え方としましては、区道関係なく、そういういろいろな視点でご意見をいただいているところです。進めていく事業になっていますので、そういう事業計画を持ちながら、また都道の場合は都に要請していくなどの形で行っているものです。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ当事者のご要望をよく聞き取った上で、進めてほしいと求めました。確認なのですが、改めて合流改善事業の意義、趣旨について、端的にお答え願えますか。","respondent":"和田河川下水道課長","answer":"合流ですから、水再生センターで処理できない分をどうしても河川に放流しなければならないという状況に東京都の下水道はあります。貯留管をつくり、初期汚水をそこにためて、河川の水質浄化に寄与するという事業です。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"そのためには、今進めている雨水流出抑制事業と抑制推進事業をどれぐらいまで進めるという目標は持てないのでしょうか。ぜひこの質問についても、両方の立場でこのような連携は考えられないか、お答えいただけないか尋ねました。","respondent":"和田河川下水道課長","answer":"この趣旨をもうちょっとわかりやすくＰＲできる方法を考えて、これまで進めてきた施策とあわせてＰＲを続けてまいりたいと考えています。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"下水道」キャンペーンについての連携はないのでしょうか。あの汚い白いぷかぷか浮いているものは何だということになるのではないかと思うのですが、その辺についての連携はいかがか尋ねました。","respondent":"和田河川下水道課長","answer":"東京都下水道局が主体として行っているものでありまして、連携と申しましたけれども、我々河川下水道課の廊下のところに「油・断・快適！","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"多分やっていらっしゃるに違いないと思うのですが、確認させてください。先日聞き忘れたのですけれども、その点、ちゃんと使われているかの確認をしていらっしゃるのか尋ねました。","respondent":"和田河川下水道課長","answer":"申し訳ございません。それから、区有タンクを工事する際にその施設の方々にどのような使用方法があるかということをきちんと説明をして、やっているところです。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ進めてほしいと求めました。残りの質問は、時間がなくなりましたので、機会を改めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"沢田委員","kind":"確認","question":"１６２ページの商店街電線類地中化事業と、それからオリンピック・パラリンピック施設周辺無電柱化事業でお伺いします。どういった経緯で始められて、また地域も若干あったかと思うのですけれども、どうなっていたのかを確認したいと求めました。","respondent":"多並道路課長","answer":"戸越銀座からお話ししますと、平成１８年度から平成２７年度の１０年間で事業を進めてまいりました。同じ割合で、国費が５億円、都費が１億円という事業でございました。","id":"exchange-041"},{"speaker":"沢田委員","kind":"意見","question":"平成１５年のときに５０の商店街でヒアリングを行ったということですが、どう見ているのか、お聞かせください。やり終えて、どういった場所が適しているかということもわかったかと思うのですが、今後の考え方について説明を求めました。","respondent":"多並道路課長","answer":"店舗を継続しなければいけないというところがありまして、営業が終わった後、夜中の２時とか３時に工事を行うなどの方法で対応したところであります。各電線企業と研究を進めておりまして、地上に置いた場合、もう少し小さくできないかということを検討しているところです。","id":"exchange-042"},{"speaker":"沢田委員","kind":"質問・要望","question":"ガス、水道料が７,１１７万円と書かれていますが、この内訳をお聞かせください。区がこういうことを負担しているという状況について、どういうときに使われているのか、説明を求めました。","respondent":"溝口公園課長","answer":"皆さんが水を飲まれるための水栓または手洗い、トイレが設置されているところであればトイレの流す水、そういったものに使われているものです。そういったもので使っているものです。","id":"exchange-043"},{"speaker":"沢田委員","kind":"意見","question":"よく公園等で、町会とか地域の方がいろいろなイベントをされます。やっぱり町会や地域団体の支援ということも考えて、こういったことができないのかなと思うのですけれども、そのあたりのお考えを説明するよう求めました。","respondent":"溝口公園課長","answer":"街路灯とかにつきましては、家庭用の電気家電を使ったりとか、そういった製品を使ってやるというのは難しい状況ではあります。そういったところを含めて、また改修の時期も見極めながら、どういった形で対応できるかを検討していきたいと考えているものです。","id":"exchange-044"},{"speaker":"つる委員","kind":"質問・要望","question":"１７０ページ、１６０ページの道路空洞修繕について、伺っていきたいと思います。平成２４年第４回定例会の一般質問で、私も、防災上重要となる避難所周辺、病院周辺に隣接する区道の電線類地中化を優先的に実施すべきと求めました。","respondent":"多並道路課長","answer":"先ほどご説明させていただきましたが、狭い区道の中で地中化をする、いわゆる避難施設へ行く道路ですから、さらに狭い区道になっています。我々としてもそこを注視して、今後どのような整備ができるかというのをその中で見て、検討していこうという方向性です。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問・要望","question":"これまで以上に区市町村に対して支援策の拡充を求める質問をする中で、防災性の向上を図るためには、電柱や電線をなくしていかなければならないと。改めてその方向性の確認と、それから都に求めるべき点が何かあれば、改めて伺いたいと思います。","respondent":"多並道路課長","answer":"国の今の動向をしっかり受けとめていくというのは１つですけれども、特にオリンピック会場周辺で進めているのが今の流れです。一番大きいのは、要するに狭い中で技術的に何か可能な方法があるか、そこら辺をもう少しよく都と連携しながら探っていきたいと思っているところです。","id":"exchange-046"},{"speaker":"つる委員","kind":"質問・要望","question":"次に、１６１ページ、街路樹等維持管理費の視点で、街路樹の根っこが地上に張り上がってくる根上がりの対策について、伺っていきたいと思います。そこだけではなくて、１カ所修繕というか整備をするのにだいたいどのぐらいの費用がかかるのか、説明を求めました。","respondent":"多並道路課長","answer":"来年度にかけて撤去、新設という形で、植替えの計画を検討しています。確かにかむろ坂のところも実はありまして、そこもこの点検の中で一緒に見てきまして、何とか対応できないかと見ているところです。","id":"exchange-047"},{"speaker":"つる委員","kind":"質問・要望","question":"街路樹そのものの管理も含めて、今１カ所当たり、根っこを切ったり何だりというのを含めて１５万円ぐらいと伺いました。長い目で見たときに、そういう工法は非常に効果的ではないかなと思うのですが、同様の工法を区内で実施された事例があれば説明を求めました。","respondent":"多並道路課長","answer":"委員から今お話のありました工法につきましては、目黒川で実施した事例があるということです。目黒川の状況、効果を見ながら、やっていくかどうかもその中で検討していきたいと思っているところです。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"次に住宅費について伺っていきたいと思います。住宅確保要配慮者でありますが、この把握は住宅課としてできているのでしょうか、説明を求めました。","respondent":"今井住宅課長","answer":"障害者等、多岐にわたりますので、それぞれの所管で数字を確認して対応をしているところです。住宅課といたしましては、今、区営住宅等で障害者の方も利用できる、車いすの方も利用できる世帯の戸数などを把握しています。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"過去にも質問させていただきましたが、これまで私も、また区議会公明党としても繰り返し求めてまいりました。これについては過日、改めてその設置を求めたいと思いますが、検討状況を説明するよう求めました。","respondent":"今井住宅課長","answer":"平成２７年度中に、２３区では３区が設置しまして、今お聞きしているところでは、２区程度が設置に向けて検討しています。来年度検討を進める予定ですので、先ほど申しました高齢者地域支援課等と連携しながら、大きな形での居住支援協議会を検討する予定です。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ積極的によろしくお願いしたいと思います。国で目標としている平成３２年、１年でも早く設置をしていただきたいという思いで、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"１６５ページ、可動式ホーム柵整備助成、１６１ページ、視覚障害者用誘導タイル、１７０ページの崖・擁壁実態調査委託について、お伺いいたします。可動式ホーム柵整備助成の８８６万６,０００円、これはＪＲ大井町駅か尋ねました。","respondent":"中村都市計画課長","answer":"２０１６年が中延駅、２０２０年までに確実に設置をしていただくように、検討も一緒に行っていきたいと考えています。今後の予定といたしましては、大井町駅に平成３１年度末ということで予定をされておりまして、これは９月末に公表されたところです。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"早急な設置をすべき駅であると思っていますが、どのような働きかけをされてきたのか、お伺いするのが１点です。そして、ホームドアの早期設置と設置されるまでの駅員の配置、ぜひ働きかけをしてほしいと求めましたが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"旗の台駅のホームが狭いですけれども、２週間ほど前に安全について鉄道事業者と話し合いをする機会がございました。例えばエレベーターの設置ですと、これを念頭に置きながら、チャンスを……。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"危険な場所なのでホームドアをつけていただきたいというところの設置なのです。エレベーターとかではないです。","respondent":"中村都市計画課長","answer":"旗の台駅のホームドアにつきましては、平成３０年度、平成３１年度以降で計画があるところです。東急が２０２０年までという計画の中で検討を行っているですけれども、５番線、６番線につきましては平成３１年度以降に行っていくと聞いております。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問","question":"駅の安全点検、協議の場、働きかけをしてほしいという点はいかがでしょうか。ぜひ協議の場を持っていただくよう求めました。","respondent":"中村都市計画課長","answer":"ホーム柵の設置を急いでいただくということ、人的対応ということで、今そういった人的対応をしていただいているところでもあります。その点につきましては、今特に協議の場を設ける予定はございません。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"早期設置のため、ぜひ協議の場を設けて、積極的に働きかけをしてほしいと求めました。これをセットで設置を求めているところなのですが、１つ、その後の進捗があったら説明を求めました。","respondent":"中村都市計画課長","answer":"区内の信号の安全確保につきましては、意見をいただくごとに、交通管理者であります警察へその意見を伝えているところです。区といたしましてもなるべく早急にそういった対応をしていただくようにお願いをしているところであり、引き続き、またお願いしてまいります。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２０１４年、本当にご苦労してやってこられたご報告を受けましたが、今回の調査の後どのように周知を行っていくのか伺います。地域の現況の理解を深めるために、以前６地域で行った説明会などを繰り返す、丁寧な周知が必要ではないかと思いますが、いかがか尋ねました。","respondent":"鈴木建築課長","answer":"今６カ所指定しているところ、今後、検討していかなければいけないです。地域への今後の説明についてですが、当然ながら、区域指定の前に地域への説明や意見交換を行いながら進めていくという状況です。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区ホームページまたは品川ケーブルテレビでご確認くださいといったチラシが配布されたかと思いますけれども、このツールも、これが１点です。避難したくてもできない人の対策といった意味では、どういうふうになっているのか、お伺いいたします。","respondent":"鈴木建築課長","answer":"この呼びかけを開始したときに、事前の説明会、台風前に直接的な戸別訪問を行っております。それから避難行動の必要な方々も把握しておりまして、こちらの方々につきましては、ご家族が対応するとお聞きしています。","id":"exchange-058"},{"speaker":"あべ委員","kind":"質問","question":"１６８ページの大崎駅西口交通広場、それから１７０ページの親元近居支援事業について、お伺いしたいと思います。担当課として、この事業の存在意義をどのように受けとめていらっしゃるかということをお伺いしたいと思います。","respondent":"桑波田交通安全担当課長、今井住宅課長","answer":"そういった要望があれば、第二建設事務所へ連絡しまして、向こうで張りつけ等をやっていただく対策をとっているところです。 今私どもでアンケートをとりますと、やはりもともと引っ越しする予定があるとか、もともと三世代で近居する予定があったということで。この事業は子育ての交流、そういうふうな支援の中で、一定の目的を果たしていると考えております。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"そもそも走れないところを自転車通行帯と指定するよりは、駐輪場ということも視野に入れて活用を考えられたらと思うのですが、いかがでしょうか。まちづくりイベント、情報発信等委託についてなのですが、この委託の支出先と内訳について、説明を求めました。","respondent":"桑波田交通安全担当課長、今井住宅課長、稲田都市開発課長","answer":"山手通りの関係ですけれども、自転車が走行するための看板等、表示はされているものと認識しております。新宿、やはりこういったところは… やはりアンケートからも、近くに住むことでお互いに安心ができるからというところで、一定の政策目的を果たしていると考えております。… それから、夢さん橋のイベントの補助に、７３万９,２７２円。これは、一般社団法人大崎エリアマネージメントに出しております。","id":"exchange-060"},{"speaker":"あべ委員","kind":"質問・要望","question":"毎年出し続ける形が、これは区の仕事の出し方としてどうなのだろうかと思うのですが、いかがでしょうか。あわせて、各団体の年間の収入がどのぐらいあって、そのうち区関連が何割ぐらい占めているのかということも教えてほしいと求めました。","respondent":"稲田都市開発課長","answer":"継続的なまちの発展をやっていくというところもありまして、行政と、これらの一般社団法人に委託等を行っているものです。それから、大崎・五反田エリアマネージメントは４３５万円程度です。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問・要望","question":"１点だけ。区の労務管理チェックが行われているのかも説明を求めました。","respondent":"稲田都市開発課長","answer":"エリアマネージメントの活動が見えてこないですが、設立されてから進めてきております。今後もより一層発展していくと考えております。","id":"exchange-062"},{"speaker":"渡部委員","kind":"質問","question":"１６０ページとか１６５ページの道路の維持費とか公園の管理費のところで伺いたいのと、あと、都市計画総務費なのですが、先に聞きます。今後、必要があれば開催されるのかなと思っているのですけれども、そのようなことでよろしいのか尋ねました。","respondent":"中村都市計画課長","answer":"ご指摘のとおり、喫緊の課題がなかったためです。今後、必要に応じて開催してまいりたいと考えております。","id":"exchange-063"},{"speaker":"渡部委員","kind":"質問","question":"地域をどういうふうにしようかというところですから、会がないので、これは意見します。たしか前にも質問させていただいて、課長だったでしょうか、地域の方々の声により修繕する機会はないのか。","respondent":"溝口公園課長","answer":"平成２５年度で終了としておりますが、全く止めたわけではありませんで、やっているです。その都度、現地を確認し、必要なものの修繕を行いながら、公園の管理をしているというのが現状です。","id":"exchange-064"},{"speaker":"渡部委員","kind":"質問","question":"ボランティアといったらいいのでしょうか、あわせて伺いたいのと、教えていただけますか。","respondent":"多並道路課長","answer":"道路管理の件ですが、我々の管理のあり方としては、点検業者が区内の３地区で点検に回っているという形でやらせていただいております。平成２７年度の実績で申しますと、８４５件のお問い合わせがあり、そのお問い合わせに基づいて現地の処置をさせていただいているところです。","id":"exchange-065"},{"speaker":"渡部委員","kind":"質問","question":"非常に有用だと思うのですが、このような取組みに関して、どのようにお考えでしょうか。費用対効果もあると思いますが、できれば取組んでいただければと思うのですが、いかがか尋ねました。","respondent":"多並道路課長","answer":"区民との協働での点検のあり方かと思いますけれども、私の把握している部分で、千葉市のほうでもたしかそのような形があったかと思います。いろいろやられている事例を見ながら、区としてもよりよい点検のあり方、また協働のあり方を研究してまいりたいと思っているところです。","id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"そして、指定されていない地域をどうお考えになっているのかということをお聞きします。まちづくりという観点から、どういう動きが区民の皆様方の中で起きているのかを示すよう求めました。","respondent":"鈴木建築課長、東野まちづくり立体化担当課長","answer":"私から、まず応急危険度判定について、ご回答いたします。建物老朽度を決めて東京都が定めたエリアがございまして、その中でどういった事業を集中的にやっていくかというのは区が選択しているものです。特定整備路線沿道まちづくりということで、私からは主にまちづくりが進んでいる戸越公園周辺地区についてのご説明をします。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問","question":"それから、まちづくりについてですが、戸越公園はすごく進んでいるとわかっているのですが、ほかのところはどうですか。それと、今いろいろ話題になっていますけれども、お金がかかるという部分では、東京都の財源は大丈夫か尋ねました。","respondent":"鈴木建築課長、寺嶋木密整備推進課長、中村都市計画課長","answer":"新潟中越地震を含めて、ノウハウがありますので、今後もそういった努力をしていきたいです。似たようなところについては… 先ほどまちづくり立体化担当課長からご説明したのが戸越公園の周辺ということですが、除却支援、固定資産税等の減免等の支援を行って進めているところです。 予算については、限られたものですが、国や都の補助金を最大限に活用していきたいと考えております。","id":"exchange-068"},{"speaker":"あくつ委員","kind":"質問・要望","question":"雨が降るとプールのようにたまってしまうというところで改善を求める声が上がっていたのですけれども、これがどのように改善されたのか。そのあたりについてお伺いしたいと思います。","respondent":"溝口公園課長","answer":"それにつきましては、今年７月にしっかり直させていただいたところです。雨がたまっているという事実はありませんので、今回改修したことによって、雨がたまるという事象は解消されたと考えているものです。","id":"exchange-069"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これもずっと追いかけております交通安全対策ゾーン３０について、変化がちょっとありましたので、幾つかお伺いします。品川区全体のゾーン３０を幾つか見ましたが、なぜかそこだけついているというところで、そこについて情報があれば教えてほしいと求めました。","respondent":"桑波田交通安全担当課長","answer":"今まで整備されている都内のゾーン３０について新しく、今後ついているところにも設置して広報していくということで、追加でついているところです。","id":"exchange-070"},{"speaker":"あくつ委員","kind":"確認","question":"今回確認をしたら、平成２７年度に池田山、あのあたりも新しく指定されていました。これを地域全体を３０キロにしてしまうと、この点をどういうふうに解消されたのか、その辺の経緯について伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"ゾーン３０の周知につきましては、警察署と連携しながら、また区のホームページ等も使いながら周知を図っていきたいと考えております。全て２０キロであったところが、一部が取り消されて、一部が残っているという状況です。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"地域からたしかそのときに要望があったと思うのですが、警視庁のほうからも働きかけたと聞いておりますけれども。警視庁に地域からの要望、全体が４ｍ以下の非常に狭い生活道路でできている地域ですから、いかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"ゾーン３０の新たな設置の要望ですけれども、道路、または住宅等、周りの環境はやはり年月が経つと変わってくるものだと認識しております。新たな場所の要望ということであれば、そちらは品川警察の管内になると思いますので、その旨は伝えていきたいと考えております。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問","question":"１０月から成田行きの格安バスが出るということで、大崎エリアマネージメントの役割について、伺いたいと思うのです。前の導入のときの質問で申し上げましたが、例えばそういうノウハウを持った方が常駐されているのかどうか、その辺についてお伺いしたいと思います。","respondent":"稲田都市開発課長","answer":"大崎エリアマネージメントの社員でもあります世界貿易センタービルの協力のもと、その中にいる現在の事業者が事業協力を申し出てきたです。大崎エリアマネージメントの現在の事務局職員は、事務局長を入れて５名、パート職員等を入れて全部で７名です。","id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問したことがあるのですけれども、全国で２３ですか、ほとんどが株式会社がやっているのです。ここは区の見解を伺いたいと思うのですけれども、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"ただ、現在も東急バスや京成バス、先ほど言われましたけれども、一部、千葉交通等も入って運営しています。私どもの考えとしましては、一社独占でそのバスターミナルを使用するという区の考えは全くございません。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"例えばこの前開業した、２５番目にできたバスタ新宿、規模が全然違いますけれども、あそこは最初からいきなり１０社以上入っているわけですよね。そういうところで、あらぬ誤解を受けぬように、ぜひそこは門戸を広く開いていただきたいということを重ねて申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"渡辺委員","kind":"質問","question":"１６６ページのしながわ水族館のことを伺います。実数をとるのは難しいけれども、その辺の感覚的なものも説明を求めました。","respondent":"溝口公園課長","answer":"やはり英語のパンフレットが年間約５,０００枚ほどはける、または中国語のパンフレットにつきましても２,８００枚配布しているような状況です。そういった中でいきますと、やはり外国人が増えてきていると実感しているものです。","id":"exchange-076"},{"speaker":"渡辺委員","kind":"質問","question":"予算特別委員会で聞いたとき、たしか５０万人の大台を超えていなかったような気がしたのですが、前年比では大幅に増えられたのかなという気がします。どんな取組みで、どんな成果があったか、説明を求めました。","respondent":"溝口公園課長","answer":"その後、サンシャイン側、または品川区、連携した形でいろいろ経営努力をする中で、現在では４７万人がひとつの目標になっているものです。そういったものを行いながら、平成２７年度も集客を図ってきたというのが実績として上がっているものです。","id":"exchange-077"},{"speaker":"渡辺委員","kind":"質問","question":"ですから、この２５周年、すごく心から応援すべきことだと思いますし、肝心なのは今後のことです。その辺で、桟橋をどう活用していくのか、これが１つ。","respondent":"溝口公園課長","answer":"しながわ水族館だけでなく、しながわ区民公園に立地しているという特性を活かして、公園と一体となった形での集客力向上もあわせて検討していきたい。","id":"exchange-078"},{"speaker":"渡辺委員","kind":"質問","question":"そしてもう１点伺いたいのがアクセスです。この期間だったら、インパクトのある優待ができるような、そんな仕掛けがあってもいいのかなと思うので、この２点を伺いたいと思います。","respondent":"溝口公園課長","answer":"そういったものも含めまして、そういったところは引き続き、サンシャインとともに検討していきたいというふうに考えているものです。","id":"exchange-079"},{"speaker":"筒井委員","kind":"質問","question":"私からは、１６８ページの品川駅南地域周辺まちづくり事業と、天王洲地区まちづくり検討委託についてお伺いをいたします。３点の理由から、いっそのこと横断歩道に変えるべきかと思われますけれども、その点についていかがお考えか尋ねました。","respondent":"多並道路課長","answer":"例えば通学路に指定されていたりとか、子どもたちの安全を守る上でも、非常に重要な施設の１つでもあります。は通学路の有無というところも、全体的に勘案しまして判断して、対応をしています。","id":"exchange-080"},{"speaker":"筒井委員","kind":"質問・要望","question":"様々な、そうした手続き的な条件とか、交通上の条件がありますけれども、ぜひとも変えるべきところは変えていっていただきたいと考えております。変えている場所があるとお聞きしたのですけれども、今後、具体的にどこを行っていくのかということをお聞きしたいと思います。","respondent":"多並道路課長","answer":"逆に、あることで安全性の課題があるという観点で、ご要望がありました。まず横断歩道を新たにそこの下に設置して、今現在、調整しながら進めているところです。","id":"exchange-081"},{"speaker":"筒井委員","kind":"質問","question":"２年前の２０１４年６月につくられまして、かなり魅力的なので、品川駅南地域としては脅威ではないかなと考えております。柔軟に、今後の品川駅南地域に来ていただく取組みをぜひやっていただくべきと考えておりますけれども、その点いかがお考えか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"今、委員からご照会がありました「グローバルゲートウェイ品川」、こちらにつきましては、東日本旅客鉄道株式会社が昨年８月に発表した基本概要です。","id":"exchange-082"},{"speaker":"筒井委員","kind":"質問・要望","question":"こちらは、ぜひともこの品川駅を中心とした南北の広域活性化拠点として捉えて、しっかりとまちづくりを進めていっていただきたいと考えております。時間がなかったので質問できませんでしたけれども、行政としても、しっかりと推進のほうをお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"改めて、強硬なやり方はやめるよう、東京都に求めてほしいと求めましたが、いかがでしょうか。なぜ繰り返されるのか、原因を伺います。","respondent":"中村都市計画課長","answer":"現在、東京都では、この道路整備を進めるに当たりまして、今、土地をお譲りいただく、そういったお願いをしているというふうに聞いております。丁寧な対応、東京都のほうも当然、引き続き丁寧な対応を継続していくです。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"なぜ、これは続いているのでしょうか。伺います。","respondent":"中村都市計画課長","answer":"極力丁寧な対応に心がけているということで、今、区のほうでは相談を承っておりません。東京都のほうには、そういうお話もいただいているということはお伝えをして、東京都のほうはしっかり対応しますです。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"そして、この強硬な姿勢が繰り返されている原因を伺いましたので、ぜひ、ご答弁いただきたい。そして、区民が都の対応に不安に思っているということを、都が認識しているかということもお聞きしましたので、改めて伺います。","respondent":"中村都市計画課長","answer":"そういった認識を持たれる方もいるのだなという、丁寧な対応は今までもしてきたし、これからも継続をしてまいりますです。頑張るというよりも、相談をしていただければというふうに考えているというか、東京都のほうでそうしていただきたいというふうに申しておりました。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問・要望","question":"不安を与えないよう、丁寧な対応を都に求めているのは、特定整備路線にかかる人全てを対象に求めているのか、伺います。伺います。","respondent":"中村都市計画課長","answer":"区が東京都にお願いすることは、一部の方だけではなく、その権利者全ての方に丁寧な対応をしていただきたいというふうに考えております。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"都にもしっかりそのことを伝えていただいて、都が、そういう全ての人を対象にしてやっていくように求めてほしいと求めました。態度が急変したということも聞いておりますので、その改めて変わった理由、都から聞いていれば伺います。","respondent":"中村都市計画課長","answer":"特に聞いてございません。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"当時は無風状態でしたが、それでもこの火災が発生したのは、２０ｍ道路がなかったからですか。そして、このパンフレットは何枚配られて、幾らかかったのか、期間はいつからいつまでで、何世帯に配布したのか伺います。","respondent":"中村都市計画課長","answer":"品川区でもその３本の路線について、延焼遮断帯の形成を、東京都と連携して行っているところです。期間等の詳しいことは聞いておりません。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"このパンフレットの写真を見ると、１４階建てぐらいでしょうか、マンションよりもさらに２倍、３倍の高さまで炎が立ち上がっています。道路ができても完全に延焼をとめることはできないと思いますが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"東京都が進める木密１０年プロジェクトの中では、街区単位での建物の不燃化、こういったものと合わせて効果が出るとしております。そして、複数の手段を重ね合わせることによって効果が出るというふうに考えておりますので、今そういった複数の手段で対策を行っているです。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"区民を路頭に迷わせるこの計画は撤回すべきです。改めて伺います。","respondent":"中村都市計画課長","answer":"適切・最善の対応をとっていただくように東京都にお願いをしておりますし、そういった個々の生活の事情に応じて、適切な方法を一緒に考えていくと。防災性の向上に引き続き努めていくために、東京都と連携して、特定整備路線を進めていきたいと考えております。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問","question":"品川の特定整備路線についても、地域の方からの反対など、町を壊すこの計画は、見直していくべきだと思います。話があったかお聞きしたかったですけれども、こういった情報もつかんでいただいて、見直していくように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"本多委員","kind":"質問","question":"成果報告書の１６１ページ、細街路拡幅整備事業、２つ目が１６７ページの都市開発費について、質問します。最初に細街路拡幅整備事業なのですが、４２条２項道路の４ｍ拡幅が、品川区全域でどのくらい進んでいるのか、現時点の状況を示すよう求めました。","respondent":"鈴木建築課長","answer":"細街路の事業は、昭和６３年から開始しています。これまで、累計延長９４.７kmでございまして、対象とする全延長に対して約３４.６％の進捗率です。","id":"exchange-093"},{"speaker":"本多委員","kind":"質問・要望","question":"４ｍ、これまた最近、すごく区内全域から声が届いているのです。その辺の状況をつかんでいるのか、また対応等、どうなっているか説明を求めました。","respondent":"鈴木建築課長","answer":"後退した後に、例えば昨年度の事例でいきますと、この道路突出の事例としては１１件ございました。６年、１０年後にブロック塀をつくってしまったというところは、違反の是正指導等を行っているような状況です。","id":"exchange-094"},{"speaker":"本多委員","kind":"質問・要望","question":"確認次第、そういった指導を進めてほしいと求めました。そういった、最近のそういう動向というのですかね。","respondent":"鈴木建築課長","answer":"事業を開始した当時、私も１担当としてこの事業に携わりましたけれども、やはり路線として、当時は、後退したお宅が路線、あるかないか。しっかり聞いていただいて、建替えではない、空間がある今の状態で下がっていただいているというような事例も多い状況です。","id":"exchange-095"},{"speaker":"本多委員","kind":"質問","question":"こういう場合はどうかなというのを１つお聞きしますが、４ｍをもう確保している道路も含みますが、空地というか歩道ができました。そういったところを促す、指導はできないと思うのですが、促すということはできないのか尋ねました。","respondent":"鈴木建築課長","answer":"隣の敷地がまた戸建てで、２項道路の後退だけですと、なかなか歩道上の連続した空地というのはできていかない状況です。ただ、区としては、建替えだけではなく、いろいろな個別個別のケースに合わせて対応はしていきたいというふうに考えてあります。","id":"exchange-096"},{"speaker":"本多委員","kind":"質問","question":"次の質問に行きます。１６７ページの都市開発費、五反田地区コーディネート業務委託、この内容について示すよう求めました。","respondent":"稲田都市開発課長","answer":"徐々にまちづくりの活動を行っており、区として、このまちづくり協議会と連携して活動を進めております。目黒川桜植樹に向けた検討、それから目黒川の周辺のコインパーキング提携に向けた整備計画の検討等を行っております。","id":"exchange-097"},{"speaker":"本多委員","kind":"質問・要望","question":"当然、その鉄道事業者、所有者で建てるのは自由な権利があるわけですから、行政としても所有者の建築主どおりに了解すると思うのですが。西口・東口一体的に整備をという要望、意見もありましたので、その辺の区の見解を説明するよう求めました。","respondent":"稲田都市開発課長","answer":"そして付近のまちづくりと合わせました開発等の検討をしていこうということで、検討してきたところでございました。周辺とのまちづくりと合わせた検討、それから西口との連絡等々についても一緒に検討しようというところで話をしてきたところだったのですけれども。","id":"exchange-098"},{"speaker":"本多委員","kind":"質問・要望","question":"計画はわかりました。地域のことが後退しないように、ぜひ今後とも進めてほしいと求めましたが、その点についてお願いいたします。","respondent":"稲田都市開発課長","answer":"現在、東口のほうでは、再開発に向けた勉強会等々の地区もあります。そういう中におきましては、駅を挟みながら、まちづくりに向けてやっていくという考えです。","id":"exchange-099"},{"speaker":"本多委員","kind":"質問・要望","question":"最後に１つ要望して終わります。五反田駅の、目黒駅寄りに出入口を整備をしてほしいと求めましたので、申し入れをお願いしたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"塚本委員","kind":"質問","question":"それから、１６８ページの不燃化１０年プロジェクト、ちょっと前後しますが１６４ページの水辺利活用についてお伺いしたいと思います。この駐輪場について、この改修について、どのような改修となっていくのかをお伺いしたいと思います。","respondent":"桑波田交通安全担当課長","answer":"幅を広げるだとか、ラックをとってそのまま置けるような平置きの状況にするとか、そういうふうに整備していきたいと思います。その後は上部のほうも合わせてそういったものに対応できるようにやっていく計画を立てておりますので、順次整備を進めていきたいと考えております。","id":"exchange-101"},{"speaker":"塚本委員","kind":"質問","question":"１台１台多目にとっていくということは、心配になるのですけれども、その辺というのはどういうふうになっていくのか。うまく現状の駐輪台数を確保できるような形で考えていただけるのかをお伺いします。","respondent":"桑波田交通安全担当課長","answer":"場所を広げることによって、駐輪台数は若干減るものと認識しております。まだ使っていないスペース等もありますので、そういった所も有効に活用しながら、なるだけ駐輪の数を減らさないようにしていきたいと思います。","id":"exchange-102"},{"speaker":"塚本委員","kind":"質問","question":"この自転車レーンが整備されていく中で、どういうふうに整理していくというか、どういうあり方というのが望ましいというのですかね。そろそろ新たにしっかり普及していく、啓発していくという必要があるかなというふうに感じておりますが、いかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"もう１回、都内の自転車横断帯は、消していくように進めているところです。昨年、この辺はまたいろいろ警察署とも連携をとりながら、もしくは違反をさせないような広報について努めていきたいと考えているところです。","id":"exchange-103"},{"speaker":"塚本委員","kind":"質問・要望","question":"歩車分離のときに、歩行者の信号で渡るとき、これは本来は歩いて渡るものなのですか。一応、原則論としてはどうなのかを確認させてほしいと求めました。","respondent":"桑波田交通安全担当課長","answer":"失礼しました。歩車分離の場合は、こちらのほうは、押して渡っていただくようにお願いいたします。","id":"exchange-104"},{"speaker":"塚本委員","kind":"質問・要望","question":"ご対応のほうよろしくお願いしたいとともに、いろいろご検討ほしいと求めましたので、お願いをいたします。不燃化１０年プロジェクトの中の除却費用、予算に比べて４７％ということで、ご説明ほしいと求めました。","respondent":"寺嶋木密整備推進課長","answer":"執行率は４７％となっておりまして、当初予算に比べまして約半分ということなので、大変厳しい状況だという認識は持ってあります。本格実施は平成２６年なのですけれども、前倒しおよび先行実施というので、平成２５年度には２６件の除却をいたしました。","id":"exchange-105"},{"speaker":"塚本委員","kind":"質問・要望","question":"年々、実績としては拡張しているというところをお聞きしまして、非常にいいことだなというふうに評価させてほしいと求めました。幾つか新しい事業というのですか、この平成２７年度、ご紹介ほしいと求めました。","respondent":"寺嶋木密整備推進課長","answer":"建替えの際の住み替え支援助成、まだ４ヶ月なのですけれども、住み替え支援のほうは３０件を超える申請を受け付けて状況です。今後も引き続き、取組みを強化してまいりたいと考えております。","id":"exchange-106"},{"speaker":"塚本委員","kind":"意見","question":"Ｔ.Ｙ.ＨＡＲＢＯＲだとか、目黒川のことですとか、こういったことを１つ１つ取り上げて、写真に写して、大変に評価をされておりました。今後のこの品川区の水辺の展望につきまして、ぜひお一言、最後にほしいと求めました。","respondent":"和田河川下水道課長","answer":"地元事業者を中心に、区内の舟運が活性化されていくことを目指して実験を行い、今後も推進してまいります。","id":"exchange-107"},{"speaker":"石田（し）委員","kind":"質問","question":"１６６ページのしながわ水族館、時間があれば１６０ページの道路の維持管理について、それぞれお願いします。質問に入る前に、区はどのような見解を持っているのかということを、まずご答弁ほしいと求めました。","respondent":"稲田都市開発課長","answer":"大崎駅西口バスターミナルから成田国際空港まで、１０月３１日開通するです。大崎の観光、また品川区内部への観光というところで、非常に期待しています。","id":"exchange-108"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"使い捨てカイロを再利用してヘドロを分解しにおいを減らす鉄炭団子というのですかね、これを使った地域連携を始めたという報道がありまして。これはどこが運営をされているのか教えていただきたいのと、水族館に向かって、そういったものを考えていったらいいのかなと。","respondent":"多並道路課長、和田河川下水道課長、溝口公園課長","answer":"地元のまちづくり大井というＮＰＯの団体がアンケートを実施しまして、アトレの社員の皆様にアンケートを実施した結果、アンケートが集まりました。… 東京海洋大学のお話の実験については、これは目黒川ではなくて、港区内の運河でやっているというふうに認識しております。… １つはしながわ区民公園のバス停を降りてから、バス停の前のところ、そういったものをしながら水族館へ行くというわくわく感を出しています。","id":"exchange-109"},{"speaker":"石田（し）委員","kind":"意見","question":"どうせやるのだったら、来てくれた人はきれいだねというふうに言ってくれるかもしれないですけれども、ではそれを知ってくれる人がどこまでいるのか。そういうこともやっていかなければいけないのではないかなと思うのですが、その点どのように考えますか、お知らせくださいとの意見を述べました。","respondent":"溝口公園課長","answer":"委員お話しのように、様々な形でしながわ水族館を楽しんでいただくというのが大事なことだと考えています。そういったところのメニュー開発というのは、品川区といたしましても、そういったものを一緒になって考えていきたいというふうに考えているものです。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問","question":"私は成果報告書の１６０ページ、道路維持費に関連をして、それから１６６ページ、しながわ水族館に関連をして質問します。何らかの形で、所管する警察とも協議しながら対応すべきだと思うのですが、いかがか尋ねました。","respondent":"多並道路課長","answer":"ちょうど今、補助１６３号線の整備を進めながら工事を、まずは大井町線の立体のほうの工事を進めているところです。警視庁とも協議しながら進めていくところでもありますので、その中で、工夫して検討してまいりたいと思っているところです。","id":"exchange-111"},{"speaker":"伊藤委員","kind":"質問","question":"それがあそこにできるかどうかは別問題としても、リサイクルショップリボンの側だけと同時に、大崎の入口も検討してみてはどうですか。もう一言答弁をお願いいたします。","respondent":"多並道路課長","answer":"委員のご指摘のところも含め、すぐ現場を見させていただいて、できるかできないかというところは、すぐに検討させていただきたいと思います。今の点も踏まえて、すぐできることは検討というところで、そういう形で進めていきたいと思っているところであります。","id":"exchange-112"},{"speaker":"伊藤委員","kind":"質問・要望","question":"住んでいると言ったらいいのですかね、自転車を置いて、そこにいる。品川区と協議をしていただいてやってもらった記憶があるので、ぜひそういうのをもう１回やっていただきたいと思うのですが、いかがか尋ねました。","respondent":"多並道路課長","answer":"委員の今のご指摘のところ、国道敷も含めながらのところですけれども、国と連携を図りながら、しっかり対応していきたいと思っているところです。","id":"exchange-113"},{"speaker":"伊藤委員","kind":"質問","question":"だからドラマの効果に乗って、そして集客力をアップすることは、決して間違ってはいないので、そのことの見解は、まずいかがでしょうか。お答えをいただくよう求めました。","respondent":"溝口公園課長","answer":"１つは、水族館の中では、既に『水族館ガールコーナー』というのを設けております。そういったものも使いながら、集客力、集客を図っていきたいというふうに考えているものです。","id":"exchange-114"},{"speaker":"伊藤委員","kind":"意見","question":"１年間を通して多くの方々に、そういう可能性が高くなっていくことは間違いないので、そのことの考えをお聞かせください。お願いいたしますとの意見を述べました。","respondent":"溝口公園課長","answer":"これまでも、イルカとペンギンの植栽を入れてやってきたところです。さらに改善、どういう形ができるのか、検討していきたいというふうに考えているものです。","id":"exchange-115"},{"speaker":"伊藤委員","kind":"質問・要望","question":"出演された方々のサインを出していくなり、そういうようなことで、新しい形での展示を考えてはいかがでしょうかということが１点と。それを多くの方々にＰＲをしていただいて、水族館に来ていただくきっかけをつくっていくというふうに検討すべきと思うのですが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"今回、まさに２５周年記念ということで、１日館長として、主演の松岡茉優さんがご来館されることになっております。サンシャインとも連携して、そういったところの観点で、さらにＰＲには努めていきたいというふうに考えているものです。","id":"exchange-116"},{"speaker":"伊藤委員","kind":"提案","question":"款が違いますから提案だけしますけれども、１つのデータベースに載せていけば、それは連携して対応するようお願いいたします。やはり、もっと品川区が主体的に売り込んでいくべきだと思うのですが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"実績といたしましても、やはり天王洲と並んで、品川区内の中でロケーションとして使われる件数が非常に多いというのは、認識しています。これまで２５年間培ってきたものも、観光部署と連携しながら、そういったものを検討していきたいというふうに考えているものです。","id":"exchange-117"},{"speaker":"伊藤委員","kind":"質問","question":"非常に駅から近いところですから、最後にこれからのしながわ水族館の方向性だけ、ちょっとお答えください。お願いいたします。","respondent":"溝口公園課長","answer":"来たいと言ってもらえる、そういった水族館を目指して、様々な取組みをしていきたいというふうに考えております。入館者数の推移、しながわ水族館の今後をどうあるべきかというものを、しっかり詰めて考えながら運営していきたいというふうに考えているものです。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"意見","question":"先に、大崎駅西口交通広場整備工事の方をお尋ねします。それから今後、先ほど成田の話が出ましたが、増えるであろう運行本数や路線について、見通しがあればお答えくださいとの意見を述べました。","respondent":"稲田都市開発課長","answer":"それを合わせますと１６５便が１０月３１日からは出発するという形になります。そのほかの予定ですが、現在、国のほうへ路線認可を申請しているという情報を聞いております。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"たびたび、議会でも早期完了を求めていますが、いろいろなことがありまして、時間がかかるというふうに思われます。大井町と大崎駅のこのターミナルのところを結ぶ、小さなコミュニティバスを運行したらどうかと考えますが、この見解を説明するよう求めました。","respondent":"中村都市計画課長","answer":"新たな路線としては非常に難しいというところで、その他いろいろ候補はあるかもしれませんけれども、そういったようなお話も聞いております。したがいまして、この辺は、バス事業者と慎重に検討してまいりたいというふうに考えております。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、羽田のお話もありましたけれども、運転本数は概ね１時間に１本程度というふうに伺っています。改めてご見解を伺います。","respondent":"中村都市計画課長","answer":"今ご提案のあった路線につきましても、これも検討する、しなければいけないというところがあるかもしれませんけれども。慎重な検討が必要だというところで、引き続きそういった考えで、こういったご要望は伝えてまいりたいというふうに考えております。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"慎重な検討ということですけれども、ぜひ今お話ししたような状況の中で、検討をお願いしたいというふうに思います。安全性と円滑な運行のために、右折の信号をつけてほしいというご要望があるのですが、その件についていかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"きゅりあん前の信号の関係ですけれども、信号機については、各交通量、こういったものに勘案して、サイクルもしくは表示等を設置しています。今の場所につきましては、ちょっと現場のほうを見まして、対応させていただきたいと考えております。","id":"exchange-122"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして京急に求め続けていますけれども、都や京急から情報はあるのかどうか、伺いたいと思います。この要望の中で、この改善が現在どうなっているのか、伺いたいと思います。","respondent":"中村都市計画課長、溝口公園課長","answer":"人的な対応というところもありまして、人的対応というところもあるということで、今しているところでもあります。鉄道事業者も、前向きにこの点は考えたいですので、引き続きお願いをしてまいりたいと思います。観光または主要ターミナル、そういったところを中心に、今後重点的に整備をかけたいというふうに考えているところです。","id":"exchange-123"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"京急はどういう状況なのかを伺いたいと思うのですが。区からの、こうしたホームドアについての働きかけもどのようになっているのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"京急のほうにも、当然のことながら、このホームドアの設置についてはお願いをしています。耐震対策などは遅れているかもしれませんけれども、そういったところから、まず基本的なところから取組んでいきたいということでございました。","id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"利用が広がらない原因は、区はどのように考えているのでしょうか。昨年が１件ということで、今年は広げるための対策は打たれたのかどうか、伺いたいと思います。","respondent":"今井住宅課長","answer":"高齢者地域支援課で一定の事業がされているということ、もう１つ住宅課で行っております、住改善の工事助成ですね。防災あっせん用品の隣に、先ほどの高齢者と障害者だけではなく、こちらの一般の家具転倒防止の助成についても周知を強めているところです。","id":"exchange-125"},{"speaker":"石田（ち）委員","kind":"質問","question":"こうした区民の関心の高まりというのを、やはり捉えていくべきではないかなと思うのですね。高齢者の制度と同じように中身を、購入と設置を同時に助成できる中身に変えていくべきなのではないかと思うのですが、いかがか尋ねました。","respondent":"今井住宅課長","answer":"こちらは品川区内のいわゆる建設組合の４団体、どういうふうな設置器具がいいかとか、そういうアドバイスも含めて対応しています。そちらのほうの事業との連携を含めながら、私どもは改めて確認していく必要があると思いますが、現時点での拡大等の方向性はございません。","id":"exchange-126"},{"speaker":"たけうち委員","kind":"確認","question":"そこも撤去するという話になったような気がしたのだけれども、これについてのスケジュール的なものとか、検討結果を一応確認させてください。それから、まだ募集を続けているということなので、どんどん増えてきたときに、４定か何かで補正を組むのか、何かその辺も含めて説明を求めました。","respondent":"桑波田交通安全担当課長、多並道路課長、古巻防災課長","answer":"いろいろな整備だとか制度の改正等も検討していますが、引き続き、検討させていただきたいというふうに考えているところです。５０商店街にヒアリングした中で、２つの商店街を選ばせていただきましたけれども、リストアップというのはないという状況です。区の計画としては来年度以… 感震ブレーカーの設置助成に関するお問い合わせですけれども、現在、先ほどもお答えしましたとおり、１３６件の申込みを受けております。","id":"exchange-127"},{"speaker":"たけうち委員","kind":"確認","question":"確認させていただきました。地元は手を挙げないかもしれないけれども、区としてはそう思ったのかなと思ったので聞いたのだけれども、そうではないのか尋ねました。","respondent":"多並道路課長、古巻防災課長","answer":"東京都もいろいろ促進ということで検討しているところですので、その状況を見てから検討していきたいというのが、今の現状のところだと考えております。 感震ブレーカーの設置助成、今後さらに普及促進が進むように、また啓発につきましても十分に周知を図っていきたいというふうに考えております。","id":"exchange-128"},{"speaker":"たけうち委員","kind":"質問・要望","question":"その辺は考えていく、もちろん負担の問題もあると思うのですけれども、ぜひ考えていただきたいなと要望します。その辺の整合性というのか尋ねました。","respondent":"古巻防災課長","answer":"木密地域を中心にしました設置助成につきましては、ある意味、ちょっと手ごろにといいましょうか。これは助成ということではなくて、価格的にもお求めやすいので、あっせんにしたものです。","id":"exchange-129"},{"speaker":"松澤委員","kind":"質問・要望","question":"５項建築費１目建築行政費、建築確認事務について、時間がありましたらもう１点お伺いしたいと思います。その支障になるということで、工事が始まっていますけれども、この工事計画の全容をお知らせほしいと求めました。","respondent":"多並道路課長","answer":"一番密集の危険度が高い北西側のほうの地域からの逃げ込める１つの水路敷を、区としては今現在、整備を進めようと考えているところです。説明板とともに、そういう整備をしていきたいということで、考えているものです。","id":"exchange-130"},{"speaker":"松澤委員","kind":"質問・要望","question":"そんな意味では、そういうふうにしてくれるということですけれども、橋の欄干ですから、それがどういう形状で残るのか。その辺、どういうふうに大事にしてくれるのかを、もうちょっと説明ほしいと求めました。","respondent":"多並道路課長","answer":"ちょうど上ったところに、両方とも橋がそのまま現存、残るような形に移設をしたいと考えています。そういうお話もありますので、そこについてはしっかり表記をして、わかりやすいような整備をしていきたいと思ってあります。","id":"exchange-131"},{"speaker":"松澤委員","kind":"質問・要望","question":"品川区の確認が少ないという話はよく出ますけれども、やはり確認件数が少ないと、いろいろな方が質問しているのですけれども。建築確認事務、これの内容について、ちょっとお知らせをほしいと求めました。","respondent":"鈴木建築課長","answer":"考え方につきましては、日々、窓口で設計事務所から受けているものです。１日１００件程度ございまして、職員が日々しっかり考え、答えているというような状況です。","id":"exchange-132"},{"speaker":"松澤委員","kind":"質問","question":"しっかりやっていて、大丈夫ですよというお話を伺いました。もう１つ、１つぐらい、こんなにすごいのがありましたよというのがありましたらお聞きしたいと思います。","respondent":"鈴木建築課長","answer":"そうすると、既存が建蔽率、容積率がオーバーしてしまうですとか、そういった、やはり既存の建物に対しての建築行為の指導が非常に多いです。本当につくれないよというところで、例えば行っているとか、そういったところです。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"区民が真っ暗な中、避難するわけですが、避難路に今現在、誘導灯がないわけです、これで安全に区民は避難できるとお思いでしょうか。人口密度が高い地域ごとに、情報を流し、音声がよく聞こえる行政防災無線が必要だと思いますが、ご見解を説明するよう求めました。","respondent":"古巻防災課長","answer":"聞こえにくいというようなお声があることも十分認識しておりますので、そういったところを含めまして、設置・更新の計画を立てているところです。その中で、聞こえやすい、もしくは使いやすい防災行政無線となるよう、計画を考えてまいりたいというふうに考えております。","id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"この間、本当に大規模停電があって、この真っ暗な中で、人がどうやって動くのですか。だって、一斉に情報を流されたって、どうするのか尋ねました。","respondent":"古巻防災課長","answer":"そういった街灯の設置は、進めているところですので、より安全な避難ができるような形をとってまいりたいというふうに思います。広範囲に情報を広く伝えるということが主眼で設置を進めておりますけれども、さらに区民の安全・安心を守っていきたいというふうに考えております。","id":"exchange-135"},{"speaker":"須貝委員","kind":"質問・要望","question":"なぜ避難者は、生活基盤の再現ができないとお考えですか。もし、考えをお持ちだったら言っていただくよう求めました。","respondent":"古巻防災課長","answer":"避難者に関しましては、被害の状況に応じまして、様々な状況があるかというふうに思います。ですので、東日本大震災におきましては、復興の遅れから避難が長期化している面があるかというふうに思っております。","id":"exchange-136"},{"speaker":"須貝委員","kind":"質問","question":"個人の住宅や家財に対しては、やはり、国や自治体からの、私は、給付は限定的だと、もうそれは正直に認めるべきではないですか。だけれども、こういう知識はやはりきちんと教えるというのは、私は自治体の使命だと思うのですが、いかがか尋ねました。","respondent":"古巻防災課長","answer":"これまでも東京都の被害想定に基づきまして、しっかりと防災対策を進めてまいりました。今後も、それに基づきまして、きちんと防災対策を進めまして、また普及啓発につきましても十分に行っていきたい、そのように考えております。","id":"exchange-137"},{"speaker":"大倉委員","kind":"質問・要望","question":"１６０ページ、１６１ページ、１６７ページで伺いたいと思います。その観点からもお話を伺えればと思います。","respondent":"安井土木管理課長、多並道路課長","answer":"除却できたものに合わせて、その辺を重点的に回るというようなことで、除却のほうに努めているところです。９月３０日に法が改正になりまして、そういった対応をとれるようになりましたので… もともと８,０００基ほどありました水銀灯を、平成２７年から５年間の計画で、順次建て替える計画です。","id":"exchange-138"},{"speaker":"大倉委員","kind":"質問・要望","question":"こうした視点からも力強くやってほしいと求めましたが、いかがでしょうか。この辺どうしてか、教えてほしいと求めました。","respondent":"安井土木管理課長、多並道路課長","answer":"私も剥がしているときに職務質問に遭ったことがあるのですが、警察のほうが現認できれば、それはやっていただけるものだというふうに思ってあります。民事のほうは、やはり相手方が特定できないので… 先ほど、古いものと、ちょっと説明が足りなくて申し訳ございませんでした。ここの電気料金ですけれども、その中で４７０万円ほど削減ということで、その効果としてはそういう結果となると思っているところです。","id":"exchange-139"},{"speaker":"大倉委員","kind":"質問・要望","question":"そうしたところから特定に至って、こうしたことが早くなくなるように取組みを強化してほしいと求めましたので、よろしくお願いいたします。自転車走行レーンは時間がなくなってしまったので、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"南委員","kind":"質問","question":"１６６ページの公園新設改良費について伺います。こういう法律に明記されている１人当たりの面積にどう近づこうとするのか、そのあたりの考え方、それをちょっと伺っておきたいと思います。","respondent":"溝口公園課長","answer":"それに向かって進めて、公園を拡張していますが、なかなかそこの目標値に行かないというのが、今、現状です。安心に使えるような、公園の日常管理から整備、そういったものを行っていきたいというふうに考えているものです。","id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点をしっかり改めて確認をしていただいて、公園を整備する、そういうことに力を尽くしていただきたいというふうに思っています。その点についての考え方というのをどう思うのか、伺います。","respondent":"溝口公園課長","answer":"そういった中では、広く、小さい子どもから大きな子ども、そういったものが公園を利用して遊べるような整備を進めてきているものです。今後も引き続き、同様の考えで、公園整備をしっかり進めていきたいというふうに考えているものです。","id":"exchange-142"},{"speaker":"南委員","kind":"質問・要望","question":"０.５６m2程度のこんな状況が、ずっと横ばい状況ですから、ちょっとひどすぎるなというふうに思います。ちょっとその点、伺います。","respondent":"溝口公園課長","answer":"スケボーにつきましては、八潮という話がございましたが、これまでも検討していく中で、やはり音が出るというのが一番大きな問題です。は近隣にマンションがある、そういった所ですと、なかなかスケボーパークの整備というのは難しいというふうに考えているものです。","id":"exchange-143"},{"speaker":"南委員","kind":"確認","question":"もう囲いがあるだけで、どんどん吸ったたばこは上も下も全部素通しですから。メーカーの確認はきちんとしていただくのはもちろんですけれども、もし可能であれば、体験もしていただいたほうがいいのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"},{"speaker":"浅野委員","kind":"確認","question":"この２カ所しか、地中化できるところはないという認識でいいのかというところを、ちょっと確認をしておきたいと思います。もうちょっとですかね、その辺のさじ加減というのでしょうか、教えてほしいと求めました。","respondent":"多並道路課長","answer":"商店街電線類地中化の件ですが、まず、２商店街以外の商店街という件ですが、先ほども、説明が悪くて申し訳ございません。これから推進策というのを検討しているという時期でもあるので、または、そこについては今後ということで検討していくものだと考えているものです。","id":"exchange-145"},{"speaker":"浅野委員","kind":"質問・要望","question":"ガス会社からの申請等を受けながら、許可を出すのでしょうかね、そういうようなことをやられていると思います。２段階になるかもしれないですけれども、こういうことをしっかりと徹底をしてほしいと求めましたが、いかがか尋ねました。","respondent":"安井土木管理課長","answer":"面していらっしゃる方の車の出入りであるとか、交通の問題もありますので、必ずポスティングは全戸にするです。そのチラシに合わせて、工事内容等も説明するような形で、丁寧な対応を心がけていくように指導してまいりたいと思います。","id":"exchange-146"},{"speaker":"浅野委員","kind":"質問","question":"それと、あと地域からもちょっと質問といいましょうか、指摘があるのが、水で遊べるところなのですね。そのままなのかどうかとかいうことも踏まえまして、この基本設計を進めていっていただいていると思うのですが、この件についてはいかがか尋ねました。","respondent":"溝口公園課長","answer":"健康遊具につきましては、そういった、今現在進めているところですので、今後どうしていくのかというのは、今現在検討しています。そういったご利用者の声、そういったものも十分に反映しながら、今後どう整備していくのか検討していきたいというふうに考えているものです。","id":"exchange-147"},{"speaker":"浅野委員","kind":"質問・要望","question":"協力の促進などとなっているわけですけれども、この心のバリアフリーの推進ということについて、ちょっと具体的に教えてほしいと求めました。目に見えない取組みになっているかと思いますが、どのような形で啓発をしていくのか、具体的に教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"今、お互い声をかけ合うというところで、このハード整備と合わせて進めていければいいなというふうに考えてあります。ハードの整備を進めるのはもちろんのこと、こういったものについても、心がけていただくように働きかけていきたいというふうに考えております。","id":"exchange-148"},{"speaker":"浅野委員","kind":"質問・要望","question":"研修会みたいな形でやられるかどうかは、やはり１人になるとなかなかできない部分であるとか、この点よろしくお願いいたします。これからも、ちょっとバリアフリーとは違うかもしれませんけれども、進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"鈴木（真）委員","kind":"確認","question":"まず確認なのですが、あそこの工事完了というのは確か平成３１年だと思ったのですが、その点の確認を１個させてください。品川区として取得するべきではないかなと思うのですが、東京都の所有ですから、その辺について区としてどうお考えになっていくか。","respondent":"多並道路課長、柏原企画調整課長","answer":"大井町駅の駅前中央通りの件ですが、大井町駅周辺地区のバリアフリー計画の中で、当該道路につきましては、平成３１年度にバリアフリーの工事を行うという計画になっているところです。そうなりますと、都庁全体の中で使用をどうするかというのをまず確認を、流れとしてはするだろうというところまで確認できております。","id":"exchange-150"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"大井町のほうの確認は、私のほうでちょっと確認したかったのは、ここを平成３１年度に工事ということは。そうするともっと活用性が高いのではないかと思いますが、その辺でもう１回お答えをお願いしたいと思います。","respondent":"多並道路課長、柏原企画調整課長","answer":"この計画自体が全体的に平成３１年度の目標年次ということにしているところなので、そこの中の計画ということで、平成３１年と記載しています。オリンピックのこれからの動きなどというのを総合的に考えまして… 東京都の動きというのがちょっとまだ見えない部分はありますけれども、仮に取得できれば有効活用はかなりできる土地であろうと思いますので、そういったところは情報収集をしながら検討を進めたいと思います。","id":"exchange-151"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"大井のほうは要望なのですが、オリンピック前に事業を終わらせておいてもらいたいなというのが希望で、これも要望にさせてもらいます。目黒区とのその辺の連携関係も、両方とも連携というのはどういうふうにとっているのか、説明を求めました。","respondent":"和田河川下水道課長","answer":"それから水質の関係の連携ですけれども、平成１８年から大田区と連携しまして、いろいろな水質の実験などをやっております。このように、目黒区とは、目黒川の水質に関しては十分に連携をとっているところです。","id":"exchange-152"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"大田区とのほうの連携というのも、運河を使っていろいろなことを、ボートレースも今お話がございました。その辺もいろいろご検討していただいて、予算組みをしていただきたいなということも希望しておきますので、これは要望で終わらせてもらいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-153"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/678897?Template=document&Id=1428#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":119301,"voices":357}},{"id":"h28-20161017-4","meetingId":"h28-c-settlement","date":"2016年10月17日","dateIso":"2016-10-17","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時２０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を150件整理しています。","topics":[{"id":"topic-01","title":"◯こんの委員長 ただいまより、決算特別委員会を開会いたします。 それでは、平成２７年度品川区一般会計歳入歳出決算","agenda":"◯こんの委員長 ただいまより、決算特別委員会を開会いたします。 それでは、平成２７年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"同じく１７７ページ、１８０ページ、学校環境整備事業の中の校庭人工芝生化についてお伺いをいたします。決算書を見ますと、１０件、試掘調査費等と書いてありますけれども、これは具体的にどういった内容なのか説明を求めました。","respondent":"品川庶務課長","answer":"１７７ページの文化財保護費、調査ですが、こちらは埋蔵文化財の調査です。その場合、地中に埋蔵した文化財が埋まっていないかどうかの調査の件数です。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今現在、埋蔵文化財包蔵地は２５カ所だと思うのですけれども、今、私が質問しました、１０件全部とは言いませんけれども、何かお宝があったのかとか、もしそういった、今回あったのかどうかお知らせほしいと求めました。","respondent":"品川庶務課長","answer":"この調査の１０件ですけれども、全て調査の段階で終了しておりまして、特に大きなものは出てございません。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは、例えば、神社の近所の注文住宅の掘削工事のときに、そういったものが出たとか、そういったところの解釈でよろしいのかどうかと、これは当然、建築課との連携もあると思うのですけれども、その辺も教えていただければ、。","respondent":"品川庶務課長","answer":"大体この申請が月間で２００件から３００件来ております。建築課と連携というところについては、特段連携等はないのですが、必要に応じて建築課と連携をして進めているというような状況です。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"次に、同じく１７７ページ、子ども地域活動支援経費についてお伺いいたします。簡単でいいのですけれども、そのご説明と、今回、変更点があったようですけれども、その辺を踏まえて示すよう求めました。","respondent":"品川庶務課長","answer":"今年から４・５・６年生については、欲しい方についてはカードを配るというような対応をしています。それから、各町会にも少しこちらから予算を支給しまして、町会でも自由に選べるような形で対応をしています。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問","question":"いま一度、もう１回整理をしていただくということもなかなか難しい面があると思いますけれども、よろしくお願いしたいと思います。その辺のことについて説明を求めました。","respondent":"品川庶務課長","answer":"幾つか細かい点など申し上げますと、地域でこれまでもいろいろ説明してきたのですが、例えば。今、説明を行っているところですので、今後も周知には努力していきたいと考えています。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、１８０ページ、学校環境整備事業の中の校庭人工芝生化についてお伺いいたします。今年度、この人工芝生化の件数は２件ということなのですけれども、その２件の学校名を説明するよう求めました。","respondent":"品川庶務課長","answer":"今年度進めている学校については、台場小学校、それから伊藤小学校です。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これ、今、校庭人工芝生化は推進がいろいろされておられると思うのですけれども、当然、今をもって、例えば源氏前小学校とかも砂なのですけれども、砂ぼこりとか、そういった苦情がなければ、今の状態を、砂、サンドを保っていくのかどうか説明を求めました。","respondent":"品川庶務課長","answer":"委員からお話があったとおり、砂ぼこりがひどい学校、これについて導入をしています。現在、これを研究しまして、どういう方向でいくか考えていきたいと考えています。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"１７８ページ、品川図書館運営費、１７５ページのオリンピック・パラリンピック教育推進事業費についてお伺いをします。自転車置き場のラックの耐用年数はどれぐらいなのかお伺いしたいと思います。","respondent":"木村品川図書館長","answer":"昨年、塗装を行いまして、そういう形で運営をさせていただいてきております。少々お待ちください。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"もう既に２１年たっているということで、使い勝手のいいタイプの置き場を新設されることを要望したいと思うのですけれども、いかがでしょうか。新たに整備される予定があるのかということもお伺いをさせてほしいと求めました。","respondent":"木村品川図書館長","answer":"総合的に判断して、六行会とも協議をしながら、これから考えてまいりたいというふうに思っております。改築の計画につきましては、その中で考えてまいりたいというふうに思っております。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"続いて、オリ・パラ教育の推進事業についてお伺いいたします。今年度、平成２８年度も含めますと、全校になっているのかとも思うのですが、平成２７年度までの１６校の学校名を教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"昨年度の成果ですけれども、主な取組みとして、特にスポーツを重視した取組みをこの２年間でやってまいりました。いらっしゃいましたけれども、努力ということについて、子どもたちにこれからの励ましになるようなことがたくさん聞けたというふうに聞いております。","id":"exchange-010"},{"speaker":"新妻委員","kind":"提案","question":"既に平成２８年度になりますと、全ての学校でこれが推進校になっているかと思いますが、そのことも確認をさせてほしいと求めました。神輿もコラボがどうなのかという提案もされておられましたけれども、それを見ましたけれども、非常に感動いたしましたとの意見を述べました。","respondent":"熊谷指導課長","answer":"特に本年１月に策定されました実施方針では、「環境」という要素の中でも、「文化」というものが非常に重要な柱となっております。日本の伝統文化に親しませ、そしてそれを学び、発信できるような児童・生徒を育てていきたいというふうに考えております。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"その中でも基本的視点から、全ての子どもが大会にかかわるということ、そして日本人としての自覚と誇りというようなことも明記をされておりました。どうぞ推進をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点目は、１７５ページから１７７ページ、インクルーシブ教育についてお伺いをいたします。こう求めたところなんですが、ここから質問なのですが、十分な対応を考えていこうと考えていますとご答弁をいただきました。","respondent":"村尾教育総合支援センター長","answer":"さまざまな支援、またきめ細やかな対応ができるようにしていく、これについては共通しています。３点目、本年度、性自認にかかわる児童生徒に対するきめ細かな対応の実施についてというような通知がございました。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もし答えられたら、後でいいので、今後の取組みを高めていただきたいといった前回の質問に対してのご答弁をいただけたらと思います。このような報告がされていますけれども、教職員の方々は、教育現場の実態をどれだけ知識として持っていらっしゃるのか伺います。","respondent":"島袋人権啓発課長、村尾教育総合支援センター長","answer":"世田谷区の区議、上川あやさんをお招きいたしまして、性的マイノリティーと人権についてという研修を始めました。時間がたっておりますことから、新たな人権課題としての取組みについて、今後、一般職員、教職員… 学校内においては早急にサポートチームを設置し、その児童・生徒に対して適切な対応ができるよう、努めているところです。授業関係、その辺についても十分対応ができるよう、共通の理解を図っているところです。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この点を伺ったので、もう１回お答えいただきたいのですが、ＬＧＢＴ教育が少しずつですが広がっているという報道があります。早急な検討をしていただき、先に進めていただきたいのですが、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"このＬＧＢＴ（性的マイノリティー）についての研修は、現在、昨年度から実施しているところです。教員が正しい認識を持つことは、子どもたちに対してとても大切にはなります。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"小学校、義務教育学校の中には、固定学級と普通学級の児童・生徒との交流学習の充実を求めています。インクルーシブ教育として、当然の要求と思いますが、ここの充実を求めますが、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"現在、設置校の中では交流、いろいろな場面で進めているというふうに聞いております。それから、その中で、または図工の時間に一緒に入って学習をする等の活動は現在いろいろなところで進めているというふうに考えているところです。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なので、さまざまな機会を捉えて、教育現場は困難があると思いますけれども、教育環境への支援もしながら考えてほしい。学級の位置なのですが、学校の真ん中に置いて、全児童との交流が図れるような工夫をしていただきたいのですが、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"自立し、社会参加できるよう、各学校においても取組みは今後とも進めていこうというふうに考えておるところです。特別支援学級の配置につきましては、それぞれ各学校にありますので、また検討します。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"私からは、１８４ページの学校施設建設費、１７７ページの文化財保護事業、以上２つに関連してお伺いをいたします。３点目、これで東品川四丁目の学区域の人口増に対処できるものになるのか示すよう求めました。","respondent":"篠田学校計画担当課長","answer":"それから、時期ですけれども、現在のところ、平成３１年夏場ごろを予定しておるところです。１８クラスを想定しておりますので、今後、人口推計の中で想定される子どもたちの増に対しては十分対応できるものというふうに考えております。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"そうすると、東品川四丁目に限らず、今後も品川区各地域でマンションがどんどん建つことになると思いますけれども、今後もそういう状況に対応して、学校の増改築で対応していくという方針か尋ねました。","respondent":"篠田学校計画担当課長","answer":"今後の学校増改築等の展開につきましては、就学人口等の推移も踏まえまして、常に今後の見通しを立てながら考えているところです。もだめな場合には、新たな学校の改築といったものも含めて、どのような対応をしていくかということを総合的に判断して進めているところです。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"ただ、ディベロッパーのマンション開発とかの建築発表を受けたら、増改築の準備に品川区としては入っているのでしょうか。今、学校施設はこうした状況だとか、そうした相互の情報共有の連絡体制とかは作られているのか尋ねました。","respondent":"篠田学校計画担当課長","answer":"各ディベロッパーなどからは、教育委員会のほうに建てますというような話で直接入ってくるわけではございませんので、区のほうに対してさまざまな届出がありますと、区の内部で情報等を共有しながら学校の改築の判断につなげているという状況です。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"品川区としても、そうした再開発とか建築の予定を聞いてから、事後的に対応されるのは非常に大変だと思いますので、こうしたことにならないように、早め早めにディベロッパーとの連絡体制もとっていくべきかと思いますけれども、その点、どうお考えか尋ねました。","respondent":"篠田学校計画担当課長","answer":"なかなか教育委員会で直接ディベロッパーとやりとりをするというのは、なかなか難しい部分はあるのですけれども、引き続き、今度とも庁内各課との連携等も含めまして、後手に回らないような形での対応を進めてまいりたいと考えております。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"よろしくお願いします。文化財保護事業についてお聞きいたしますけれども、東京都が指定する品川区内の指定文化財数は、お幾つか尋ねました。","respondent":"品川庶務課長","answer":"現在、品川区内で指定されている文化財の件数ですが、約１８０件ほどあります。その中で東京都が文化財指定をしているものが、約２０程度あります。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"２３区中１位という状況でして、これはすごいということで、この指定文化財の数をもっと品川区としてＰＲしていってもいいかと考えております。品川区はせっかく１位なのですから、もっともっとＰＲをしていっていただきたいと考えておりますけれども、いかがお考えか尋ねました。","respondent":"品川庶務課長","answer":"ただ、これだけ多い数の文化財を所有しておりますので、ＰＲの方法については、これから検討してまいりたいと思います。こういった部分も今後検討して、オリンピック・パラリンピックに向けて、品川区の文化財、大いにＰＲしていきたいと、このように考えております。","id":"exchange-023"},{"speaker":"田中委員","kind":"確認","question":"２０１５年第２回定例会で生活者ネットワークは、一般質問で、移動教室の行き先変更について伺いました。そこで伺いますが、校長会の校外活動会、あるいは校長会が行き先の変更を決定する権限があると読み取れますが、その認識でよろしいのか尋ねました。","respondent":"有馬学務課長","answer":"最終的に起案をして決定をとるのは教育委員会の事務局のほうで決定をとります。その後、教育委員会につきましては、移動教室をこういう形で実施するということで、これは議案ではなくて報告事項ということで報告しているものです。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問","question":"決定権は教育委員会事務局にあるということで理解しました。この件に関して言えば、校長会の意向は大変大きいと考えるのですが、いかがか尋ねました。","respondent":"有馬学務課長","answer":"実際に子どもたちを連れて現場へ行って指導していろいろ活動しているのは、学校現場です。その責任者が校長ですので、まずその校長の意見は最大限尊重するというのが教育委員会の立場です。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"見解を伺います。いかがか尋ねました。","respondent":"有馬学務課長","answer":"その部会の判断によるということでございまして、こちらのほうから必ず記録をつくれというような指示は行っているものではございません。","id":"exchange-026"},{"speaker":"田中委員","kind":"確認","question":"決定と確認、承認がどこでされたのかというのは、とても大事なことだと思います。関連して、教育委員会会議録について伺います。","respondent":"品川庶務課長","answer":"教育委員会の議事録ですが、昨年度まで議事録は職員で作成しておりましたので、基本的には予算等かかってございません。ただ、今年度から議事録作成を委託しておりましてやっているというような状況です。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"その内容を決定する機関として、品川区の教育委員会は大変な重責を担っているとともに、説明責任も求められるものだと思います。品川区は逐語録に変更することは検討されていないのか尋ねました。","respondent":"品川庶務課長","answer":"昨年度まで、委員のおっしゃるとおり、要約を議事録として出しておりました。今年度４月から逐語録というような形で対応していくというような方向で進めているところです。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"現在、大崎中学校、伊藤学園、八潮学園、豊葉の杜学園の７年生で実施されていると伺いました。各校のスクールバディの実態といじめ防止への効果について、教育委員会の評価を伺います。","respondent":"村尾教育総合支援センター長","answer":"現在、４校が実施し、いわゆるモデル校指定として当初はスタートいたしました。このプログラムだけではなく、一概に一律にすぐにこの後、モデル校を廃止して全校展開というような考えをしているものではございません。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"その中で、子どもの学校生活の中での保護者の付き添いは、これをさせないということを再確認したと伺いました。現状、親の付き添いが行われているという話を伺っていますが、その実態についてどのようにお考えか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"現在、本年度から全小学校に特別支援教室が配置になりました。発達障害を含めて特別支援教室を開設するということで、保護者から大変負担が減った分、対象となる児童数も増えてきたというような現状です。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問","question":"普通学級の親御さんのお話を伺ったので、もう１回、答弁を。","respondent":"村尾教育総合支援センター長","answer":"これについては、現在、やはり登下校の安全等を含めて、やはりまだ学校が、例えばそこに対応するということはできておりません。まさに保護者のほうに、今、協力をいただいているというのが現状です。","id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"学校からあれこれ問題を指摘され、なぜうちの子だけ差別されなければならないのかと納得できずとも承諾するしかないのが親ではないでしょうか。学校現場でも、本当の意味での障害者差別の解消を一層進めていくことについて、見解を伺います。","respondent":"村尾教育総合支援センター長","answer":"改めてこちらのほうで確認をさせていただければと考えていますが、各学校でさまざまな形で進めていこうというふうに捉えているところです。学校のほうに、どのような負担が入ってくるのか等も十分こちらのほうで研究させていただければというふうに思っております。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"その後、障害者差別のことについて学ぶなどしなくても、自然にそういったことを学ぶことはできるのです。なので、ぜひ学校現場での本当の意味での障害者差別の解消を進めていくということを要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"１７６ページの国際理解教育でお伺いします。イングリッシュレッスン５００は好評で、今年度から４校に拡大したということですけれども、そのあたりのお考えを説明するよう求めました。","respondent":"熊谷指導課長","answer":"イングリッシュレッスン５００ですが、１１月からは、パソコン室を活用して行っていく予定です。ただ、まだまだ環境整備等の部分がありますので、これからはまたその部分も研究しつつ、検討してまいりたいというふうに思っております。","id":"exchange-034"},{"speaker":"沢田委員","kind":"質問・要望","question":"当初、８０名ぐらいということだったと思うのですけれども、これはぜひ品川区の全中学生が一度は体験できる制度にしていってほしいと求めました。ぜひとも事業の拡大をしてほしいと求めましたが、そのあたりのお考えをもう一度説明するよう求めました。","respondent":"熊谷指導課長","answer":"委員ご指摘のとおり、そういった部分を子どもたちの中で喚起するためにも、こうした事業を充実させていきたいというふうに考えております。方法等、さまざま検討していく部分がありますので、それは検討事項として考えていきたいというふうに思っております。","id":"exchange-035"},{"speaker":"沢田委員","kind":"質問・要望","question":"１８０名、大変多くの方が希望したということで、これはどのように選考したのかお聞かせほしいと求めました。２位が荏原第五中学校ということで、３位が私立の中学校でしたけれども、改めてこの感想を説明するよう求めました。","respondent":"熊谷指導課長","answer":"昨年度は９年生を優先、そして８年、７年というふうにとりました。９年、８年、７年の順でとったところです。","id":"exchange-036"},{"speaker":"沢田委員","kind":"質問・要望","question":"まさに今、課長がおっしゃったとおり、品川区は平成１８年度から英語教育を行ってきて、実を結んでいると思います。オークランド等ありますけれども、どういった形で学校とこの海外研修が連携できているのか、今どういうふうになっているのか説明を求めました。","respondent":"熊谷指導課長","answer":"やはり７年生ですと、８年生、９年生を中心に選んでおります。原則１名の推薦ということと、平成２７年度からは、私どもも面接をしてふさわしい子どもを選んで送っているところです。","id":"exchange-037"},{"speaker":"つる委員","kind":"確認","question":"１７７ページ、図書館経費、１８２ページ、学校給食費、時間があれば、１８３ページ、学校保健費を伺っていきたいと思います。ゆたかが４１年ということで、改修の計画があったかどうか、念のため確認で説明を求めました。","respondent":"木村品川図書館長","answer":"現時点では、ご案内ございました大崎図書館の移転というところが控えております。今後、そういう公共施設の改築、改修の計画に合わせて検討してまいるところであると考えております。","id":"exchange-038"},{"speaker":"つる委員","kind":"質問・要望","question":"全体の１０館を維持していただきたいし、さまざまな形で充実させていただきたいという、これを説明するよう求めました。","respondent":"木村品川図書館長","answer":"来館者、カード登録者、貸出数のお尋ねです。延べ来館者数に関しましては約１００万人、それからカード登録をされている方は約１４万人、約３５０万点です。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"そのいわゆる１４万人のうち、押しなべて大体年間で１０冊とか、その辺の数値はとれているものなのですか。利用数が多い、Ａさんが何十冊も借りて、Ｂさんは１冊とか、その辺がわかったら説明を求めました。","respondent":"木村品川図書館長","answer":"そういう意味では、出っこみ引っこみはあると考えていますが、具体的な数値として把握しているものではございません。","id":"exchange-040"},{"speaker":"つる委員","kind":"確認","question":"全体の話の部分なので、またそこについては改めて伺っていきたいと思います。返却ができるところの確認をしたいと思うのですが、それ以外のいわゆる図書館以外で受け取り、返却ができるところを説明するよう求めました。","respondent":"木村品川図書館長","answer":"現在は、今ご案内ありました駅前のサービスコーナーということでは、大井町、それから武蔵小山のサービスコーナー２カ所で図書の貸出、返却という形で受け付けております。","id":"exchange-041"},{"speaker":"つる委員","kind":"質問","question":"貸出配本、これは今、事務事業を見たら、団体貸出というふうになっていましたけれども、その説明と、実施先について説明を求めました。","respondent":"木村品川図書館長","answer":"団体貸出についてのお尋ねです。は福栄会と昭和医大に、本を一定のサイクルで貸しているというような、そういうサービスを行っております。","id":"exchange-042"},{"speaker":"つる委員","kind":"質問","question":"２、３歳もいわゆる午前中の時間とかも図書館を利用される機会はあると思うのですが、そうしたものがある館があれば説明を求めました。","respondent":"木村品川図書館長","answer":"それから、定期的におはなし会、特に今は０歳から２歳のおはなし会の需要は大変高まっております。そういう形で定期的におはなし会を展開しています。","id":"exchange-043"},{"speaker":"つる委員","kind":"質問","question":"今、おはなし会とありました。ＮＰＯなどにお願いをしたりとかということも含めてなのですが、これは図書館とかでやる場合は、どういう手続が必要か尋ねました。","respondent":"木村品川図書館長","answer":"児童センター２５館の中の数館で、演者の方、地域の方が自主的にやられているというお話は聞いております。ただ、数値といいますか、実績につきましては、そこは把握はしておりませんが、そういう実態としては聞いております。","id":"exchange-044"},{"speaker":"つる委員","kind":"確認","question":"基本的には、２５館ある児童センターを主として読み聞かせの会だとかということで、いろいろな形で展開されていると思うのです。先ほど確認させていただいた図書館以外で本を貸し出したり、先ほどの貸出配本だとか、そのあたりの考え方を説明するよう求めました。","respondent":"木村品川図書館長","answer":"児童センターでの図書取次の実施に関するお問い合わせです。置き場所もあると思います、運用体制もあると思います、いろいろな多角的な側面から今後の研究課題とさせていただきたいというふうに思っております。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問・要望","question":"多世代交流施設の１つとしてのそういういわゆる縮充策といいましょうか、そのあたり、ぜひ積極的に検討をお願いしたいと思います。対応をどういうふうにされているか説明を求めました。","respondent":"有馬学務課長","answer":"合計６４名がアレルギー症状があるということで、対応といたしましては、まず牛乳については完全除去いたします。それから、乳製品等が入った料理をつくる場合についても、そのおかずについては除去するというような対応で行っているところです。","id":"exchange-046"},{"speaker":"つる委員","kind":"意見","question":"その中で、和食を提供する機会。米飯というときに、和食になるのかちょっと別ですけれども、いわゆる和食を提供している機会はどれだけありますかとの意見を述べました。","respondent":"有馬学務課長","answer":"品川区は、週３回から４回ということで米食を提供していて、和食を中心に出しているというのが特徴かです。","id":"exchange-047"},{"speaker":"つる委員","kind":"質問","question":"昨年の一般質問で、再質問のところで参考にということで紹介させていただいた乳和食です。どういう和食のメニューのときでも出したりするわけだと思うのですが、乳和食があるのですが、これの活用についてお考えを説明するよう求めました。","respondent":"有馬学務課長","answer":"塩分、お醤油とかみそを使うということで、その辺が少し問題だということになっています。これから牛乳の件につきましては研究していきたいと思います。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"私は、１８２ページの就学援助費について拡充を求めて質問します。いかがか尋ねました。","respondent":"有馬学務課長","answer":"生活保護の世帯につきましては、就学援助ではなく、生活保護費のほうから支給されております。この新入学用品というのは３月に支給されているということですので、一般の就学援助の７月の段階ではなく、入学する前に支給されているです。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"要保護についてはそうなっているということですけれども、準要保護についても、やはり入学前から支給が必要だと思います。いかがか尋ねました。","respondent":"有馬学務課長","answer":"それは、４月１日以降、公立の小中学校に入学していること、それから品川区民であること、そしてもう１つ大きなところが、所得要件があるです。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまで求めても、先ほどありました所得認定が６月である、入学準備金については前年の所得で認定をして支給をしています。品川でできない理由は何か伺います。","respondent":"有馬学務課長","answer":"それからもう１点、我々のほうでも一応検討してみたことがあります。そういったことは６年生時点であげるよりも、しっかり中学１年生に入学した人、現在の制度を変える予定はございません。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"この紹介しました八王子市は、中学校でもそういった前から支給していくということをやっております。ほかのところでも６年生、返還を求めるようなことはないというところでやっておりますので、いかがか尋ねました。","respondent":"有馬学務課長","answer":"現在の申請数、相当な数に上っておりますし、今のところ、これを２回にわたって申請をし直すということは考えておりませんので、現行のままの形でいきたいと思ってあります。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"２０１４年９月、その強制執行の当日、無理心中を図ろうとしたところを発見されました。こうした深刻な実態が品川区で起きないように、改めて入学前からの支給を求めたいと思いますが、いかがか尋ねました。","respondent":"有馬学務課長","answer":"きちんと３月のところで支給されているということもありますので、一定の配慮は今の制度でもなされているというふうな認識に立っております。ということで、準要保護の方につきましては、現行の制度の中で運用をしていきたいというふうに思っているところです。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"次に、来年度の就学援助対象者の基準はどうなっているでしょうか。この間の生活保護の引き下げに連動させるべきではないと思いますが、いかがか尋ねました。","respondent":"有馬学務課長","answer":"来年度の生活保護の基準との関係をどうするかですけれども、生保の基準は平成２５年度から３年間にわたって引き下げられたです。今のところでどうこうということは申し上げられませんので、ご了解願いたいと思います。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"各費目について伺います。この案は、平成２８年度に入って実施されたのか、区で支給額について変更はあったのか伺います。","respondent":"有馬学務課長","answer":"平成２６年度から平成２７年度につきましては、学用品と新入学用品の単価改定ということで、金額をアップしているです。今のところ、区のほうでは、従来どおりの単価に基づいて支給をしていくという考えです。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"もし今後、やらないように求めてほしいと求めましたし、実施されても下げないようにしていっていただきたいと要望いたします。入学時の実態を調査し、区の支給額を実態に合わせて見直しを求めますが、いかがか尋ねました。","respondent":"有馬学務課長","answer":"７年生で３万４５６円、８年生、９年生で３万４,４１６円。そのほか主なところでいきますと、修学旅行費６万円、卒業アルバム、小学校１万１,０００円、中学校が１万円と、大体そのぐらいです。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"それに合わせて見直しを行ってほしいと伺いましたので、ぜひそれを求めたいと思いますが、いかがでしょうか。いかがか尋ねました。","respondent":"有馬学務課長","answer":"基本的には、先ほど申し上げましたけれども、社会情勢等を踏まえまして、平成２６年から平成２７年というふうな改定をしています。ということで、今言った標準服等も含めまして、適宜判断してまいりたいというふうに思います。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ実態調査をして拡大していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"あべ委員","kind":"質問","question":"１７７ページ、それから１７８ページの図書館資料、学校施設建設ならびにＩＣＴ活用についてもお伺いしたいと思います。今の対象人数と、教育委員会としてこの事業を現在のところどう評価しているかについて説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"本年度から始まりました区の特別支援教室の実績ですけれども、２２４名の子どもたちが、この特別支援教室での学習等に取り組んでいるところです。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"従前は介助員や支援員と担任との連携ということが１つの大きなポイントとなっていたと思いますけれども、今回、どのようになっているのでしょうか。その仕組みを含めて説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"特別支援教室に通うのは週に１回、２時間から４時間程度ですので、特別支援教室の指導員が担任にアドバイスしたことについて。それぞれの特別支援教室の担任がどのような対応をしているかをお互いに情報共有をすることで、その子にとって今必要な支援がどうなのか、今。","id":"exchange-060"},{"speaker":"あべ委員","kind":"質問","question":"連携についても伺いましたが、介助員の方がかなりこの春、足りなくなったというようなお話も聞きました。学校現場でも春の段階で相当混乱したというふうに聞いているのですけれども、その対応について、区教委としてはどのように今後お考えか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"ぐっと減ったということはこちらのほうでも認識をしておりますが、この専門員がさまざまな学習の支援であったり、また。学校間の連携であったり、区としてこの子どもたちへの支援、それから指導の充実を図っていこうというふうに考えております。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問","question":"先ほど、学校の付き添いという話もありましたけれども、その背景には、介助員の絶対量の不足もあるのではないかと思います。そうすると、区教委として、この介助員の確保について、さらに積極的な施策を何か考えていく必要があるのではないかと思いますが、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"現在、区のほうでも介助員、学習支援員ということで、配慮を要する子どもたちの対応を今進めているところです。そことの連携を図りながら、また地域の中で、現在視野に入れて検討を進めているところです。","id":"exchange-062"},{"speaker":"あべ委員","kind":"質問","question":"平成２７年度の決算で６,０００万円弱となっておりますが、ほぼこれは１億７,０００万円、１億８,０００万円で来ているのです。それとも本年度の予算でもやはり６,０００万円程度となっておりましたが、一時的なものなのか説明を求めました。","respondent":"木村品川図書館長","answer":"こちらに関しましては、基本的に委員のおっしゃいました１億７,０００万円というベースは変わりません。そこの中に入っておりまして、合算すると１億７,０００万円、例年そのぐらいのペースで購入しておるものです。","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問","question":"これは選書のシステム自体も変わったということなのでしょうか。それとも決算、予算の書き方だけが変わったということなのか尋ねました。","respondent":"木村品川図書館長、篠田学校計画担当課長","answer":"平成２７年度から指定管理者制度を導入いたしまして、まず一次選定を指定管理者、中央館は委託をしていますが、委託の事業者がまず一次選定をする。それから二次選定を区の職員で全体調整をするというような仕組みに変えております。基本的には一義的に就学人口への対応がまず１つございまして、今のところ、現状のキャパシティーで子どもたちは対応できるということが１つ。","id":"exchange-064"},{"speaker":"あべ委員","kind":"質問","question":"選書の仕組みを変えたことによるメリット、あるいはねらいがあれば教えてください。東海中学校のほうは、そうですね、一応理解いたしました。","respondent":"木村品川図書館長","answer":"利用者の方の層もいろいろ変わります。蔵書構成に関しまして、そういう部分ではきめ細かいニーズに沿った選定ができているというふうに、それがメリットと感じております。","id":"exchange-065"},{"speaker":"あべ委員","kind":"質問","question":"ＩＣＴを活用した学習について、簡単にお伺いしたいと思います。例えば、読字障害の子に対して、それに適したアプリを使うといったような使い方も含めての利用となっているのかどうか説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"特別支援教育でのタブレットの部分につきましては、今、委員おっしゃるとおり、学習支援関係の読み書き、また計算、さまざまなものに活用できるようなアプリで学習をしております。","id":"exchange-066"},{"speaker":"あべ委員","kind":"質問・要望","question":"特に学習障害を持ったお子さんに対して、タブレット等のアプリでかなり活用できるものが増えていると思います。普通学級等においても、個々のニーズに応じてこうした機器を使うということも視野に入れていただきたいのですが、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"通常学級におきましても、現在も既に読みがなかなか厳しいということに対しては、音声ペンを使ったものという、それはタブレットとは違うのですけれども、今後、そのような形、合理的配慮という視点からも必要になってくると思いますので、今後検討してまいります。","id":"exchange-067"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひそういったことがないように、教室内での指導も含めて充実してほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"渡部委員","kind":"質問","question":"公立学校ですから、間違いなく周知をされていますし、今年も９月に学校案内がそれぞれ入学を控えている方々に配られました。保護者がすごく気にするところ、とりわけ小学校の学校案内でしたけれども、脚注ですか、書かれています。","respondent":"有馬学務課長","answer":"４月に新たな校種として義務教育学校が設置されたということで、これは小学校１年生のときに入学して中学校へ上がるときにどうなるのか。そのため、若干内容が細かくなったということもありまして、参照ページ等を入れたものです。","id":"exchange-069"},{"speaker":"渡部委員","kind":"質問","question":"実はこの後、インクルーシブ教育の関係で特別支援のことについて伺っていくのですけれども、これを全戸配布されているわけですね。先ほどのあべ委員からの質問にもありましたように、これが配られて、まずこれがどういうふうに配られているか説明を求めました。","respondent":"有馬学務課長","answer":"このパンフレットにつきましては、住民基本台帳をもとに、新入学となる全世帯に対して郵便で送っているです。","id":"exchange-070"},{"speaker":"渡部委員","kind":"質問","question":"伺ったところですと、５校回っている方もいるということですので、特別支援教育について伺っていこうと思います。先ほど、人数をほかの委員が伺っていたので聞きました。","respondent":"村尾教育総合支援センター長","answer":"劇的にこの特別支援教室の人数が増えた１つの要因といたしましては、説明もしておりますけれども、そのために保護者の付き添いが必要であった。","id":"exchange-071"},{"speaker":"渡部委員","kind":"質問","question":"やはり給与もいいですし、いわゆるＮＰＯに委託している介助員の仕事量は減ったのかなというふうに認識をしたのですが、それは間違いでしょうか。１６日通ううち、さまざまな活動ができるというふうには認識していたのですが、ちょっとその辺を説明するよう求めました。","respondent":"村尾教育総合支援センター長","answer":"この特別支援教室に配置される都からの専門員ですけれども、通常、特別支援教室を置いている在籍校と派遣校との連絡調整がメインになります。","id":"exchange-072"},{"speaker":"渡部委員","kind":"質問・要望","question":"先ほどのほかの委員の質問のときにご答弁も伺っていますので、やはり地域の学校へ来ていただくことはありがたいですよね。私自身も、意外とその連携がスムーズになっていたと確認をしているのですけれども、もしくはすみ分けとかというのはどういうふうにお考えか尋ねました。","respondent":"熊谷指導課長","answer":"これまでもＰＴＡの皆さんには非常に学校支援をしていただいてきたところであります。品川区を超えて東京都の中でのつなぎということを考えたときに、学校地域コーディネーターという立場が必要であるというふうに考えております。","id":"exchange-073"},{"speaker":"渡部委員","kind":"質問","question":"ただ、こういう仕組みができた以上、それがコーディネーターの仕事となるわけですね。僕、そういう関係がちょっと知りたかったので、教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"例えばＰＴＡのＯＢの方、ＯＧの方がコーディネーターをやっていることが多うありますので、卒業しても活躍の場がある。ＰＴＡと町会をつなぐ立場でもあるということで、そういった意味も含めて、コーディネーターを置いていきたいというふうに考えております。","id":"exchange-074"},{"speaker":"渡部委員","kind":"質問","question":"一生懸命理解しようとするのですけれども、なぜこの質問をしているかといいますと、いわゆる地域の理解がないのです。そうですねとは、そこまでは言い切れない部分がありますので、またの機会にいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"提案","question":"私からは、主に１７８ページ、品川図書館運営費、幾つかお伺いをします。ほかのところにも拡大したらいかがですかというふうにご提案しましたら、検討するというようなご答弁でしたが、進捗状況について伺いますとの意見を述べました。","respondent":"木村品川図書館長","answer":"大井町線の荏原町駅から歩いての図書館ですけれども、そちらのほうでも取扱いを開始するということで、今年度は３館で展開をいたします。それから、これから他館でも販売できるようにというところで、福祉施設と協議の上、拡大を検討していく予定です。","id":"exchange-076"},{"speaker":"あくつ委員","kind":"提案","question":"そのとき委員からもさまざま提案がありましたけれども、例えばそこで大きく福祉施設製品の販売等をやってみたらいかがかなと思うのです。それはやはり図書館内で販売するということも１ついい取組みだと思うのですが、１つ大きな意義があるのではないかと思うのですが、いかがか尋ねました。","respondent":"木村品川図書館長","answer":"これから魅力ある図書館づくりというところで、内部でも検討チームをつくりまして、実際に二子玉川も見に行かせていただいております。今後、サービスコーナーを運営するところとも協議を重ねまして、そういう形で持っていきたいなというふうには今考えているところです。","id":"exchange-077"},{"speaker":"あくつ委員","kind":"質問・要望","question":"区民からの要望もあって私も調べたのですが、Ｆｒｅｅ Ｗｉ－Ｆｉ ＆ ＴＯＫＹＯで１階から５階まで、それは都立の図書館には書いてあります。昭和２５年にできた法律ですから、ぜひそういったところも拡充をしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"木村品川図書館長","answer":"確かにニーズの高まりは認識しておりまして、利用者の方からもぜひ整備をしてほしいという声もいただいているところです。慎重に運用ルールを整理しながら、もちろんセキュリティも確保しながら、研究課題として引き続き進めてまいりたいというふうに考えております。","id":"exchange-078"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これも区民要望で、図書館内で携帯電話の使用は禁じられています。こういう区民のご意見がありますので、ぜひ検討してほしいと求めましたが、いかがか尋ねました。","respondent":"木村品川図書館長","answer":"委員もおっしゃいましたように、確かに難しいところがかなりあります。お声をいただいて、何か私どもでできることがあるのか、これから考えてまいりたいと思います。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"ましてや学校選択をしているものですから、どういうふうに避難をしていったらいいのかということを整理する必要があるのかなと考えています。１８３ページの給食食材放射性物質検査ですが、これもう役割は終わっているのではないですかということでのご意見をお聞きしたいと思います。","respondent":"品川庶務課長、有馬学務課長","answer":"どういうふうに行っていくべきか、それから、そのあたりのところを検討していきたいと考えています。今後また芝の入替え等もありますので、整備をやっていきたいと、このように考えております。 実際にこれをやっていて、これがどこでこの役割を終えたのかと判断するのは大変難しい問題だというふうに捉えております。どこでやめるのか、この辺につきましては、また慎重に検討をしていきたいというふうに思っている事項です。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"理解を求めて子どもたちの教育環境の整備をしていただきたいと考えていますので、地域の方への説明を含めてお答えをお願いします。なので、しっかりと国の指針がきっちりしているのであれば、この放射性物質の検査は、もうそろそろ役目は終わっているのではないか尋ねました。","respondent":"品川庶務課長、有馬学務課長","answer":"学校のほうでも何か周知できる方法がないかというのは、再度これは校長会と相談をして、何か方法があるかどうか検討していきたいと思います。それからあと、人工芝の導入にあたっては、地域に少し周知が足りなかったという経過もあるの… さまざまな声を聞きながら判断してまいりたいと思います。","id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１７２ページの義務教育施設整備基金積立金について伺いたいと思います。それに対しての補助金の仕組みがどうなっているのか、何％ぐらい学校改築のときに補助金が出ることになるのかということについても説明を求めました。","respondent":"品川庶務課長、篠田学校計画担当課長","answer":"現在の義務教育施設整備基金の残額ですが、平成２８年度５月時点ですけれども、約１８０億円となっています。 改築中のものも含めまして、残った学校が、小学校でいきますと２１校残っているということになっています。中学校につきましては６校残っている形になっていますので、順次、改築を進めていくような形で考えているところです。","id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国が責任を持つべきというところで、やはり補助金の割合や額を増やすよう求めるべきだと思うのですけれども、いかがでしょうかというのが１点です。その答申が平成２０年度ですから、平成２０年度に出された答申については、どう総括をしているのかについてもお聞かせほしいと求めました。","respondent":"品川庶務課長、篠田学校計画担当課長","answer":"１点目の補助金の要望というところなのですけれども、２３区で庶務課長会を開催しております。毎年、学校改築の補助金につきましては、意見を出しまして、東京都、国に要望をしているというような状況です。今、私どもも考えておりますので、廃止するしないはまたこれは審議会の中で検討の推移を見ながらという形になってくると思いますので。","id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何としてもなくさないでほしいという、この時点では、人口の推計がわずか３年間で７年間も後にずれるという状況があったと思うのです。そういうことからすると、前提そのものがずれていると思うのですけれども、そこら辺の認識はいかがか尋ねました。","respondent":"篠田学校計画担当課長","answer":"平成２０年の答申時では、６歳人口で平成２７年、１３歳人口で平成３２年がピークになるという前提で審議が進められてきたものです。再編等につきましても、その辺を最新の人口動向等を踏まえながら、学事制度審議会の中で検討がされていくものと考えております。","id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この文科省が出している統廃合の手引についても、そういう項目の中で、地域にとって学校がどれほど大きな存在なのかということが書かれているのです。地域とともにある学校づくりということで、丁寧な議論を行うということで書かれていますので、ぜひこういう視点でやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"渡辺委員","kind":"質問","question":"成果報告書の１７４ページ、英語科についてと、１７５ページ、特色ある教育活動経費全般で伺います。そんな中で、このオリ・パラ教育をどう生かしていくか、総論でまず１つ説明するよう求めました。","respondent":"熊谷指導課長","answer":"今年度、５校指定されておりますけれども、日本のよさを改めて知るというふうなところにつながっていると思います。外国の方々からアメリカンフットボールについて学び、日本の剣道について一緒に学ぶことで伝えていくというような授業を行っているところです。","id":"exchange-086"},{"speaker":"渡辺委員","kind":"質問","question":"それは地域イベントでこの間も宿場まつりですか、こんなに反応があるのはなぜだろうと思ったら、間があって懐かしいのですごく求心力があった。それとあとは、本当に教育委員会がリードすべきと私は思うのですが、いかがでしょうかという意味で、昔の遊びで伺えればと思います。","respondent":"熊谷指導課長、村尾教育総合支援センター長","answer":"そういった遊びを通じて、昔遊びを通じて学んでいく日本の伝統のよさということもあります。これは絵本等で伝えていくのではなく、実際に体験していく、そういったことが非常に重要であるというふうに感じております。昔遊び、今現在、学校ではということもここでご説明できればと思いますが、小学生一、二年生に生活科というものがあります。","id":"exchange-087"},{"speaker":"渡辺委員","kind":"質問","question":"もっと全区的にぜひオリ・パラ教育もちょうど項目であったものですから、いろいろなことが想像できたものですから、こんなことできるよ」。補習と銘打ったから補習だけではなくて、すまいるスクールでの展開等も承知はしているので、その辺、全体で説明を求めました。","respondent":"熊谷指導課長","answer":"放課後、それからサマースクール、そういったところで取り入れて行ってきております。荏原平塚学園、品川学園、豊葉の杜学園で拡大しています。","id":"exchange-088"},{"speaker":"渡辺委員","kind":"質問","question":"この辺を詳しく伺いたいのと、もう１つ、全校展開だと思います。この辺の平成３１年の目標数値がたまたま出ていましたから、それに向けて段階的な取組み等ありましたら説明を求めました。","respondent":"熊谷指導課長、村尾教育総合支援センター長","answer":"一人ひとりの生徒の学習支援およびコミュニケーション能力の向上といったことを目的としております。今、拡充を目指していきたいところでありますが、環境整備ですとか、さまざま課題も見えてまいりましたので… 平成２７年度、１１種目の共通種目を休み時間等、さまざまな形で取り組んでいこうという取組み。","id":"exchange-089"},{"speaker":"塚本委員","kind":"質問","question":"１７７ページ、それから１７４ページの市民科・各教科充実経費、そのほかにもということでお伺いしたいと思います。そしてそれがこの平成２８年度からの全小学校への特別支援教室の展開に際して、フィードバックされているのか、この辺をお伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"まず１年目、どういうような体制をつくらなければきちんとした連携が育めないかどうか、その辺のモデル事業ということで実際に行いました。拠点校を４校として、平成２８年度、品川区では全小学校で一斉に開始できるというような成果として得られたというふうに考えております。","id":"exchange-090"},{"speaker":"塚本委員","kind":"質問","question":"これまでの質疑で、学校担任と訪問指導員の間のコミュニケーションが非常にとれるようになっているということが大きいという答弁もございました。その指導員と学校側の担任の間の連携に一役買うというのですか、そういうことも期待し得るところかどうか、少しお伺いをしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"この特別支援教室の実施についてです。なかなか個別にはすぐ対応はできない部分もあるのですけれども、もうちょっとフォロー的に学習の支援ができる、個別の対応ができるというような。","id":"exchange-091"},{"speaker":"塚本委員","kind":"質問","question":"もう１点、今回の特別支援教室という形になると、そういう機会がなくなるところもあるかと思います。いろいろな形で、保護者側からはいろいろなことを聞きたいという場合があるのではないかなとも思うのですが、その辺についてはいかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"それに含めて、実際に年度の初め、それから終わりには、必ず個人面談を行っていく。例えば１学期、そして進めていくということで、きちんとやっていくというふうな方向で現在取り組んでいるところです。","id":"exchange-092"},{"speaker":"塚本委員","kind":"質問","question":"１７４ページなのですけれども、私の１つの理解としては、ここが非常に中心的なことなのかなというふうに受けとめているところです。１５の能力ということで体系化をされておりますが、どういう形で品川区の中でなされているのか、そこをお伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"基本的には市民科のカリキュラム検討委員会等を立ち上げて、または、どうやったらもっといいかというようなものも増えております。その時代時代に応じ、子どもたちに身につけてほしい力を育成する、そういうような教科として進めていこうというふうに考えています。","id":"exchange-093"},{"speaker":"塚本委員","kind":"質問","question":"そういうカリキュラム検討委員会ですか、１５の能力という体系化の中では、お伺いをします。","respondent":"村尾教育総合支援センター長","answer":"情報化も含めて、大きな社会の変化の中で子どもたちにこの社会の中でという部分での「生き抜く力」というものを大きく取り上げているところです。四年生で言うと９名程度、生き方を考えていく、そういうような本当に市民科独自の教育方法を今進めているところです。","id":"exchange-094"},{"speaker":"塚本委員","kind":"意見","question":"この市民科というのは１つの大きな柱として、今後とも取り組んでほしいと求めましたので、どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-095"},{"speaker":"高橋（し）委員","kind":"意見","question":"１８４ページの学校施設建設費で、城南小学校の改築基本設計委託が、平成２７年度で決算４,３４８万円であります。これを受けて、平成２８年度は実施設計ということになっているかと思うのですが、この実施設計のほうの進捗状況についてお尋ねしますとの意見を述べました。","respondent":"篠田学校計画担当課長","answer":"城南小学校の実施設計につきましては、この春に基本設計が終了しましたので、それに引き続き、実施設計を今年度取り組んでいるところです。","id":"exchange-096"},{"speaker":"高橋（し）委員","kind":"質問","question":"その実施設計の中で、委員会では図などを見せていただいたのですが、当初の予定とは変更を余儀なくされてきたという状況があるのではないかと思いますが、その辺についてのご説明をお願いします。","respondent":"篠田学校計画担当課長","answer":"委員お話のあったのは、おそらくお隣のお寺のイチョウの木の関係のお話かと思います。学校としても最大限取り得る対応をしていこうということで、設計のほうに、基本設計の部分から若干の変更を加えて進めているといった状況があります。","id":"exchange-097"},{"speaker":"高橋（し）委員","kind":"質問","question":"木の保存に関連して設計のほうの変更がということなのですが、それは予算上で何か措置が必要になる設計の変更なのかということ。それから、工事はしていただいて、竣工時期でしょうか、そちらのほうの影響などはあるのか尋ねました。","respondent":"篠田学校計画担当課長","answer":"予算上の対応ですけれども、何らかの対応が必要になってくる部分はあろうかと思いますが、調整中です。設計がそういった形で手直しをする部分があるということで、今のところ、若干遅れるような見込みで話が出てきております。","id":"exchange-098"},{"speaker":"高橋（し）委員","kind":"質問","question":"小学校６年生の方が行けても２校、下手すれば１校ぐらいで、なかなかいろいろな中学校を見に行けないという実態があります。中学校３年生は受験の時期ですので、中学校２年生（８年生）がプレゼンなどに参加すれば、そういったことについてのお考えをお伺いします。","respondent":"有馬学務課長","answer":"委員ご指摘のとおり、今まさに１０月が学校選択のための学校説明会ということで行われているわけです。なるべく重ならないようにということで、校長同士の調整をしておりますけれども、１つの案としてこれから検討をしてみたいと思っているところです。","id":"exchange-099"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"時間があれば、災害時の教職員の対応についてお伺いしたいと思います。子どもたちが大人になったときに求められる能力、これからの時代に求められる子どもたちの資質と能力、品川区のご見解を示すよう求めました。","respondent":"有馬学務課長、村尾教育総合支援センター長、熊谷指導課長","answer":"それからもう１つは、そこでもある程度、情報共有はできているというふうに考えております。これは平成２４年ですけれども、これに基づきまして… どこに連絡をしたらいいのか、どういう処理をすればいいのか、そこを研修として今進めているところです。子どもたちがきちんと身につけなければいけない力… 成果検証につきましては、今後、品川教育検討委員会教科等検討部会で内容検証していくところです。","id":"exchange-100"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そのチョイスをできるかできないかということが今後の教育として求められるものでありますので、教育改革もぜひ品川区から国にも求めながら、国も今。これは要望で終わりますが、ぜひこれからの時代に求められる教育の部分に関して、もう一度ご答弁ほしいと求めました。","respondent":"熊谷指導課長","answer":"ＳＮＳも含め、ＩＣＴ教育につきましては、今後、品川教育検討委員会の中でも内容面も含め検討していきたいというふうに考えております。情報収集能力、活用能力、そして適切な情報をきちんと根拠をもとに判断する能力を身につけさせていきたいと思います。","id":"exchange-101"},{"speaker":"若林委員","kind":"質問・要望","question":"１７４ページ、プラン２１推進事業と、１７６ページの特別支援教育費の２点で伺います。一体型と分離型について、何か成果に違い、傾向があるのかどうかということをお知らせほしいと求めました。","respondent":"熊谷指導課長","answer":"小学校との連携が充実していると答えたのは、分離型が８２.４％ということで、一体型のほうが１０ポイント程度上回っておりました。で、五、六年生のリーダーシップが醸成されるというよさも見られると考えています。","id":"exchange-102"},{"speaker":"若林委員","kind":"質問・要望","question":"客観的な、というものに耐え得るものをぜひつくっていただきたいという思いで、お考えをお聞かせほしいと求めました。いわゆるプラン２１全体として、もっと詳細に品川区の教育は全国に先がけて、僕はチャレンジしてもいいのかなという思いで質問します。","respondent":"熊谷指導課長","answer":"品川教育検討委員会、立ち上がってまいりますけれども、そうした丁寧な対応をしていきたいというふうに思っています。分析が非常に難しい部分もありますけれども、丁寧に行っていきたいというふうに考えているところです。","id":"exchange-103"},{"speaker":"若林委員","kind":"質問・要望","question":"同じような言い方になるのでしょうか、引き継ぎを行うために、（仮称）個別カルテを作成するということが提言をされております。この３つの関係、教育委員会ではどのように捉えているか、ちょっとお聞かせほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"２点目の乳幼児期、そして福祉関係がより充実を図りながら、その子の支援を図っていくという考え方です。保育課との連携も図りながら、できる支援を高めていく、そういうような考えです。","id":"exchange-104"},{"speaker":"若林委員","kind":"質問・要望","question":"前に一般質問で取り上げましたけれども、品川区は今、先がけてやっているという認識でよろしければお答えをほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"伊藤委員","kind":"確認","question":"私は、１７３ページ、いじめ防止対策について、それから１７４ページ、プラン２１推進事業に関連して質問します。学校はＢ君を呼び出して状況を確認しましたけれども、当時の２人の関係に十分注意を払うことなく、いじめはなかったと結論づけられました。","respondent":"村尾教育総合支援センター長","answer":"２点目につきましては、教員は決して１人で抱え込むことなく、必ず情報を共有し、組織で対応していくこと。子ども自身がきちんと善悪を判断して考えて行動できるという学校での指導、地域、いじめ防止について努めていこうというふうに考えております。","id":"exchange-106"},{"speaker":"伊藤委員","kind":"意見","question":"それから、さまざまな人間関係や、このケースは部活と絡んでいました。私としては、学校全体で問題を共有して対処していく仕組みがさらにとられていかないといけないと思うのですが、改めてお話をお願いいたしますとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"方法が、やはり冷やかしやからかい、また悪口等が９０％近くと多いという現状があります。そういうときにも、きちんと子どもたち同士が話ができる、そういうことが必要かなというふうに考えております。","id":"exchange-107"},{"speaker":"伊藤委員","kind":"質問","question":"もっと言うと、確かに外的な面でさまざまな制度を構築することは当然必要です。中学生の心に具体的にしみ入るような、そういう授業を展開していくといいと思うのですが、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"友達同士で本当にいろいろなものに挑戦をして達成したときの喜び、そんなものをとても大切にしなければいけないというふうなところがあります。","id":"exchange-108"},{"speaker":"伊藤委員","kind":"質問","question":"感性でわかってもらうことのほうが、私はより効果的だと思うのですが、いかがでしょうか。お願いいたします。","respondent":"村尾教育総合支援センター長、高山子ども育成課長","answer":"まさに子どもの心に届くというさまざまな経験は、本当に大切なものというふうに受けとめております。外部の力、外部の人材を活用して、子どもたちの心の育成を進めていければというふうに考えているところです。私のほうから、児童センターが実施します赤ちゃんふれあい事業の実績についてご報告いたします。","id":"exchange-109"},{"speaker":"伊藤委員","kind":"質問・要望","question":"全ての中学校、特にいじめが発生しやすい年齢に集中して行ってほしいと求めましたので、これは要望をお願いいたします。東京都と連携をした上で、当該学校にフィードバックをしていただいて、それをもとに学校が対応していく仕組みを検討してみたらどうか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"いわゆる携帯電話やスマホによる対応については、研修、また子どもたちへの教育のほうは十分進めていこうと考えております。個々がきちんと判断ができる、そういうことがまさに教育に求められている部分なのかなというふうに考えているところです。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これだけＳＮＳのことが青少年の犯罪やらいろいろなことで騒がれるという状況の中ですから、難しいですよね、限定されるのは難しいです。過日、一般質問で、大井第一地区町会連合会の正式決定として、この地区に小中一貫校を建設してほしいという要望が出されたということを聞きました。","respondent":"篠田学校計画担当課長","answer":"今、区政協力委員会でのご要望があるということで、私どもも地域の声として受けとめているところです。さまざまな点に配慮して６校整備しましたけれども、そういった考え方について、その先を検討していくべきものと考えているところです。","id":"exchange-111"},{"speaker":"南委員","kind":"質問・要望","question":"１８２ページの学校給食費をはじめとした教育費の父母負担軽減を求める質問をしたいと思います。どのようなものがあるのか、それぞれの項目と年額にするとどのくらいになるのか、まず教えてほしいと求めました。","respondent":"有馬学務課長","answer":"例えば部活動の自分で用意するものですとか、教科書以外の教材費、そういったものが個人の負担になっているというようなことです。それ以外には、ＰＴＡ会費、生徒会費等が個人の負担という形になっているものです。","id":"exchange-112"},{"speaker":"南委員","kind":"質問・要望","question":"それと、金額について伺ったのです。実際問題、どのくらいということを教育委員会自身も認識しておられるのかというところを確認したいと思って伺っておりますので、説明を求めました。","respondent":"有馬学務課長","answer":"生徒会費等につきましては、各学校によって違いますけれども、おおよそ両方合わせて６００円前後というようなことで聞いているところです。それから、そういったところでは個人が選んでいるスポーツなり文化系などによって差が出てくるものというふうに認識しております。","id":"exchange-113"},{"speaker":"南委員","kind":"質問・要望","question":"その点についての認識も伺いたいと思います。これらの教育費、父母負担がやはり当然８％分がかかってくるわけですし、その点についての状況がどうなっているのか教えてほしいと求めました。","respondent":"有馬学務課長","answer":"保護者の負担ですけれども、ここ数年の物価スライドということで言えば、そんなに大きくは変わっていないというふうな認識を立てております。８％分の影響ということですけれども、全体としては、そういった中で飲み込んでいるものというふうに認識しています。","id":"exchange-114"},{"speaker":"南委員","kind":"質問・要望","question":"あるいは２３区の課長会等々、そういう方向性を要望として改善を求める、そういう姿勢は示していただきたいと考えています。これも私は非常に重たいというふうに印象を持つのですけれども、この点についての区の教育委員会の見解も伺いたいと思います。","respondent":"有馬学務課長","answer":"ただし、この問題と給食費を誰が負担するかというのは全く別物というふうに考えております。そんな中でも、認定された４,６００人の方については、そういった低所得者に対しては配慮をしているものというふうに考えているところです。","id":"exchange-115"},{"speaker":"南委員","kind":"質問","question":"ごめんなさい、低所得者への配慮のところがあまりよくわからなかったのですけれども、もう１回説明を求めました。","respondent":"有馬学務課長","answer":"約２万人弱の生徒のうちの４,６００人については、就学援助できちんとその分を支援しているということですので、支給しているということで認識をしているということを申し上げたものです。","id":"exchange-116"},{"speaker":"南委員","kind":"質問","question":"給食費の補助を、第三子以降の方に対する補助もやっているということですから、それはやっているということは改めていいことだと思っているわけです。この点についての認識をお願いします。","respondent":"有馬学務課長","answer":"多子家庭への補助ということで、これも就学援助よりもさらに所得要件を緩和して行っているものです。無料化につきましては、施策がおそらく定住化とか少子化対策とかということで、目的が違ったところで行っているものというふうに認識しております。","id":"exchange-117"},{"speaker":"たけうち委員","kind":"質問・要望","question":"しっかり地域に学校のほうでご説明をするのが本来の筋なのだというような感じのお話があったと思うのですけれども、それはどうなのですか。何かどうもされていないようなところもあるので、トラブルがないような形でやっていかなければいけないと思うので、そこをもう１回説明を求めました。","respondent":"品川庶務課長","answer":"今まで約１０校程度、今まで導入をしたときに地域から反対の声がなかったというような経過が我々の認識としてもあったのかというところがあります。やはり支障のあるところ等、そういったところの改善点なども少し検討しながらやっていきたいと、このように思っております。","id":"exchange-118"},{"speaker":"たけうち委員","kind":"質問・要望","question":"この審議会等でも話し合うのかどうかちょっとわかりませんけれども、ぜひ進めていただきたいと思うので、それについてのお答えをいただきたい。そういうことで一定程度、教育委員会からアドバイスをしてあげるということが今後大事ではないかと思うのですが、その辺について説明を求めました。","respondent":"品川庶務課長","answer":"これをうまく活用していくように、方法は今後検討していきたいと、このように思っております。地域との対応とか、そういった面についてはいろいろと考えていきたいと、このように思っております。","id":"exchange-119"},{"speaker":"松澤委員","kind":"質問","question":"このお礼というのでしょうか、１９９１年、これを契機として品川区との友好憲章が制定されて交流が始まっています。どうしてなのか、これについてお話を伺いたいと思います。","respondent":"品川庶務課長","answer":"どういう位置づけかといいますと、これは国の重要文化財の１つ下の、その候補というような位置づけになっております。したがいまして、品川区の指定文化財にするということも、なかなかハードルが高いというような現在の状況です。","id":"exchange-120"},{"speaker":"松澤委員","kind":"質問","question":"ですから、この梵鐘にふさわしい栄誉というか名誉というか、これはやはり品川区でしっかりとすべきではないかと思うのです。それぐらいの価値があるものだと思うのですけれども、いかがか尋ねました。","respondent":"品川庶務課長","answer":"この梵鐘の価値については、我々としても非常に高く評価をしているところではあります。何か別の方法がないかどうかについては、少し研究をしていきたいと、このように思っております。","id":"exchange-121"},{"speaker":"松澤委員","kind":"質問","question":"これは、民生費のほうと、子どもたちの保育園ですか、一緒にすると、年間６２０万円かかっているのですね。これは先ほどの答弁ですと、やってくれという方がいるからやめませんというふうに聞こえたのですけれども、もう一度答弁をお聞きしたいと思います。","respondent":"有馬学務課長","answer":"その中で、この検査をどういうふうに今後考えていくかというところが問われているのだろうと思います。私が先ほど言ったのは、そういう声を聞きながら、適切に判断をしてまいりたいというようなことを答弁したものです。","id":"exchange-122"},{"speaker":"松澤委員","kind":"質問","question":"２３区の中で、あるいは全国の中で、こういう食材の放射性物質検査、やめたところはまだないのでしょうか。その辺についてお聞きしたいと思います。","respondent":"有馬学務課長","answer":"その中でも年に５回、６回というふうに実施しているところは５区あります。ただ、最近の傾向としては、平成２５年度に３区で実施をやめたと。","id":"exchange-123"},{"speaker":"松澤委員","kind":"質問・要望","question":"３点目、９月の第３回定例会で渡部議員が質問したのですけれども、いよいよ１０月２７日から審議会が始まります。これの審議項目、諮問項目がもうはっきり決まったのでしたらお教えほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"学校規模および学校種、地域バランス、そういったものをまず検討すると。それに加えまして、それらを踏まえた上での学校改築についての考え方、こういったものを取り上げていければというふうに考えておるところです。","id":"exchange-124"},{"speaker":"松澤委員","kind":"意見","question":"ほとんどが３学級がいい。我々もこれから質疑のしようがありませんので、しっかりとした答申が出るように、ひとつよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"ですから、学習塾がほとんど見当たらないという状況でした。なぜ品川区では、このような取組みが、同じ日本の中でできないのか尋ねました。","respondent":"熊谷指導課長","answer":"小学校では４３％、中学校で１１％という状況でありますけれども、これについては問題ありません。できない子どもへの補習ということでありますけれども、これについても各学校で補習を行ってきている。","id":"exchange-126"},{"speaker":"須貝委員","kind":"確認","question":"でも、どこか目立つところはあるのですか。毎月ごとに理解度確認のためテストを実施して、そしてそれを子ども本人はもとより、親にきちんと教えているのです。","respondent":"熊谷指導課長","answer":"福井も品川も７６点ということで、東京都よりも、全国よりも上回っているところです。福井もやっているかと思いますが、品川区におきましても、きちんと子どもの学力を身につけるという指導は行っていると思います。","id":"exchange-127"},{"speaker":"須貝委員","kind":"質問・要望","question":"では、なぜ皆さん、塾へ行くのですか。実際、いいですか、塾へ行っていないお子さんが中３になりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"ここでお聞きしたいのですが、留年をさせている子はいるのですか。再試をするなり、実施して、子どもたちを将来きちんと支えるような仕組みづくりはあるのか尋ねました。","respondent":"熊谷指導課長","answer":"私は中学校３年の担任をしておりましたけれども、平成５年、「中学校における進路指導について」が出されました。子どもたちがしっかり考えて選びとっていく、それに準じたものを考えさせる、そしてキャリア教育に変わってきたです。","id":"exchange-129"},{"speaker":"須貝委員","kind":"質問","question":"だって、過去問をやったら、わからないじゃないですか。そういう自分のところで問題をつくっているところ、では、そこだって学校は教えられないではないか尋ねました。","respondent":"熊谷指導課長","answer":"教員が教えられないのではないか、問題ができないのではないかというのは、それは教員に対して冒涜であります。ですので、教えられる教員を私どもは研修でも育てていきたいと考えています。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"だって、実際、教えていないではないですか。教育体制は、私はすごく疑問に思うのですが、ご見解を説明するよう求めました。","respondent":"熊谷指導課長","answer":"必ず確認して、もう一度次の段階に行かないと、いつまでたっても旧態依然の教育しかできないと思います。そしてまた、錦の御旗では決してない、品川区としてプライドを持って全国に発信していく教育改革を行っていきたいと考えております。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問・要望","question":"私、これ、品川区の教育はどうなっているのだろう。僕はそういうところをやはり、ほかの人は言わないかもしれないけれども、僕はきちんと言って、教育を立派な教育にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"大倉委員","kind":"質問・要望","question":"時間があれば、また伺います。学校給食費なのですが、食品ロスについて伺いたいと思います。","respondent":"有馬学務課長、村尾教育総合支援センター長","answer":"中には若干食べ残しがあるということですので、この生ごみ処理の中には若干の食べ残しもあるだろうというふうに考えているところです。金額については、この生ごみ処理にかかる費用としては、おおよそ１,２００万円ほどかかっているで… 家庭のほうに訪問する等の対応をとりながら、早期の対応に努めている、そういう現状です。支援において学校に復帰をした子どもの数ですけれども、全体の１２.９％が、またいろいろなケースで子どもたちを支援していきまして。","id":"exchange-133"},{"speaker":"大倉委員","kind":"意見","question":"そのときには、目標設定をしっかりして、改善をしていくことが大事であるというようなことも、第３次推進計画のほうでは載っております。昨年で小学生が１３名、中学生が２０名ということで、その把握についてのお考えをお知らせくださいとの意見を述べました。","respondent":"有馬学務課長、村尾教育総合支援センター長","answer":"一定程度、例えばトウモロコシの芯だとか、バナナの皮だとか、どうしても出てしまうものはあるかと思います。ただ、学校によっては、栄養士等を通じてそういった取組みをまた進めていきたいというふうに思います。一概には言えませんけれども、昼夜逆転が起きているとか、そういう生活習慣の乱れが１つの要因になっているというふうに考えております。","id":"exchange-134"},{"speaker":"大倉委員","kind":"質問・要望","question":"しっかりと子どもたちとともに、啓発とこうした食品ロスに対する取組みを充実していってほしいと求めました。子どもたちの生活習慣について、現状を知っていくということも重要ではないかと思いますので、そこはぜひ研究してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、ページ数はちょっとわからなくて、学級規模、少人数学級の実施についてを伺いたいと思います。今、３５人学級に取り組まれていますけれども、どのように考えているのか伺いたいと思います。","respondent":"有馬学務課長","answer":"いわゆる中１ギャップ対応ということで、ここは都の対応ということで、加配対応なりがされていて。ということで、少人数の重要性ですけれども、区としては、この都の基準にのっとってしっかりと学級編制をしていきたいです。","id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それともう１つ、聞き忘れてしまったのですけれども、小学校と中学校の全体の小中別で、１クラスの平均生徒数を教えていただきたいのです。お願いします。","respondent":"有馬学務課長","answer":"現在の１クラスの平均ですけれども、小学校全体で１クラスの平均人数は２９.８人です。中学校の部分につきましては３２.８人が１クラス平均になってあります。","id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"３５人学級、さらに３０人学級まで進めていくべきだと求めているところなのですけれども、ＯＥＣＤの先進国の平均では２１.３人です。３５人学級に全学年をしていくと、そして、そこにかかる区の負担はどれぐらいになるのかを伺いたいと思います。","respondent":"有馬学務課長","answer":"３５人、少人数学級にすべきですけれども、教育の質に関しましては、単に学級の人数で評価すべきではないというふうに考えております。４０人分の教員の人件費が直接かかりますのと、あとは、相当な金額がかかってくるのではないかというふうに思っております。","id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、国や都に求めていかなければ、これはなかなか進まないことだと思うのです。少人数学級だと思うのですけれども、国や都に求めていただきたいと思うのですが、いかがか尋ねました。","respondent":"有馬学務課長","answer":"それから、先ほど、４０人学級が増えるということもございました。我々としても、今後、その辺もしっかり考えあわせていかなければいけないことだというふうに思っているところです。","id":"exchange-139"},{"speaker":"浅野委員","kind":"確認","question":"２０２０年から小学校でプログラミングの教育が必修化される見通しとなったという報道を、５月ですか、見た記憶があります。内容を確認して、動きをするなりしてほしいと求めましたが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"実際には新たな教員をというよりは、担任が指導していくことが中心になりますけれども、やはり実際になかなかそこの指導は難しい部分もあります。","id":"exchange-140"},{"speaker":"浅野委員","kind":"確認","question":"このような安全の確認はもう既にされているのか、今後行うのかということについて、現状をお知らせほしいと求めました。防災ヘルメットは早急に必要になると、これは誰もが感じるかと思いますので、ご見解を説明するよう求めました。","respondent":"小林施設整備課長、品川庶務課長","answer":"今の校舎の耐震の関係についてご答弁いたします。建築基準法に基づいて、今回、耐震を済ませておりますので、法律上、現状は大丈夫ということで答弁します。学校施設については、通常、通常の地震よりもかなり強いものにも耐えられるというような構造にはなってあります。","id":"exchange-141"},{"speaker":"浅野委員","kind":"質問・要望","question":"中学校混声の部で金賞を１回、銀賞を５回、銅賞を１回受賞しています。このような取組みについて、学校としての評価、そしてまた、同じように取り組んでいる学校があれば説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"各学校を含め、区内の皆さんにも周知をしながら、より多く進めていこうというふうに考えているところです。吹奏楽または合唱等で取組みをスタートしている、また、現在も大きな取組みを続けているという学校があるというふうに考えております。","id":"exchange-142"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１７４ページ、品川のスポーツトライアル等経費、この辺に関して質問させてもらいます。これもまだ半年ぐらいの期間だと思うのですが、この半年ぐらいでどのような評価になっているかということを教えてもらえればと思います。","respondent":"村尾教育総合支援センター長","answer":"体育主任会での説明をした上で、今、進めているところです。子どもたちと一緒に取り組んでいく、また子どもたちの体の健康づくりにも大きく役立っているというような声を学校のほうからよく聞いております。","id":"exchange-143"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"というのは、ケーブルテレビか何かで放送することはできないのでしょうか。４月１日の発行となっているのですが、決算の中でこの発行がどこに出てきているかわからなかったので、それを説明するよう求めました。","respondent":"村尾教育総合支援センター長、品川庶務課長","answer":"子どもたち、小学校も中学校もこの連合体育大会に向けて、さまざま学校で朝練を含め取り組んでいます。ご提案のケーブルテレビ等、さまざまな広報につきましては、少しこちらのほうでも検討させていただければというふうに考えておりま… 「品川の教育」ですが、成果報告書１７７ページの文化財保護費の中に金額としては含まれた形で入ってあります。","id":"exchange-144"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"教育大綱の中に出ていたのですけれども、「品川区史２０１４」品川の歴史と区内各地域のあゆみと特色、これらの勉強も出ていたところもあります。こういうものを活用していただいて、その地域のことを知ってもらいたいなと思うのですが、いかがか尋ねました。","respondent":"品川庶務課長","answer":"この中で学習の一部にでも取り入れていただけるように努力していただければというふうに思っております。それから、校長会のほうにもそのような声かけをしていきたいと考えています。","id":"exchange-145"},{"speaker":"鈴木（真）委員","kind":"確認","question":"これは４月から開設して、本庁舎から離れたところにあることで、連携がうまくとれているのか。もちろんとっているとは思うのですが、その辺が非常に気になるところなので、確認の意味でお願いします。","respondent":"村尾教育総合支援センター長","answer":"連絡等を含めながら、２課にまたがるような事業はなるべく見直していかないと、お互い情報交換ができない部分がありますので見直しをする。定期的に週１回程度、また学校の支援を十分していこうというふうに、今取り組んでいるところです。","id":"exchange-146"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ連携を取り合って進めていってほしいと求めました。５つの都市像の中でどうつながっていくのかちょっとわからなかったので、どういうふうに入ってくるのか、そこを確認させていただきたいのですが。","respondent":"柏原企画調整課長","answer":"その中の１つの大きな都市像ということで、区全体の施策を進める中で、施策の大きな分野として切ったものがまず長期基本計画です。生涯学習であったり、文化であったり、こういったところも入れた中で進めるというのがこの教育大綱というふうに進めているものです。","id":"exchange-147"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先ほど、総合教育会議の中で詰めて、方針としては一般に出ていると思うのですが、都市像の下に基本方針が出てくるのです。基本方針がこの教育大綱と同じように見えてしまったので、項目が、例えば生涯学習とかいろいろ出てくる中で、そこが確認をしたかったのですが。","respondent":"柏原企画調整課長","answer":"長期基本計画というところがありまして、その下といいますか、具体的にどう進めるといところで教育大綱の考え方が出ております。その方針、長期基本計画でいろいろ方針が出ている部分について、この長期基本計画との整合をとったというところが中身です。","id":"exchange-148"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ちょっと自分が見た範囲でここがどうもすっきりしなかったので、ちょっと確認をさせてもらいました。もしよろしければ、品川の子どもに対してどのようにこれからやっていっていただくか、お考えをお聞きしたいと思います。","respondent":"中島教育長","answer":"この１０年の市民科の実施を中心とする重要なことに取り組み、また、さまざまな施策の中で大きく改善している状況もあろうかと考えております。そういう状況の中での学校教育というのは、地域との連携、さまざまなチームとしての機能なしには考えていくことはできないだろう。","id":"exchange-149"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"いろいろお話を伺って、ぜひ進めていっていただきたいし、基本方針に、たしか将来を生き抜く力ということもあったと思います。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/678897?Template=document&Id=1430#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":119470,"voices":342}},{"id":"h28-20161019-4","meetingId":"h28-c-settlement","date":"2016年10月19日","dateIso":"2016-10-19","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を133件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"初めに、オリンピック・パラリンピック開催へ向けて、区の取り組みについてお伺いいたします。お考えを説明するよう求めました。","respondent":"安藤文化スポーツ振興部長","answer":"そして、正確には今年から３年間ですけれども全校で体験教室を実施して、障害者スポーツの振興を普及していきたいというような報告を受けてあります。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"第２回定例会の一般質問で私が取り上げましたけれども、品川区といえば、オール品川で取り組めるイベントの開催をしていってはどうかと思います。この４年間の中で計画性を持って企画していってほしいと求めましたけれども、お考えを説明するよう求めました。","respondent":"安藤文化スポーツ振興部長","answer":"観光協会の４法人が１つになって、スポーツのプログラムを一緒に盛り上げていこうということで、徐々に進めているところです。進めるに当たっては、主体となる地域の皆さんと、より十分な協議をしながら実現していきたいと考えています。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"ＪＲの土地ですから、進めていると思いますけれども、また文化プログラムとも一緒になって活用できる方法を進めていってほしいと求めました。そういったＪＲへの働きかけをお願いしたいと思いますけれども、区としてのお考えを説明するよう求めました。","respondent":"安藤文化スポーツ振興部長、藤田都市環境部長","answer":"関係団体との緊密な連携ですけれども、ご指摘のとおり、十分な地域の方々との協議をもって進めていきたいと考えています。今後の予定としては、その後、その間にＪＲとしても跡地についての有効な活用については検討していきたいとしています。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に、医療的ケアが必要な子どもの療育についてお伺いいたします。現在、区としてはどのような対応を行っているのか説明を求めました。","respondent":"榎本福祉部長、齋藤子ども未来部長","answer":"区としての対応ですけれども、それを活用しつつ、さらに品川区独自の児童発達支援事業運営補助を追加して実施しているものです。ただ、平成２７年度から事業を始めておりますけれども、なかなか場所の確保が難しい状況で… 保育の視点での対応です。平成２７年１０月から、疾患・障害のあるお子様の居宅に訪問して、１対１での訪問事業を実施しております。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"品川区では１４名ということと、区としてどのように取り組んでいくべきとお考えなのか、お聞かせほしいと求めました。医療的ケアが必要な子どもたちが増加していくと考えられますけれども、現在の状況と、今後の対応についてのお考えを説明するよう求めました。","respondent":"齋藤子ども未来部長、本城教育次長","answer":"障害をお持ちのお子様がいらっしゃるご家庭でも、就労の継続を図りたいとご希望の方がいらっしゃいます。進めている事業に加えて、こういった事業の拡充を図りながら、女性活躍推進法の趣旨に従って取り組んでまいりたいと考えています。 私からは、医療的ケアが必要な児童への学校での対応についてお答えいたします。どんな体制が必要かということを、保護者とのお話の中で、きめ細かく対応することに努めているところです。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に、品川区の住宅施策についてお伺いいたします。現在の区営住宅、そして区民住宅のそれぞれの戸数、そして今後の動向と入居率の傾向についてお伺いいたします。","respondent":"藤田都市環境部長","answer":"現状と同様の傾向ではないかと考えてございまして、２棟が２０年の期間満了を迎え、返還することになってあります。入居率の低い借上型の返還に伴いまして、入居率については上がっていくものと考えています。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"借上型と建設型を合わせての割合でしたので、若干変わってくるかと思うのですけれども、空き室の傾向についてお伺いします。この入居者（登録）募集というのを行っていると思うのですけれども、建設型のほうの入居者（登録）募集の状況について説明を求めました。","respondent":"藤田都市環境部長","answer":"平成２７年度の入居の応募につきましては、１０１件に対しまして、入居できた件数が２５件となっています。それぞれ開きがございまして、また入居の希望のない物件につきましては、随時募集を行っている状況です。","id":"exchange-007"},{"speaker":"沢田委員","kind":"意見","question":"今の入居者（登録）募集も１０１件中２５件ということで、それなりに、その要因をどのように分析されているのかお聞かせください。傾斜家賃ということで、そういったことをどのように考えているのか説明を求めました。","respondent":"藤田都市環境部長","answer":"おおむね、近傍の民間住宅の家賃と変わらない状況になってきたことも、委員お話しのとおり、原因の一つであると考えています。民間住宅ストックが数多くある中で、こうした方々の住まいの希望の条件に合うものが、やはり民間住宅にあったものと考えています。","id":"exchange-008"},{"speaker":"沢田委員","kind":"意見","question":"そのお考えをお聞かせください。シェアハウスとして賃貸するなど、新たな行政ニーズへの対応をしていく必要があると思うのですが、お考えを説明するよう求めました。","respondent":"藤田都市環境部長","answer":"こうした検討を進めてきましたけれども、現状の法に基づく制度を活用していることもあり、なかなか解決が難しい状況にあったのが現状です。こうした状況も踏まえまして、課題としての認識から、さらなる研究が必要かと考えているところです。","id":"exchange-009"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に資源回収についてお伺いいたします。どうなっているのか、区内でどれぐらいの地域で資源の各戸回収を行っているのか、説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"可燃ごみ・不燃ごみの各戸収集実施以前は、各戸収集の開始に伴い、残った資源だけを資源ステーションとして集積所を継承して使用しています。従前の資源ステーションを改築後設置できず、１５件であったものが三、資源を回収せざるを得ない場所が出てきております。","id":"exchange-010"},{"speaker":"沢田委員","kind":"意見","question":"２割ではそういったことを行っているということで、資源ステーション回収の方向性をどうしていくのか、お考えをお聞かせください。なかなか成立しにくくなってきてしまうのではないかとも思うのですけれど、現状の認識についてどうお考えなのか、説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"集約化を進めつつも、用地を確保した資源ステーションの整備が１つの課題となってくるかと思いますので、検討していく必要があるかと考えています。地域への支援体制、最も効率的な収集体制が維持・再構築していけるものと思い、その方向で頑張ってまいりたいと考えています。","id":"exchange-011"},{"speaker":"沢田委員","kind":"質問・要望","question":"以上で私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問","question":"沢田委員に引き続き、総括質疑を行います。初めに委員長、途中で資料を提示させていただいてよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"提案","question":"質問は、これは携帯電話会社にも協力いただいた情報伝達訓練を展開すべきと考えますが、いかがでしょうか。品川区の見解をお伺いいたしますとの意見を述べました。","respondent":"曽田災害対策担当部長","answer":"多くの区民に的確に情報を伝達する手段として有効だと認識しておりますので、どのような訓練が可能であるか、今後検討してまいります。このため、発災時においては安否確認が最優先されるということについて、今後は周知してまいりたいと考えております。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問","question":"この内容を品川区でも導入すべきと考えますが、いかがでしょうか。各家庭等に、水・食料の３日分の備蓄等を義務化すべきと考えますが、いかがでしょうか、ご見解を説明するよう求めました。","respondent":"曽田災害対策担当部長","answer":"区では、自助の観点から、高層マンションに限らず全ての家庭におきまして、３日分以上の水・食料などの生活必需品の備蓄をお願いしております。現時点では、それぞれを義務づけることは考えておりませんが、今後も引き続きしっかりと啓発に努めていきたいと考えております。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"提案","question":"しかし、その解決は具体的に進めていかなければならないわけでありますから、品川区の対応と計画を改めてお伺いいたします。私どもの会派の提案により、このマップが制定されたのは、たしか３年ほど前と記憶しておりますとの意見を述べました。","respondent":"曽田災害対策担当部長","answer":"地域と連携して対応できるように、町会などからなる協議会を設置して、帰宅困難者対策を進めているところであります。これまでに８町会・４小学校での開催を終えておりまして、平成３０年度までには残りの町会・小学校で実施してまいります。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"意見","question":"毎年新しく入ってくるわけだから。万が一、こう避難すべきだということがわかるマップが引き継ぎされるべきだと思うのですが、もう一度この部分だけは答弁をお願いいたしますとの意見を述べました。","respondent":"曽田災害対策担当部長","answer":"ご指摘の点につきましては私も認識しているところでありまして、皆さんが考えた、そういったものは共通するものです。この共通するものについては、やはり共有する、引き継ぐということは考えていかなくてはいけないと考えております。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問","question":"これを踏まえて、昨年９月１日に昭和大学、１２月に山中小学校で、学校医療救護所の開設訓練が行われました。お願いいたします。","respondent":"西田健康推進部長","answer":"こうした検討の中、第三北品川病院、震災時に病院に押し寄せると想定される傷病者のトリアージおよび応急救護を実施することを定めております。以上のとおり、医療救護体制を構築し、医療救護所開設訓練を実施する中で、よりよい計画とするための検証も行っているところです。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"今お伺いしました現在の医療救護体制の中では、特に住人への周知や、それから医療従事者の確保、多くの課題があるということを思っております。お願いいたします。","respondent":"西田健康推進部長","answer":"１０月下旬に、第１回マニュアル策定会議を開催する予定で、今年度末までにマニュアルは作成させる予定です。医療救護所の人・物・場所・仕組みを明確とする作業を進めながら、今まで課題とされました救護所の位置関係も含め検証し、改善策を提示する予定です。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"確認","question":"確認していただいて、ともかく場所を決めることは一番大切なことだと考えていますので、ぜひ十分なご検討をお願いいたします。次の責任者を立てる計画等、進んでおりますでしょうか、現状を説明するよう求めました。","respondent":"曽田災害対策担当部長","answer":"平成２４年度から今年９月までに、２回以上の避難所運営訓練を実施しているのは４４の避難所であります。したがいまして、責任者となる方の優先順位について、今後の避難所連絡会議の中で検討していただけるよう、投げかけてまいりたいと考えております。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"それでもなかなか進まない現状があるわけですから、やはり品川区の中で、様々な情報を共有する。例えばどこの町会にはこういう人材がいるとか、自治会にこういう人がいらっしゃるというのは当然あるわけですから、改めて答弁をお願いいたします。","respondent":"曽田災害対策担当部長","answer":"責任者の不在というのも同様だと思います。これに限らず、様々な事態に対応できるように、引き続き防災対策を進めていきたいと考えております。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"確認","question":"各自治体等で確認している精神障害者等については、ある程度、具体的な避難計画も策定していたわけでありますが。しかし、行政がそれらの避難所を確認・認識し、必要な支援物資等を配布するのに、大変な努力と時間がかかった」という指摘がありました。","respondent":"曽田災害対策担当部長","answer":"現在、この対応について明確になっておりませんので、どう対応するかについて、今後検討してまいりたいと考えております。しかしながら、指定外避難所の避難も十分考えられることから、今後につきましてはその取り扱いも含めて検討していきたいと考えております。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"確認","question":"例えば、避難所の一部を原則女性のみの避難場所とし、その運営も女性が行う等、新たな視点で避難所運営を検討すべきと思いますが、いかがでしょうか。これらを踏まえて、いかがでしょうか、あわせてご見解をお願いいたします。","respondent":"曽田災害対策担当部長","answer":"遺体の身元確認についてでありますが、デジタルレントゲンにつきましては、身元確認を行うための有効な手段の一つであると認識しております。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"そこで、地域防災計画の１８８ページのカラー部分をお示しします。品川区全戸に配布すべきと思いますが、いかがでしょうか、ご答弁をお願いいたします。","respondent":"曽田災害対策担当部長","answer":"『わが家の防災ハンドブック』や『品川区防災地図』にも記載しておりまして、それぞれ平成２４年と平成２６年に区内全戸に配布しております。ご提案の振り仮名や関係部署の電話番号の掲載などについては、今後の改訂の時期に合わせて検討してまいりたいと考えております。","id":"exchange-024"},{"speaker":"新妻委員","kind":"質問","question":"特別支援教室に通う児童生徒の中で、特に読み書きが苦手な児童生徒はどれぐらいいて、どのような教科書を使っているのでしょうか。ＩＣＴ機器の活用を含めて、どのような学習支援をされているのかお伺いします。","respondent":"本城教育次長","answer":"通級指導学級や特別支援教室用のタブレットにおきましては、学習支援を行っているところです。それから、テストの際の対応ですが、より確実に時間内でできるように等の観点から、別の部屋で問題を読み上げることによって対応しています。","id":"exchange-025"},{"speaker":"新妻委員","kind":"確認","question":"昨年３月の参議院予算委員会で、「デイジー教科書を必要とする子どもの把握とニーズの仕組みを整えてほしい」との質問に対し、教育委員会を通じ。品川区でもこの調査が行われたと聞いていますが、今回の調査の目的である、通常学級の児童生徒の把握においても取り組まれたのか尋ねました。","respondent":"本城教育次長","answer":"文部科学省で平成２９年度の使用教科書に係る音声教材の需要調査として行われたものですが、１０月に回答を行ったところです。平成２９年度使用教科書において、または必要と見込まれる児童生徒数を調べる調査でございまして、または必要と見込まれるとしています。","id":"exchange-026"},{"speaker":"新妻委員","kind":"確認","question":"そこで現在、通常学級の児童生徒でデイジー教科書を使用している児童生徒はいるのでしょうか。そして、品川区はデイジー教科書の活用や必要性をどのように認識し評価されていますか、お伺いいたします。","respondent":"本城教育次長","answer":"品川区では平成２８年５月から通級指導学級に通っている児童１名が、国語の読み取り、あるいは社会の調べ学習や理科の実験準備等で活用しています。","id":"exchange-027"},{"speaker":"新妻委員","kind":"意見","question":"今回の調査は、今後、国が支援体制をどのように進めていくのかを検討するためのものです。品川区においては、調査で把握した内容を踏まえて、通常学級における今後の取り組みの方向性を説明するよう求めました。","respondent":"本城教育次長","answer":"実際に、集団の中で一部の児童生徒がタブレットを使うことに対しましての相互理解が必要であり、課題の一つとして考えているところではあります。","id":"exchange-028"},{"speaker":"新妻委員","kind":"質問・要望","question":"質問の２点目は、障害者の就労支援拡大と、品川区立心身障害者福祉会館についてです。この施設の設置目的・用途を改めてお伺いいたします。","respondent":"榎本福祉部長","answer":"それから地域活動支援センターでは、それから生活支援センターの相談件数は６,１８１人ということで、このような状況です。それからエレベーターも狭いということで、その辺の利便性が不足しているというところが一番の課題と考えています。","id":"exchange-029"},{"speaker":"新妻委員","kind":"確認","question":"先ほどのご答弁で、この施設の設置目的、また使用状況は確認させていただきましたが、この施設では、かつて授産作業の就労支援がありました。どのような就労支援の内容だったのか、なぜ行われなくなったのか、経緯を説明するよう求めました。","respondent":"榎本福祉部長","answer":"厚生施設として運営しておりましたけれども、作業メニューとしては、クリーニングや革細工を行ってきたところです。クリーニング作業等ができなくなってきたことで、今現在は、ほかの場所でそういう作業については行っているという状況です。","id":"exchange-030"},{"speaker":"新妻委員","kind":"質問","question":"ふれあい作業所、そして平成３１年度にリニューアルされる旧品川児童学園がありますが、地域に偏りがあるのではと思います。荏原地域も含めて、区内全域にこの作業所が整備されることが望ましいと考えますが、ご所見をお伺いいたします。","respondent":"榎本福祉部長","answer":"平成３１年度開設予定の品川区立障害児者総合支援施設内におきましても、就労継続支援Ｂ型、定員２０名ということで設置する予定になってあります。就労継続支援Ｂ型の施設につきましては、次に開設する際に、エリアについても考慮していきたいと考えています。","id":"exchange-031"},{"speaker":"新妻委員","kind":"質問・要望","question":"利用状況を再度ご確認いただき、検討を進めてほしいと求めました。人口増において、近隣の学校の教室を増やすなどの対応ができるのでしょうか、お伺いいたします。","respondent":"本城教育次長","answer":"勝島地区の再開発に伴う就学動向や学校の対応についてですが、人口増が見込まれることによりまして、対応に漏れのないように。空き教室の活用や、多目的室の普通教室への転用など、受け入れ対策について引き続き講じていく必要があると考えているところです。","id":"exchange-032"},{"speaker":"新妻委員","kind":"提案","question":"私は２０１５年の一般質問で、癒やしの場を提供してみてはいかがでしょうか」と提案させていただきましたが、人道橋の設置で回遊性が実現し。そこで、勝島運河の人道橋設置に当たっての区のご所見をお伺いいたしますとの意見を述べました。","respondent":"藤田都市環境部長","answer":"最近、勝島地区における物流・倉庫などの機能から、マンションへの転換をしてきているものが出てきている。こうした中で、地域の要望として、改めて交通の利便性、特に人の通行について利便性の向上を求める声があることを認識しています。","id":"exchange-033"},{"speaker":"新妻委員","kind":"質問・要望","question":"その認識をされた上で、ぜひ課題を解決し、この方向性を示してほしいと求めましたが、いかがでしょうか。もう一度お伺いいたします。","respondent":"藤田都市環境部長","answer":"人道橋の設置においては、道路と道路を結ぶ橋というような形にはなかなかならないということで、難しいような現状もあります。勝島運河における人道橋につきましては、地域の意見を踏まえながら、課題解決に向け、しっかりと考えていく必要があると考えています。","id":"exchange-034"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこで品川区は、勝島地域の特性や、これからのまちづくりにおいて、どのように認識されているか、お伺いいたします。そして、勝島地区のまちづくりを進めるためには、地域の声を聞く場が必要ではと思いますが、区のご所見を伺います。","respondent":"藤田都市環境部長","answer":"倉庫などの物流施設からマンションなどへの土地利用の転換を踏まえまして、区としても今後のまちづくりの方向性の検討の必要性を認識しています。具体的に進める際にはどのような手法がいいのかについては検討していきたいと考えています。","id":"exchange-035"},{"speaker":"新妻委員","kind":"質問・要望","question":"住民・観光客、共存のまちとして、品川区のモデル地域となるようなまちづくりをぜひ要望して、総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"若林委員","kind":"質問・要望","question":"住宅施策とは何か、目的のためにこれからどのような施策が必要となるのかということも確認しながら考えていくことも大切と思います。品川区はこれまで、公営住宅や民間住宅を合わせ、どのような住宅施策を進めてこられたのか伺います。","respondent":"藤田都市環境部長","answer":"これまで進めてきた住宅施策としては、適正な管理などについて支援し、一方では耐震化や不燃化についても支援してきたところです。引き続き、高齢者や障害者などの住宅確保要配慮者が民間賃貸住宅などに住み続けられるよう、住環境を整備することが課題と考えています。","id":"exchange-037"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、この転入・転出の超過の傾向性の分析をお聞かせほしいと求めました。住宅施策のベースとなる人口動向を踏まえ、今後の住宅施策の考え方・方向性についてもお聞かせほしいと求めました。","respondent":"中山企画部長、藤田都市環境部長","answer":"それで、分析詳細については現在行っておるですけれども、この辺の２０代・３０代前半というのは流動性が非常に高く、大きく転入がある。それから、その中に、転出のほかの世代の動向についての分析等は今後深めてまいりたいと考えます。区民住宅における、お子様の成長に合わせた広い住宅への住みかえの実現など、子育て世帯の定住化促進に努めてきたところです。","id":"exchange-038"},{"speaker":"若林委員","kind":"質問・要望","question":"続いて、住まいに困っている方たちへの支援について伺います。オーナーから行政で活用してほしいと意向のあった２７軒について空き家活用事業をスタートさせていますが、住まいへの活用事業がありません。","respondent":"藤田都市環境部長","answer":"民間の不動産というなりわいに、区として積極的にかかわっていくことはいかがなものかと考えているものです。都営住宅のうち一般世帯向けについては２７倍程度になっているといったものと認識しており、公的住宅の応募や窓口相談などでも把握しています。","id":"exchange-039"},{"speaker":"若林委員","kind":"質問・要望","question":"品川区の住宅施策に空き家を活用するという積極的な姿勢を示し、認識していただくことが必要ではないでしょうか、お考えをお聞かせください。この決算特別委員会の審査の中で、品川区議会公明党から改めて要望させていただいたのに対し、今委員会での大きな成果の一つであると考えています。","respondent":"藤田都市環境部長","answer":"地域に合ったやり方を進めることが重要であり、法には目標年次も示されておりますが、さらに検討を進める必要があると考えています。居住支援という観点では、都の居住支援協議会連絡会などを参考にいたしまして、支援の仕組みやスキームを検討してまいりたいと考えています。","id":"exchange-040"},{"speaker":"若林委員","kind":"質問・要望","question":"福祉部長にご答弁を求めたいと思います。ぜひ住宅部門との連携、また協議会の主導的な立場であるとも考えておりますので、福祉部長のご答弁を最後にお願いいたします。","respondent":"榎本福祉部長","answer":"確かに住宅に困る方々というのがいらっしゃるという問題は大変重要なものだと認識しております。そういうことも考えながら、都市環境部とともに、居住支援についていろいろと検討を進めてまいりたいと思います。","id":"exchange-041"},{"speaker":"若林委員","kind":"質問","question":"次に教育について伺います。そこで、「プラン２１」の目的はどの程度達成されたのか尋ねました。","respondent":"中島教育長","answer":"小中一貫教育の実施、また学校選択制も絡んでまいりますけれども、様々な中で大きく意識を変えてきた状況がアンケート等からも見てとれます。","id":"exchange-042"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、品川教育ルネサンスの３つの柱で何をどのように変えようとされているのか、説明をしてほしいと求めました。「品川教育」とは何か、説明をお願いいたします。","respondent":"中島教育長","answer":"これまでより、例えば校長や教職員が入れかわっても、その学校のカラーを持続・継続していけるような学校づくりが進むものと考えております。そして、「品川教育」というのは、これまでの品川区の教育の根幹であった小中一貫教育を、やはり「プラン２１」から継続するものです。","id":"exchange-043"},{"speaker":"若林委員","kind":"質問・要望","question":"いま一度「プラン２１」について伺いますけれども、特に学校教員と学校選択制について、私は再評価したほうがいいのではないかと考えています。学校選択制をどのように総括し、地域との協働を進めようとするのか、お考えをお聞かせほしいと求めました。","respondent":"中島教育長","answer":"様々な場面の課題も、先ほど申しましたように出てきておりますので、これは継続的に意識をつないでいかなくてはいけない部分と考えております。教育改革の継続の部分ですけれども、これからも継続的に行っていく必要があるものだと考えておりますので、それを。","id":"exchange-044"},{"speaker":"若林委員","kind":"確認","question":"最後に災害対応について伺います。そこで確認の意味で伺いたいと思います。","respondent":"曽田災害対策担当部長","answer":"大規模地震発生時には、区役所機能の継続と早期復帰を確実なものとするための事前対策として、平成２４年３月に策定した計画です。応急対策業務として被害状況の把握や避難所の開設・運営、医療救護所の体制整備など、災害対応に関する１,０４２業務を応急対策業務とする一方で。","id":"exchange-045"},{"speaker":"若林委員","kind":"質問","question":"通常業務について、区の職員だけでは業務対応が困難になるという状況は、今どのように想定されているのかということをお聞きします。業務継続計画の見直し、他自治体や諸機関からの支援の受け入れなどの事前の準備の検討は必要と思いますけれども、ご見解を伺います。","respondent":"曽田災害対策担当部長","answer":"あるいは応急対応業務の量が増大した場合などには、区の職員だけでは業務対応は困難になるという可能性があると考えております。今後は、協定のあり方や事前の準備についてさらに検討を進めていきたいと考えております。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問","question":"なぜ区立園の民間委託を始めたのでしょうか。それぞれ伺います。","respondent":"齋藤子ども未来部長","answer":"平成１３年に国の方針が変わりまして、民間活用を図るということで、補助金といった仕組みが変わっております。毎年５００人から８００人近く、子どもが前年より２％ずつ増えている中で、やはり民間活用を図るということが民営化の理由です。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"毎月の履行を確認し検査を行っていながら、４月から配置されていない看護師分の補助金を支給していたことになります。看護師分の補助金の返還を求めるのか伺います。","respondent":"齋藤子ども未来部長","answer":"仕様書に従って看護師が配置されていない点については不履行だと私どもも認識しております。現時点では３００人ではなくて１７０人ですので、連携園である品川保育園や、あるいは本課の看護士を派遣して対応しています。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"そして、基準外でも、区が求めていた看護士配置、いなければそれでいいというものなのでしょうか、伺います。そして、年間でトータルで調整していきたいということですけれども、返還を求めない理由を伺います。","respondent":"齋藤子ども未来部長","answer":"したがって、契約という形で年度いっぱい事業を継続していただいて、年度末をもって終了とし、円滑な引き継ぎを図るといった取り組みをしたものです。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"区と夢考房の認識のずれとは何でしょうか、伺います。以上、３点伺います。","respondent":"齋藤子ども未来部長","answer":"保育教育の実施の中で、体力、あわせて個々のお子様方の特性・個性に応じて保育士が対応する。この認識のずれも同様でございまして、私どもは区の方針に従って、保育を実施していただけると考えておりましたが。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"体現したことを伝えたかったということですけれども、どういうことでしょうか。区が園長に直接指示したいと申し出たことが、おかしいのではないでしょうか、伺います。","respondent":"齋藤子ども未来部長","answer":"「偽装請負」という言葉が出てきましたので、ちょっと簡潔にご説明申し上げますと、偽装請負は労働派遣法の脱法に当たるということなのだと思います。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"そして業務委託についてですけれども、指示することができないというのが業務委託の手法ではないでしょうか。区の保育方針で運営することはできないということではないでしょうか、伺います。","respondent":"齋藤子ども未来部長","answer":"具体的な保育方針の違いにつきましては、物の考え方が違ったため、「のびのび育つしながわっこ」の趣旨に従って保育を実践してください。これが方針の違いでありました。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問","question":"なぜ守られていると言えるのか伺います。それぞれ伺います。","respondent":"齋藤子ども未来部長","answer":"延長保育も実施されております。ただ１点、看護師の配置がないことについては、委員のご指摘のとおりです。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問","question":"これについても守られていないと思いますが、いかがでしょうか。それは事業者が判断することになり、保育士に残ってもらえる保証はないと思いますが、いかがか尋ねました。","respondent":"齋藤子ども未来部長","answer":"あわせて、契約の１条項の不履行をもって解除できない。あわせて、円滑な引き継ぎ保育に努めるといった経験もあるですので、お子様方にご迷惑はかけないように来年の４月を迎えたいと考えております。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"ひろまち保育園では、もともと区の職員だった方が１３人入って、何とか、区の求めるものを実現しているという状況です。民営化したところには、毎回、区の保育士だった方に入ってもらうということでしょうか、伺います。","respondent":"齋藤子ども未来部長","answer":"これは契約の方針に従っておりませんので、区としてはこのような考えはございません。これは、区として想定外のことですので、今後、委託の縁があったときに、チームとして区の職員、保育士を送り込むかということはございません。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほどのご答弁では、互いの協働や区との連携を確認できたというお話でしたけれども、それであれば解除ということにはならないのではないでしょうか。そして、改めて、看護師配置など、仕様書を守らせることができない理由を伺います。","respondent":"齋藤子ども未来部長","answer":"５年間にわたって継続的な信頼関係を構築する、これが難しいと考えたので、合意解除に至った。全体の契約関係を覆すことはできませんので、看護師が配置できなかったことは大変残念ではありますが、引き続き相手方に配置を求めてまいります。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問","question":"二度と繰り返さないために、新たな事業者選定について改善した点はあるのか、伺います。今後の事業者選定についてもどういう改善をするのでしょうか、伺います。","respondent":"齋藤子ども未来部長","answer":"あわせて、一番大事な保育の方針についても、経営者の方と十分事前にお話し合いする機会もございました。中身を知るということを通して、品川区の保育方針、高い質のサービスを継続できる受託者にお願いしていきたいと考えております。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"最悪の場合、毎年、事業者がかわる可能性もあるということですか、伺います。夢考房選定のときには、こういったことはやらなかったのでしょうか、伺います。","respondent":"齋藤子ども未来部長","answer":"次に、毎回繰り返されるかということで、今回の案件につきましては極めて例外的なことと受けとめております。私は４月に着任したので、相手方事業者の現場は見ておりますので、いろんな目で多角的に確認してきたものと考えております。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"原因を明らかにし、対策を打たなければ、同じことの繰り返しではないでしょうか、伺います。区の保育方針で運営を行うためには、業務委託の方針を根本的に見直し、品川区の直営でやるべきではないでしょうか、伺います。","respondent":"齋藤子ども未来部長","answer":"取り組みといったものを、合意解除という例外的な対応ではございましたけれども、強く発信できたものと考えております。スピーディーに待機児対策に対応する、認可保育園事業というものの制度根幹を継続させていく、この方法しかないと考えております。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問","question":"区としてしっかり対策しなければいけないと思いますが、いかがでしょうか。民営化の推進について、改めて品川区の直営でやるべきではないかと思いますが、いかがか尋ねました。","respondent":"齋藤子ども未来部長","answer":"待機児対策は、認可保育園を構築することでは対応できません。これに対応する、最も合理的な手法をとって、保護者の期待に応える。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問","question":"毎年、事業者交代のリスクを負わなければならない区立保育園の民間委託、民営化はやめるべきです。以上で、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問","question":"区長は、送った先でどういった未来があり得るかを知っての発言なのか、本人・家族の不安をどう考えているのか伺います。今年２月の激励会で入校・入隊した品川区民の動機と人数を伺います。","respondent":"田村総務部長","answer":"今年の第３回定例会で飯沼委員の質問は、「ご自分の意思で自衛隊に入隊・入校される区民の方々を激励するための会議です」とお答えしたものです。自衛隊法第３条では、先ほど申し上げた生きがいや使命感から、入隊・入校を職業として選択したものと考えております。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問","question":"このもとで開かれる激励会とは、その先の未来に何があり得るのか、区はなぜ考えないのか、改めて理由を伺います。家族、そして現役の自衛官をどういう思いにさせるのか、区のお考えを伺います。","respondent":"田村総務部長","answer":"再三お答えしているように、国の安全保障に関しましては国会において議論されるべきことで、一自治体として見解を述べることは差し控えします。そういう方向性を出して決定しているものですから、引き続き、区として激励ということは必要なことと考えております。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は、自衛官の上官でさえ、部下を目の前に、「あなたの意思でここにいる」と、心からそう言えるでしょうか。この発言の撤回と、この状況での激励会中止を求めますが、いかがか尋ねました。","respondent":"田村総務部長、曽田災害対策担当部長","answer":"自衛隊との連携は本当に不可欠ですから、引き続き、募集の事務あるいは激励会とともに自治体の役割と考えておるところです。激励会については引き続き重要な式典と考えていますので… 入隊予定者激励会ということでやっていただきまして、１人ではないのだな、頑張っていけるなと思った覚えもあります。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"そして、住環境の悪化が公害だとなぜ認めないのか、理由を伺います。それと最後に１つ、いわゆる魔の１１分に品川区は入るのか、入らないのか、その点も伺います。","respondent":"藤田都市環境部長","answer":"国はこれを受けまして、２段階でのフェーズで説明を実施してまいりました。このような認識をされているようですけれども、国のほうとしては、そのような表現あるいは解釈、判断をする立場にはないと聞いてあります。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問","question":"そして、そもそも公害とは一体どういう定義なのか、この点もあわせて伺います。二分に１回通過することになりますが、何デシベルぐらいの騒音に区民はさらされることになるのか、伺いたいと思います。","respondent":"藤田都市環境部長","answer":"品川区上空ですけれども、国のほうからの説明である時速３００キロは、分に直すと分速５キロという形になります。「今だ国の案を知らない」、「説明が不十分である」というような声も聞かれることから、引き続き地域に対する具体的な説明を求めてまいります。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、今の時点で反対しないとは賛成と同じではないかという点と、そして騒音について区が正しいと考えている理由は何かと伺いましたので、説明するよう求めました。","respondent":"藤田都市環境部長","answer":"このことに努めてまいりたいと考えているものです。これについて国のほうにも、もう少し何とかならないのかという働きかけを行いまして、基準の弾力的な運用につなげてきたところです。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"車のレースのＦ１のストレートで、時速約２８０キロから３５０キロぐらいですから、同じぐらいのスピードで、超低空に響くわけです。この騒音が公害とならない基準の、どこが正しいと思うのか、伺いたいと思います。","respondent":"藤田都市環境部長","answer":"今、定められている基準があるわけですから、これに当てはまるかどうかということが解釈の視点になってくるのかと考えています。国に対して具体的な方策を示すように、今、求めているところでごいます。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"大井町駅の上空３００メートルですが、例えば３００メートル上空でパチンコ玉を落としたら、地上の落下速度は時速何キロになるのか伺います。そして、航空機によるＰＭ２.５、ナノ粒子の上昇は起きないのか伺います。","respondent":"藤田都市環境部長","answer":"様々な気象条件・対応により、状況が大きく異なるために、具体的なものはなかなか難しいのかと考えています。あるいはＣＯ２のうち、影響は限定的であるという説明を、私どもは国から受けているところです。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"このパチンコ玉が時速２７６キロで庁舎に当たると屋上はどうなるのか、もし人に当たったら一体どうなるのか、区の認識を具体的に伺います。何だか小さいようには言いますが、ＰＭ２.５やナノ粒子が上昇することが問題だとは思わないのか、この点を伺います。","respondent":"藤田都市環境部長","answer":"現在の羽田空港の機能強化の進捗状況に合わせまして、地域防災計画の中にどのようにしていくかについては考えていくものと考えています。この辺については、国のほうからまた改めてしっかりと、私どももいろんな情報提供を得ていきたいと考えています。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問","question":"具体的な被害は明らかなのに公害とは認めないとは、もはやこの計画を擁護するものではないでしょうか、伺います。当時はどのような努力があって、どんな被害を防いだのか、伺います。","respondent":"藤田都市環境部長","answer":"最近、国とお話しすると、これに加えて、もっとほかにはないのかというような検討もしていると聞いてあります。環境に配慮した方策については、これからも新たな技術等を踏まえながら考え、それに向けて努力を重ねていきたいと考えています。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのは、なぜ当時は公害と認めたのか。そして、今回の新ルートは、これを壊すものではないでしょうか、説明するよう求めました。","respondent":"藤田都市環境部長","answer":"先ほども申し上げましたとおり、その当時も今も変わっておらず、新たな技術革新に合わせて少しでも影響を小さくしていくことが大切だと考えています。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"これは一体どういうことなのか、この点を伺いたいと思います。品川区の広報では「音の沖合移転」との記載もありましたが、この成果を壊すものだという認識はないのか、この点も伺います。","respondent":"藤田都市環境部長","answer":"これが、今お話をされているところの分かれ目になるのかと考えています。区としては、環境に与える影響を区民が感じるものとして国のほうに申し入れを行いまして、こうした形につながってきているところです。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問","question":"では基準が一体どう変わったのでしょうか。住民の被害は何も変わらず、起こり得ると指摘しておりますけれども、この点についても伺いたいと思います。","respondent":"藤田都市環境部長","answer":"当時の飛行機と現在の飛行機は性能が大分違っておりまして、国のほうからの説明でも、騒音の大きさ、レベルについては大分異なると聞いてあります。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問","question":"私は大阪の伊丹空港に行って、直接、肌で感じて耳で聞いて、現地の住民に伺いましたが、そんな被害では全くありません。過去の取り組みにも学んで、国に反対することが、この計画をとめる力になるとはなぜ思えないのか、この点を伺いたいと思います。","respondent":"藤田都市環境部長","answer":"これに加えることを、地域の皆様方に環境影響に配慮した方策として何ができるのか、これを求めてきていたところです。当時も現在も引き続き、新たな技術革新等を踏まえながら、さらなる影響の軽減に努めていく姿勢には変わりございません。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、国に反対することがこの計画をとめる力になるとはなぜ思わないのかと、その理由を改めて伺いたいと思います。そうした声は届いていないのか、伺いたいと思います。","respondent":"藤田都市環境部長","answer":"フェーズ２といった説明会等の中のニュースレターの中でも、様々な地域の声という形で載せさせていただいている記事を国が発行しているものです。国としては検討いたしまして、品川区のエリアで何をやってくれるのか、これについて先般８月に国が示したところです。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"区民による反対運動も広がっております。濱野区長の抜本的な姿勢の転換を求めて質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"松永委員","kind":"質問","question":"品川区内には５２カ所の避難所があると承知しておりますが、避難所、こうした多くの避難場所がどういう役割を果たしているのか伺いたいと思います。そのことにつきまして、区民の方への周知はどのように行っているのか、あわせて伺います。","respondent":"曽田災害対策担当部長","answer":"避難場所のそれぞれの役割についてお答えいたします。区民の方への周知につきましては、地域における防災協議会や防災訓練などにおいて説明を行い。","id":"exchange-078"},{"speaker":"松永委員","kind":"提案","question":"そこで、この『わが家の防災ハンドブック』を、町会・自治会や、各自で行っている訓練や総合防災訓練などで活用してみてはいかがでしょうか。もちろん、荷物になるとの批判の声も出てくると思いますが、ぜひ年に１回、訓練だけでもと思うので、いかがか尋ねました。","respondent":"曽田災害対策担当部長","answer":"これを利用して啓発活動を行ったり、あるいは町会・自治会での勉強会での教材ということで、いろんな活用をしております。総合防災訓練やしながわ防災学校においても配布しておりまして、今後とも様々な機会を捉え、配布・活用していきたいと考えております。","id":"exchange-079","title":"町会・自治会支援"},{"speaker":"松永委員","kind":"確認","question":"次に、ペットの避難の仕方について伺いたいと思います。そのマニュアルについて、町会・自治会、消防署、消防団、獣医師会などとの連携についてもあわせて伺いたいと思います。","respondent":"曽田災害対策担当部長","answer":"ペットの避難につきましては、個別のマニュアルはありません。関係機関との連携についてですが、ペットの治療といったことについて定めているところであります。","id":"exchange-080","title":"町会・自治会支援"},{"speaker":"松永委員","kind":"質問","question":"そこで、品川区ではこうした同行避難についてどのような考えを持っているのか伺いたいと思います。今後どのようにされていくのかもあわせて伺います。","respondent":"曽田災害対策担当部長","answer":"ペットの同行避難に関する環境省の見解につきましては、全くそのとおりだと考えています。現在、避難所連絡会議等におきまして、引き続きペットの同行避難について普及してまいりたいと考えているところであります。","id":"exchange-081"},{"speaker":"松永委員","kind":"質問","question":"関連してペットの同行避難と同伴避難について伺いたいと思います。この同行避難ができる避難所、また同伴避難ができる避難所について、品川区には何カ所あるのか伺いたいと思います。","respondent":"曽田災害対策担当部長","answer":"ペットの同行避難に関する記載をしているのは全部で９カ所、冨士見台中学校、ウェルカムセンター原の９カ所です。同伴避難については、明確に定めている避難所はございません。","id":"exchange-082"},{"speaker":"松永委員","kind":"質問","question":"同行避難を勧めるという立場で、現在、同行避難と同伴避難もあわせた防災訓練というものは行われているのでしょうか。もし行われていなければ、ぜひ必要ではないかと考えておりますが、いかがか尋ねました。","respondent":"曽田災害対策担当部長","answer":"これまでのところ、防災訓練において同行避難といったことは実施しておりませんが、マニュアルを具体化する必要性もございまして、今後の実施を働きかけていきたいと考えております。","id":"exchange-083"},{"speaker":"松永委員","kind":"質問・要望","question":"政府は２０１７年度以降、業界団体に安全確認の試験実施を求め、難しいと考えております。その姉妹都市、友好都市の関係はどのように行われているのか伺いたいと思います。","respondent":"曽田災害対策担当部長","answer":"現在まだ入手は難しい状況ではありますけれども、熊本地震の例からも、災害時には乳幼児用の食料として非常に有効であると考えております。","id":"exchange-084"},{"speaker":"松永委員","kind":"確認","question":"品川区では現在、携帯電話の充電器についてですが、どのような考えを持っているのでしょうか。今後、連絡手段の一つとして必要だと考えますが、区のご見解をお伺いいたします。","respondent":"曽田災害対策担当部長","answer":"応急対策に必要と考えられる食料、飲料水、様々なニーズに対応した物資の確保に努めているところであります。やはり通信・連絡手段の一つとして重要だとは考えておりますが、自助の観点から、個人ごとに準備していただくようお願いしているところであります。","id":"exchange-085"},{"speaker":"松永委員","kind":"質問・要望","question":"ボランティアセンターが設置されるまでの流れについて伺います。何人体制で、またいつごろ、どの場所にボランティアセンターが設置されるのか伺います。","respondent":"曽田災害対策担当部長","answer":"区では、発災後２４時間を目安に、ボランティアの活動拠点となる災害時ボランティアセンターを中小企業センター内に設置する予定としております。それぞれの組織の中にボランティア部というのがございまして、それぞれの避難所における受け付け組織ということになっております。","id":"exchange-086"},{"speaker":"松永委員","kind":"質問","question":"品川区は、現時点での児童センター、またシルバーセンターについて、どのような考えを持っているのか伺います。将来を見据えた、こうした多世代交流施設をどのように取り組んでいかれるのか、伺いたいと思います。","respondent":"齋藤子ども未来部長、榎本福祉部長","answer":"平成２４年に児童センターのあり方検討会からの報告がございまして、あるいは委員ご提案の、こういったものは検討していきたいと思います。高齢者との交流の事業を児童センターでも様々実施してまいりましたが、仕組みをしながら… それから高齢者多世代交流支援施設の将来の取り組みですけれども、３０年後に４９.６％増加するという推計になってあります。","id":"exchange-087"},{"speaker":"松永委員","kind":"質問","question":"今後、品川区では、こうした、夕方１人で食事をしなければならない子どもたちの対策をどのように行っていかれるのか、あわせて伺います。そして、先日の文教委員会でも取り組みについて報告されておりますが、その内容について改めて伺いたいと思います。","respondent":"榎本福祉部長、齋藤子ども未来部長","answer":"高齢者人口動向の増減の状況、それから福祉施設の事業規模等の違い、さらには介護人材確保に対し需給動向などが大きな課題となっております。したがいまして、このようなモデル事業については、今… 子ども食堂、これは相互扶助で実施されることが基本ではありますが、区としてはコーディネーターの役割を果たすことができると考えています。","id":"exchange-088"},{"speaker":"松永委員","kind":"質問","question":"ブラインドサッカー会場の変更に当たり、品川区は今後どのように応援されていくのか、改めて伺います。あわせて、ブラインドサッカーの出前体験教室ですが、どれぐらいの方から依頼を受けて、どれぐらいの方が参加されたのか、改めて伺います。","respondent":"安藤文化スポーツ振興部長","answer":"会場は変更はしましたけれども、ブラインドサッカーの実績と成果を伴って、引き続き応援していくことには変わりはございません。少年野球連盟または少年サッカー連盟の保護者の皆さん、それからソフトバレーの皆さん、小学校のＰＴＡの皆さんからの依頼があります。","id":"exchange-089"},{"speaker":"松永委員","kind":"質問","question":"ブラインドサッカーは、情報の８割を得ている視覚を閉じた状態でプレーするスポーツであり、この出前体験教室が必要だと考えます。品川区では、他の障害者スポーツについて、どのように応援されているのか、現況について、また今後の展開について伺いたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"そして、総合体育館、戸越体育館では、障害者の方々に対するスポーツ教室、または通年を利用してできるフリー利用も実施させていただいています。スポレクの方と一緒に、みんなで障害者とともにスポーツをということで、グランドゴルフを実施しています。","id":"exchange-090"},{"speaker":"松永委員","kind":"質問・要望","question":"楽しさや難しさなど肌で感じることができますので、ぜひこうした体験を、もっと周知してほしいと求めました。最後に、障害者スポーツをより推進するためには指導者も必要だと思いますが、品川区の障害者スポーツの指導者の現況について伺います。","respondent":"安藤文化スポーツ振興部長","answer":"戸越体育館、実際に平成２４年から障害者の指導者の資格を自分たちで独自に学習をし資格を取得していただきまして、指導しています。去年においては、ユニバーサルマナー研修を受講しまして、障害者の方々への対応、スキルや知識の習得に努めて、資質の向上を目指しています。","id":"exchange-091"},{"speaker":"松永委員","kind":"質問","question":"今後、健常者、そして障害者の方が自然に触れ合える環境を目指し、東京オリンピック・パラリンピックを盛り上げるためにもよろしくお願いいたします。以上で私からの質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"あべ委員","kind":"質問・要望","question":"子育てするなら品川区、企画部ならびに子ども未来部としてどう受けとめているのでしょうか。背景をどのように分析し、どのような施策を打とうとしているのでしょうか、答えるよう求めました。","respondent":"中山企画部長、齋藤子ども未来部長","answer":"ここの部分が当初の見込みより上回っているという状況で、これは年少人口を含めて、全体の人口増にもつながっているです。そのようなことを分析しながら、区全体の施策も考えていきたいと考えています。 間取りの大きいところに行ったり、ちょっと収入が増えたので品川区に来たりというやりとり、人口の動態・流動性はあるのだろうと考えています。それで、それを踏まえた待機児対策も見つめなければならないと考えております。","id":"exchange-093"},{"speaker":"あべ委員","kind":"質問・要望","question":"５年前の一般質問で、保育園の申し込み率を尋ねたところ、現在の保育園申し込み率は何％となっているでしょうか。今後何％程度まで伸びていくと区では推計しているか尋ねました。","respondent":"齋藤子ども未来部長","answer":"今後２％ずつ平成３８年まで増えていくのかもしれないというふうな推計はしておるところです。その根拠が、一定程度の歩どまりもあると考えておりますので、明確な数値ということをお示しすることはできないと考えております。","id":"exchange-094"},{"speaker":"あべ委員","kind":"質問・要望","question":"区内には、無認可保育園が何施設あり、何人程度の子どもが在籍しているのでしょうか。品川区では無認可保育園に対して、運営費補助や保育士研修等、何らかの施策を講じているのでしょうか、示すよう求めました。","respondent":"齋藤子ども未来部長","answer":"支援ですが、このほかの運営費補助の支援のほかでは、保育士のパートの方・非常勤の方に対する保育士資格の取得支援ということで。あわせて、区が行う研修あるいは私立保育園の保育士を対象とした保育士の方への研修にもお声がけをしています。","id":"exchange-095"},{"speaker":"あべ委員","kind":"質問","question":"ただ、２１４人中１９６人、助成が行われていないということですが、無認可保育園が品川区の保育に果たしている役割は、決して小さくないと考えます。品川区でも、一定の要件のもとに助成を検討すべきだと考えますが、いかがか尋ねました。","respondent":"齋藤子ども未来部長","answer":"区といたしましては、やはり保育の質を守るということを、１つ大きな原則と考えております。少し保育の質に欠けた施設が整備されるのではないかという懸念もありますので、当面は、無認可保育園に対する助成というものは考えておりません。","id":"exchange-096"},{"speaker":"あべ委員","kind":"質問","question":"次に、ネウボラネットワークについて伺いたいと思います。相談時に１万円分の子育てギフトカタログが区からプレゼントされるということで、その後、成果を感じるところがあれば説明を求めました。","respondent":"西田健康推進部長","answer":"実施した期間が短うありますので、即、これがネウボラ相談の効果というふうに判断するのは時期尚早と思います。今後、引き続き効果検証を続けていきたいと考えています。","id":"exchange-097"},{"speaker":"あべ委員","kind":"質問・要望","question":"以前も要望いたしましたように、やはり週末の開催を検討していただきたいということをお願いして、後でご答弁もお願いいたします。自己負担を下げて利用しやすくしたり、より必要な方に届く仕組みをさらに検討すべきではないかと考えますが、いかがか尋ねました。","respondent":"西田健康推進部長、齋藤子ども未来部長","answer":"この４,０００円というのが、非常に、この年代の金銭感覚とかけ離れているとは考えにくいところがあります。まだこれからの実施ですので、事業実施をする中で評価しまして、研究させていただきたいと思っているところです。 今年度４月から始めまして、累計で１７名、平均７時間のご利用です。今後、周知を含め、実績を踏まえ、利用数の増につきましては検討してまいります。","id":"exchange-098"},{"speaker":"あべ委員","kind":"質問・要望","question":"使っている方はその金額に満足して使っているわけですから、ちょっとそれだけでは不十分ではないかと思います。時間が迫ってまいりましたが、最後に医療的ケアについてお伺いしたいと思います。","respondent":"榎本福祉部長","answer":"それで、手帳の申請や療育のサービスの相談については障害者福祉課で対応しています。品川区としましては、平成２７年度から児童発達支援事業所の運営費の補助の事業を開始いたしまして、いろいろと事業者の誘致を図っているところです。","id":"exchange-099"},{"speaker":"あべ委員","kind":"質問・要望","question":"法改正もされましたので、今後、区の障害福祉計画にもきちんと数値目標を盛り込んで対応を強化してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"筒井委員","kind":"質問・要望","question":"そこで、品川区としてこの不十分さを解消するための、以下６点の要望・質問を国に対し行うべきと考えます。試験飛行を行うべき、大規模教室型説明会を行うべきと国に対し要望すべきですが、いかがか尋ねました。","respondent":"藤田都市環境部長","answer":"ＳＯ２、浮遊粒子状物質あるいはＣＯ２のうち、影響は限定的であるという説明を国から受けているところです。都との羽田空港の機能強化については、これまでも密に連携をとって対応しています。","id":"exchange-101"},{"speaker":"筒井委員","kind":"質問・要望","question":"ここで自衛官ＯＢの危機管理担当部長にお聞きしたいのですけれども、２０００年代から海外で５件、テロの危険性はどうお考えになっているでしょうか。テロによる爆破で航空機が品川区に墜落した場合の区の対応はどうお考えか尋ねました。","respondent":"藤田都市環境部長","answer":"時間の変更等の話については、可能かどうかも含めた部分になりますけれども、こうした声があったということを伝えていきたいと考えています。未然防止にしっかりと取り組むことが大切であり、しっかりと対応を、航空会社のほうでとっているところです。","id":"exchange-102"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはり一番被害をこうむるのは品川区でありますので、品川区長である濱野区長も出席すべきと考えますが、いかがでしょうか。８月２３日の行財政改革特別委員会で、結果はどうなりましたでしょうか示すよう求めました。","respondent":"藤田都市環境部長","answer":"先般の行財政改革特別委員会の中でもお話ししたとおり、国のほうにはそうした機会はないかということでお話をしています。区としては、特にこの会を通じなくても、国とは別に太いパイプがありますので、こうした中でこれまでもしっかりと国にお話をしてきているところです。","id":"exchange-103"},{"speaker":"筒井委員","kind":"質問・要望","question":"はっきりと区民の方に目に見える形で、そうした会議形式のもの、機関を設置していただきたいと考えております。協議会の設置についていかがお考えでしょうかということを、まず１点お伺いするのと、区のご見解を説明するよう求めました。","respondent":"藤田都市環境部長","answer":"影響を受ける区との連携の部分ですけれども、大田区・港区・目黒区といった近隣の区と勉強会を設けるなど、これまでも行ってきたところです。近隣の区との連携、それから国とのつながりといったものをとりながら、対応をとってまいりたいと考えています。","id":"exchange-104"},{"speaker":"筒井委員","kind":"質問・要望","question":"良好な景観の確保・創出の３つの理由から、なくしていく、すなわち無電柱化を推進すべきと考えます。そこで伺います。","respondent":"松代防災まちづくり部長","answer":"今後、無電柱化を行う具体的な予定とのことですが、平成３１年度までの完成を目指して進めております。補助２０５号線については、今後は原踏切から補助２９号線までの未整備区間を予定しております。","id":"exchange-105"},{"speaker":"筒井委員","kind":"質問・要望","question":"今後とも、ぜひとも積極的に無電柱化を推進していっていただきたいと考えております。そして、無電柱化推進に対する今後の区の意気込みを示すよう求めました。","respondent":"松代防災まちづくり部長","answer":"電線類企業者で構成される「無電柱化低コスト手法の技術的検証に関する委員会」を平成２６年に設置しまして、無電柱化のさらなる整備促進に向け。さらに、オリンピック・パラリンピック開催に向け、競技会場周辺の無電柱化事業を平成３１年度までに完了する予定です。","id":"exchange-106"},{"speaker":"筒井委員","kind":"質問・要望","question":"そこで、目黒川や運河をよりきれいに美しくするために、水質改善を行うべきと考えます。このカキ殻を利用した水質浄化の効果を検証し、将来の実施に向けるべく、このような水質浄化実験を行ってみてはいかがか尋ねました。","respondent":"松代防災まちづくり部長","answer":"目黒区とは、目黒川環境整備促進流域三区連絡会で連携しており、今回の実験結果を提供いただく予定となっております。水質改善に対して効果があると確認できれば、区としても導入等、いろいろと研究・検討してまいります。","id":"exchange-107"},{"speaker":"筒井委員","kind":"質問・要望","question":"目黒区で得られたデータを品川区においてもしっかりと反映していっていただきたいと考えております。効果があれば運河でも行えると考えておりますけれども、カキ殻の水質浄化を運河でも行うということはいかがでしょうか示すよう求めました。","respondent":"松代防災まちづくり部長","answer":"連絡会として毎年、東京都に対して、目黒川の水質改善に対する要望活動を実施しておるところです。次に、運河の水質等につきまして、河川から流れ込む水や下水処理の影響を大きく受けるものと認識しております。","id":"exchange-108"},{"speaker":"筒井委員","kind":"質問・要望","question":"昭和５０年代から、東京都に要望されているということですけれども、相当な時間がかかるのだと改めて実感いたしました。そうした生物が繁殖しやすいような環境、ビオトープのような環境をぜひとも検討していただいて、その点についてどうお考えか尋ねました。","respondent":"松代防災まちづくり部長","answer":"一昔前と比べて、少しではありますけれども、よくなってきている証左とも認識しております。そういったことも少し視野に入れる可能性というのはありますが、目黒川ではなかなか難しい、困難であると考えておるところです。","id":"exchange-109"},{"speaker":"筒井委員","kind":"質問・要望","question":"国会の衆参両院では、国民の信任を受け、憲法改正に前向きな自民党・公明党・日本維新の会などの、いわゆる改憲勢力が３分の２を占めております。憲法の教育が行われているかとは思われますが、具体的にどのような内容なのか、どの学年で何時間程度行われているかを示すよう求めました。","respondent":"本城教育次長","answer":"それから７年生におきましては、全部で８時間ですけれども、我が国の民主政治のあらましというようなもので授業を行っているところです。９年生においては、全部で４０時間ということで、より詳細な形で９年生で授業を行っているところです。","id":"exchange-110"},{"speaker":"筒井委員","kind":"質問","question":"９年生で４０時間ということなのですけれど、私は教科書も見させていただきましたけれども、あれを４０時間で十分なのかということを改めてお聞きしたいのと、９年生の内容、どのようなスタイルで、教育の仕方、教え方をどのようにやられているのか、わかり得る範囲で説明するよう求めました。","respondent":"本城教育次長","answer":"４０時間ということで授業を行っているところですが、憲法についてもかなり重視して、そのような時間を確保して授業を行っているものです。子ども同士で発表し合ったり、いろいろする、そんな活動も含めた憲法の授業になっているところです。","id":"exchange-111"},{"speaker":"筒井委員","kind":"質問","question":"現実味を帯びてきた憲法改正について、今の公民等、学校で教えている授業にどのような影響と、またどのような対応を考えているのでしょうか。発表会ということがありましたけれども、ディベート形式などの討論会などは行う予定なのでしょうか、その点を示すよう求めました。","respondent":"本城教育次長","answer":"学校教育の中で国の学習指導要領ですとか、区で言えば、小中一貫教育要領に基づいた内容で教育を行っているところです。それと、あとディベート等ですが、ディベート等の手法も活用して、生徒同士の動議を通じて、より理解が深まるような授業も、その中で活用しています。","id":"exchange-112"},{"speaker":"筒井委員","kind":"質問","question":"今後の影響というのをお聞きしたのですけれど、それをいま一度示すよう求めました。","respondent":"本城教育次長","answer":"憲法改正の動向等の影響ということに関しましては、ただいま申し上げましたように、学校教育の中では、学習指導要領等に即して、現実の憲法の内容について教育をするということで、そのような形の教育を行っていくという立場です。","id":"exchange-113"},{"speaker":"筒井委員","kind":"質問・要望","question":"問題点、そうしたことを多様な方法でもって、今の生徒たちに教育していってほしいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"吉田委員","kind":"質問","question":"一応、２０１５年までの事業にこれを充てるとしたわけですから、２０１５年決算のこの時期、大変ふさわしいかと思います。それから、あわせて議会に対しての説明も必要と考えますが、そのことについて伺います。","respondent":"秋山財政課長","answer":"平成２３年度から平成２７年度までであるということ、その特別区民税の特例期間、何らかのお知らせをしていくということは必要であると考えています。","id":"exchange-115"},{"speaker":"吉田委員","kind":"質問","question":"地方財政法第７条１項の解釈も含めて伺いたいと思います。この考え方というのは、なかなか納得しがたいのではないかと思うのですが、その辺についての見解も伺います。","respondent":"秋山財政課長","answer":"医療給付の支出額が見込みを下回ったということで３億円の不用額が出ていたり、児童福祉費では、３億５,０００万円の不用額等々が出ておるものです。","id":"exchange-116"},{"speaker":"吉田委員","kind":"質問・要望","question":"いつも求めると予算がないと言われるような方たちにとっては、なかなか納得がいかないのではないかということで、質問させていただきました。ところが、このたび、ある施設で虐待が起きてしまったという事例を伺いました。","respondent":"榎本福祉部長","answer":"利用者全体への説明と謝罪を行い、それから法人内の苦情解決の第三者委員会等へ報告を行い、法人内の理事会・評議員会の報告等も行ったところです。最終的には、一番その暴言が多かった方については、みずから退職したという形になってあります。","id":"exchange-117"},{"speaker":"吉田委員","kind":"確認","question":"一番、暴言が多かった方がみずから退職ということで、これは処分という形ではなくて依願退職ということなのでしょうか。その辺について確認したいと求めました。","respondent":"榎本福祉部長","answer":"実際の申し立てについては、事実関係をやっていく中では、主にお１人の方という形で事実関係が確認されたところです。ご本人は依願退職という形で退職したという形です。","id":"exchange-118"},{"speaker":"吉田委員","kind":"質問","question":"依願退職ということでいいのでしょうか、何か変な聞き方ですけれども、何か処分みたいなことはなかったのでしょうか。改めて伺います。","respondent":"榎本福祉部長","answer":"改善指導等の報告の中でも求めたところなのですけれども、やはり事実関係がはっきり全部わかる前に依願退職を認めたという事は、遺憾であります。それを法人側が認めてしまったということで、その後の調査等に若干支障が出ているという形です。","id":"exchange-119"},{"speaker":"吉田委員","kind":"質問","question":"本当に事実かどうか伺いたいだけなのですけれど、当人の訴えがあったにもかかわらず受け入れてもらえずに、このような事実はあったのでしょうか。依願退職については法人のほうで、もう既に処理してしまったということで、もう区としては口を出せないと理解してよろしいのか尋ねました。","respondent":"榎本福祉部長","answer":"調査にいろいろと時間がかかりますので、その間に東京都のほうからの連絡で、区がすぐに調査に入ったという形です。それはそれぞれ法人の中でそのときの状況等を見ながらという形ですけれども、今回については、遺憾であるという形での改善指導を行ったところです。","id":"exchange-120"},{"speaker":"吉田委員","kind":"質問","question":"聞きたいのですけれど、指定管理者の指定の選考基準の評価のときには、こういう事例を起こしたことはどのような評価になるのでしょうか。ただ、もしそういうことにかかわった法人が指定管理のときには、どういう評価になるのか、無関係とは思えないのですけれども、いかがか尋ねました。","respondent":"榎本福祉部長","answer":"今回は、区立の施設ではなかったという形ですけれども、指定管理者の部分については、やはり一定の指定の更新のときの基準としては、中身等、どう対処したか、どう連絡体制をとったかという形では、それぞれ影響する可能性があると考えております。","id":"exchange-121"},{"speaker":"吉田委員","kind":"質問・要望","question":"これらは本来、この手引で初めて求められたことではなくて、それ以前からも必要だったものが、もう一回、確認せよということだと理解しております。現在、何施設あるか、把握していらっしゃったら教えてほしいと求めました。","respondent":"榎本福祉部長","answer":"そういった中で、実際には対応の手引と同じ、区も引き続きこういう対応の手引等を作成しまして、研修と周知等に、同じ内容で努めているところです。実際に、区内では同じレベルを保っていくように努めているところです。","id":"exchange-122"},{"speaker":"吉田委員","kind":"質問・要望","question":"昨年の決算の総括質疑でも求めたのですが、例えば障害者虐待防止法や行政不服審査法に詳しい学者や弁護士、その点についての見解を改めて伺います。この件が、この事件において、十分機能したと評価しているかどうかについても伺いたいと思います。","respondent":"榎本福祉部長","answer":"第三者的機関の必要性ですけれども、実際に今回は差別解消法の職員対応要領の中で、相談先等の窓口を置いているところです。関係者の聞き取りもしたほか、都と同行して調査も行ったという形で、十分その役割は果たしたと考えております。","id":"exchange-123"},{"speaker":"吉田委員","kind":"質問・要望","question":"当初予算１,６００万円に対して、決算５８万円余り、この当初事業計画の内容を伺いたいと思います。音が反響し合うなど、そういう検証は入っているのか、それもあわせて伺います。","respondent":"藤田都市環境部長","answer":"区としての対応を決めていくということで、昨年執行しなかった分、また今年度の予算に計上しているものです。通常の、例えば建物の屋上であるとか、そういったところに設置し測定するといったものを計上したものです。","id":"exchange-124"},{"speaker":"吉田委員","kind":"質問・要望","question":"国土交通省に計画を白紙見直しすべきという要望書を提出いたしました。国土交通省にリスク評価を求め、区として意見を募るぐらいの姿勢は必要と考えますが、いかがか尋ねました。","respondent":"藤田都市環境部長","answer":"品川区として、どんなことができるのかというようなことを国に求め、８月にその答えをいただいたところです。さらに何ができるのか、もう少しはっきりわかるように調整を進め、国の説明を求めていきたいと思ってあります。","id":"exchange-125"},{"speaker":"吉田委員","kind":"質問・要望","question":"国の評価とあわせてどう判断するかというのを区民に示すべきではないかとお尋ねしましたので、その辺をもう一回伺いたいと思います。人口密集地とでは、リスクは明らかに品川区のほうが高いと考えますが、その点について見解を伺います。","respondent":"藤田都市環境部長","answer":"区として懸念される事項等を申し伝える中で、今回の８月における環境影響等に配慮した方策の品川区バージョンというものを示してもらったものです。","id":"exchange-126"},{"speaker":"吉田委員","kind":"質問","question":"よろしくお願いします。品川・生活者ネットワークとしての質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-127"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"しかし、将来の人口構造の変化、法人住民税国税化による財政調整制度への影響などの動向を見据えつつ、区民サービスのさらなる充実を求めます。品川区の来年度の予算、施策に実現されることを要望し、平成２７年度品川区各会計歳入歳出決算を認定いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-128"},{"speaker":"たけうち委員","kind":"提案","question":"全ての街路灯のＬＥＤ化５年計画をスタートするなど、様々な分野で、品川区議会公明党の提案を踏まえた施策の充実が図られました。我が会派の委員が提案・要望した中で、区の各実施事業に十分反映されますよう要望いたしまして、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-129"},{"speaker":"飯沼委員","kind":"提案","question":"４年後の東京オリンピック・パラリンピックの成功や機運醸成のため、誰もが日頃から気軽に、文化・スポーツに親しめる環境整備を求めます。以上、区政の転換を求め、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-130"},{"speaker":"大倉委員","kind":"提案","question":"今後もＩＣＴ化による事務の効率化、情報共有、情報の見える化など、区政運営・財政運営のさらなる効率化を求めます。区民一人ひとりが安全に安心して住み続けることのできる長期的・総合的なまちづくり推進を要望して、民進党・無所属クラブの意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問・要望","question":"福井県の教育のように、確かな学力を子どもに身につけさせ、社会で生き抜いていける教育制度を早急につくっていただきたい。以上で、維新・無所属品川の意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"田中委員","kind":"提案","question":"このお金の扱いについては、地方財政法第７条１項に求められる基金の積み立て以外は、弱い立場にいる人々のために使われることを強く要望します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-133"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/678897?Template=document&Id=1432#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":113990,"voices":296}}]);
